HSK6_STORIES_40 = [
    (11, '浩瀚宇宙中的黑洞探索', 'Khám phá lỗ đen trong vũ trụ bao la', 'astrophysics', 'Vật lý thiên văn', '🌌', 5, 'Khám phá thiên thể bí ẩn có lực hấp dẫn vô song giúp kiểm chứng thuyết tương đối và mở rộng biên giới hiểu biết vũ trụ.', [('黑洞是广义相对论预言的最极端天体之一，其强大无匹的引力场使得包括光线在内的任何物质都无法逃逸。', 'Hēidòng shì guǎngyì xiāngduìlùn yùyán de zuì jíduān tiāntǐ zhī yī, qí qiángdà-wúpǐ de yǐnlìchǎng shǐde bāokuò guāngxiàn zài nèi de rènhé wùzhì dōu wúfǎ táoyì.', 'Lỗ đen là một trong những thiên thể cực đoan nhất mà thuyết tương đối rộng dự đoán, với trường hấp dẫn vô song khiến mọi vật chất kể cả ánh sáng đều không thể thoát khỏi.'), ('长期以来，黑洞由于完全不发光而隐匿于虚空之中，天文学家只能通过观测其周围伴星的轨道摄动来间接推断其存在。', 'Chángqī yǐlái, hēidòng yóuyú wánquán bù fāguāng ér yǐnnì yú xūkōng zhī zhōng, tiānwénxuéjiā zhǐ néng tōngguò guānxiè qí zhōuwéi bànxīng de guǐdào shèdòng lái jiānjiē tuīduàn qí cúnzài.', 'Suốt thời gian dài, do hoàn toàn không phát sáng nên lỗ đen ẩn nấp trong hư không, các nhà thiên văn học chỉ có thể gián tiếp suy đoán sự hiện diện của nó qua nhiễu loạn quỹ đạo các sao đồng hành xung quanh.'), ('事件视界望远镜项目通过统筹全球多台射电望远镜协同作业，成功捕获了人类历史上首张超大质量黑洞的高清轮廓照片。', 'Shìjiàn shìjiè wàngyuǎnjìng xiàngmù tōngguò tǒngchóu quánqiú duō tái shèdiàn wàngyuǎnjìng xiétóng zuòyè, chénggōng bǔhuò le rénlèi lìshǐ shàng shǒuzhāng chāodà zhìliàng hēidòng de gāoqīng lúnguò zhàopiàn.', 'Dự án Kính viễn vọng Chân trời Sự kiện thông qua phối hợp nhiều kính thiên văn vô tuyến trên toàn cầu tác chiến đồng bộ đã chụp thành công bức ảnh đường nét lỗ đen siêu khối lượng đầu tiên trong lịch sử nhân loại.'), ('这一里程碑式的科技壮举，不仅坚实印证了爱因斯坦引力理论在极端物理环境下的卓越准确性，更为探究时空本质铺平了道路。', 'Zhè yí lǐchéngbēi shì de kējì zhuàngjǔ, bùjǐn jiānshí yìnzhèng le Àiyīnsītǎn yǐnlì lǐlùn zài jíduān wùlǐ huánjìng xià de zhuóyuè zhǔnquèxìng, gèng wèi tànjiū shíkōng běnzhì pūpíng le dàolù.', 'Kỳ tích công nghệ mang tính cột mốc này không chỉ kiểm chứng chắc chắn tính chuẩn xác vượt trội của lý thuyết hấp dẫn Einstein dưới môi trường vật lý cực đoan mà còn mở đường cho việc khám phá bản chất của không - thời gian.'), ('在永无止境的科学探索征途上，人类正凭借智慧的光芒逐步驱散宇宙最深邃幽暗的谜团。', "Zài yǒng wú zhǐjìng de kēxué tànsuǒ zhēngtú shàng, rénlèi zhèng píngjiè zhìhuì de guāngmáng zhúbù qūsàn yǔzhòu zuì shēnsuì yōu'àn de mǐtuán.", 'Trên hành trình khám phá khoa học không hồi kết, loài người đang dựa vào ánh sáng trí tuệ để từng bước xua tan những bí ẩn sâu thẳm tối tăm nhất của vũ trụ.')], [('Đặc tính vật lý cốt lõi của lỗ đen được mô tả trong bài là gì?', ['Phát ra ánh sáng rực rỡ', 'Trường hấp dẫn cực mạnh khiến ngay cả ánh sáng cũng không thể thoát ra', 'Không có khối lượng'], 1, 'Trong bài có câu: 强大无匹的引力场使得包括光线在内的任何物质都无法逃逸.'), ('Làm thế nào mà các nhà khoa học chụp được bức ảnh lỗ đen đầu tiên trong lịch sử?', ['Phóng tàu vũ trụ bay vào trong lỗ đen', 'Phối hợp đồng bộ mạng lưới kính viễn vọng vô tuyến trên toàn cầu', 'Chụp bằng máy ảnh thông thường'], 1, 'Trong câu có viết: 事件视界望远镜项目通过统筹全球多台射电望远镜协同作业，成功捕获了首张高清照片.'), ('Thành tựu mang tính bước ngoặt này đã chứng minh điều gì?', ['Kiểm chứng tính chuẩn xác của lý thuyết hấp dẫn Einstein trong môi trường cực đoan', 'Bác bỏ hoàn toàn thuyết tương đối', 'Chứng minh vũ trụ không tồn tại thời gian'], 0, 'Trong câu có viết: 坚实印证了爱因斯坦引力理论在极端物理环境下的卓越准确性.')]),
    (12, '文明互鉴与多元文化共生', 'Giao lưu văn minh và cùng chung sống hòa hợp đa văn hóa', 'civilizations', 'Lịch sử & Văn minh', '🌍', 5, 'Sự giao thoa và học hỏi lẫn nhau giữa các nền văn minh là động lực then chốt thúc đẩy tiến bộ và hòa bình nhân loại.', [('人类历史的长卷生动表明，世界上没有任何一种文明能够孤芳自赏、脱离与其他文明的交流而独自繁盛。', 'Rénlèi lìshǐ de chángjuàn shēngdòng biǎomíng, shìjiè shàng méiyǒu rènhé yì zhǒng wénmíng nénggòu gūfāng-zìshǎng, tuōlí yǔ qítā wénmíng de jiāoliú ér dúzì fánshèng.', 'Cuộn tranh dài của lịch sử nhân loại chỉ rõ rằng trên thế giới không một nền văn minh nào có thể tự ngắm mình cô độc, thoát ly khỏi giao lưu với các nền văn minh khác mà tự mình phồn thịnh.'), ('不同民族在漫长岁月里孕育出的独特哲学思辨、审美传统与社会制度，皆是全人类共享的璀璨瑰宝。', 'Bùtóng mínzú zài màncháng suìyuè lǐ yùnyù chū de dútè zhéxué sībiàn, shěnměi chuántǒng yǔ shèhuì zhìdù, jiē shì quán rénlèi gòngxiǎng de cuǐcàn guībǎo.', 'Tư duy triết học, truyền thống thẩm mỹ và thể chế xã hội độc đáo mà các dân tộc sinh thành qua năm tháng đằng đẵng đều là những kho báu rực rỡ mà toàn nhân loại cùng chia sẻ.'), ('文明的差异不应当成为对立与冲突的借口，而恰恰是彼此启迪、取长补短的宝贵源泉。', 'Wénmíng de chāyì bù yīngdāng chéngwéi duìlì yǔ chōngtū de jièkǒu, ér qiàqià shì bǐcǐ qǐdí, qǔcháng-bǔduǎn de bǎoguì yuánquán.', 'Sự dị biệt giữa các nền văn minh không nên trở thành cái cớ cho đối đầu xung đột, mà chính là nguồn cội quý báu để soi sáng lẫn nhau và học hỏi bù đắp cho nhau.'), ('唯有秉持包容谦逊的态度开展平等对话，摒弃狭隘偏执的傲慢与偏见，才能消除隔阂、凝聚共识。', "Wéiyǒu bǐngchí bāoróng qiānxùn de tàidù kāizhǎn píngděng duìhuà, bǐngqì xiá'ài piānzhí de àomàn yǔ piānjiàn, cái néng xiāochú géhé, níngjù gòngshí.", 'Chỉ khi giữ vững thái độ khiêm nhường bao dung mở ra đối thoại bình đẳng, gạt bỏ sự ngạo mạn và định kiến hẹp hòi, ta mới có thể xóa tan ngăn cách và kết tinh đồng thuận.'), ('各美其美，美人之美，美美与共，方能共同开创人类命运共同体和睦繁盛的美好未来。', 'Gè měi qí měi, měi rén zhī měi, měiměi-yǔgòng, fāng néng gòngtóng kāichuàng rénlèi mìngyùn gòngtóngtǐ hémù fánshèng de měihǎo wèilái.', 'Mỗi bên tôn vinh cái đẹp của mình, đồng thời trân trọng cái đẹp của người khác để cùng chung sống hòa hợp, mới có thể cùng mở ra tương lai phồn vinh của cộng đồng chung vận mệnh nhân loại.')], [('Theo bài viết, một nền văn minh có thể đơn độc phát triển rực rỡ mà không cần giao lưu không?', ['Có thể, nếu đủ giàu mạnh', 'Không, không nền văn minh nào có thể tách rời giao lưu mà tự phồn vinh', 'Chỉ các nền văn minh lớn mới làm được'], 1, 'Trong câu đầu có viết: 没有任何一种文明能够孤芳自赏、脱离与其他文明的交流而独自繁盛.'), ('Thái độ đúng đắn trước sự khác biệt văn hóa giữa các quốc gia là gì?', ['Lấy đó làm lý do để gây chiến', 'Xem sự khác biệt là nguồn cảm hứng học hỏi bù trừ cho nhau và đối thoại bình đẳng', 'Đồng hóa mọi nền văn hóa thành một'], 1, 'Trong bài có câu: 文明的差异恰恰是彼此启迪、取长补短的宝贵源泉.'), ("Phương châm 'Mỗi bên tôn vinh vẻ đẹp riêng, trân quý vẻ đẹp của nhau' (各美其美，美人之美，美美与共) hướng tới mục tiêu gì?", ['Mở ra tương lai hòa mục, phồn vinh của cộng đồng chung vận mệnh nhân loại', 'Chia rẽ các liên minh quốc tế', 'Phục hưng chế độ phong kiến'], 0, 'Trong câu cuối có viết: 方能共同开创人类命运共同体和睦繁盛的美好未来.')]),
    (13, '传统中医药的现代科学实证', 'Chứng thực khoa học hiện đại của y học cổ truyền', 'tcm_science', 'Y học & Khoa học', '🌿', 5, 'Kết hợp tinh hoa y học phương Đông với hóa sinh phân tử và dược lý học đương đại mở ra hướng điều trị mới.', [('传统中医药学凝聚着中华民族数千年来同疾病作斗争的丰富经验与深邃智慧，是一座巨大的临床宝库。', 'Chuántǒng zhōngyīyàoxué níngjù zhe Zhōnghuá mínzú shù qiān nián lái tóng jíbìng zuò dòuzhēng de fēngfù jīngyàn yǔ shēnsuì zhìhuì, shì yí zuò jùdà de línchuáng bǎokù.', 'Y học cổ truyền Trung Hoa kết tinh kinh nghiệm phong phú và trí tuệ thâm sâu qua hàng ngàn năm đấu tranh với tật bệnh của dân tộc, là một kho tàng lâm sàng đồ sộ.'), ('然而在现代循证医学语境下，传统本草方剂往往面临有效成分不清、作用机理复杂的技术诘难。', "Rán'ér zài xiàndài xúnzhèng yīxué yǔjìng xià, chuántǒng běncǎo fāngjì wǎngwǎng miànlín yǒuxiào chéngfèn bùqīng, zuòyòng jīlǐ fùzá de jìshù jiénàn.", 'Tuy nhiên trong bối cảnh y học thực chứng hiện đại, các bài thuốc thảo dược truyền thống thường đối mặt với chất vấn kỹ thuật về hoạt chất chưa rõ và cơ chế tác động phức tạp.'), ('当代科学家运用色谱分离、分子药理学与系统生物学方法，成功从青蒿中提取出抗疟特效药青蒿素。', 'Dāngdài kēxuéjiā yùnyòng sèpǔ fēnlí, fēnzǐ yàolǐxué yǔ xìtǒng shēngwùxué fāngfǎ, chénggōng cóng qīnghāo zhōng tíqǔ chū kàngnüè tèxiàoyào qīnghāosù.', 'Các nhà khoa học đương đại vận dụng sắc ký tách chiết, dược lý học phân tử và sinh học hệ thống đã chiết xuất thành công hoạt chất artemisinin từ cây thanh hao hoa vàng đặc trị sốt rét.'), ('这一重大科学突破生动证明，借助现代前沿分析手段对古籍验方进行精准破译具有不可估量的临床价值。', 'Zhè yí zhòngdà kēxué tūpò shēngdòng zhèngmíng, jièzhù xiàndài qiányán fēnxī shǒuduàn duì gǔjí yànfāng jìnxíng jīngzhǔn pòyì jùyǒu bùkě-gūliàng de línchuáng jiàzhí.', 'Đột phá khoa học trọng đại này chứng minh sinh động rằng việc giải mã chuẩn xác các phương thuốc cổ phương nhờ công cụ phân tích hiện đại mang giá trị lâm sàng khôn lường.'), ('推动传统中医药与现代科技的深度交叉融合，将为全球公共卫生事业提供独具东方智慧的创新方案。', "Tuīdòng chuántǒng zhōngyīyào yǔ xiàndài kējì de shēndù jiāochā rónghé, jiāng wèi quánqiú gōnggòng wèishēng shìyè tígōng dújù dōngfāng zhìhuì de chuàngxīn fāng'àn.", 'Thúc đẩy giao thoa sâu sắc giữa y dược học cổ truyền và công nghệ hiện đại sẽ cung cấp phương án đổi mới mang đậm trí tuệ phương Đông cho sự nghiệp y tế công cộng toàn cầu.')], [('Thách thức lớn nhất của thuốc y học cổ truyền khi tiếp cận y học thực chứng hiện đại là gì?', ['Không có người mua', 'Khó khăn trong việc xác định hoạt chất chính xác và làm sáng tỏ cơ chế tác dụng', 'Giá thành quá rẻ'], 1, 'Trong bài có câu: 传统本草方剂往往面临有效成分不清、作用机理复杂的技术诘难.'), ('Ví dụ điển hình nhất về việc chiết xuất hoạt chất hiện đại từ thảo dược cổ truyền là gì?', ['Sản xuất cồn sát khuẩn', 'Chiết xuất artemisinin (thanh hao tố) chữa sốt rét từ cây thanh hao hoa vàng', 'Chế biến trà giải nhiệt'], 1, 'Trong câu có viết: 成功从青蒿中提取出抗疟特效药青蒿素.'), ('Mục tiêu chiến lược của việc kết hợp y học cổ truyền với khoa học hiện đại là gì?', ['Cung cấp giải pháp đổi mới sáng tạo mang đậm trí tuệ phương Đông cho y tế công cộng toàn cầu', 'Xóa bỏ hoàn toàn y học phương Tây', 'Giữ kín bí quyết gia truyền không chia sẻ'], 0, 'Trong câu cuối có viết: 为全球公共卫生事业提供独具东方智慧的创新方案.')]),
    (14, '量子计算与未来算力跃迁', 'Điện toán lượng tử và bước nhảy vọt năng lực tính toán', 'quantum_computing', 'Công nghệ lượng tử', '💻', 5, 'Hiện tượng chồng chập và vướng víu lượng tử mang lại tốc độ xử lý cấp số nhân, mở ra kỷ nguyên giải mã siêu dữ liệu.', [('传统硅基计算机依赖二进制比特进行串行逻辑运算，但在逼近物理极限时遭遇了难以逾越的功耗与算力瓶颈。', 'Chuántǒng guījī jìsuànjī yīlài èrjìnzhì bǐtè jìnxíng chuànxíng luójí yùnsuàn, dàn zài bījìn wùlǐ jíxiàn shí zāoyù le nányǐ yúyuè de gōnghào yǔ suànlì píngjǐng.', 'Máy tính nền silicon truyền thống dựa vào các bit nhị phân để tính toán logic nối tiếp, nhưng khi tiệm cận giới hạn vật lý đã vấp phải nút thắt điện năng tiêu thụ và năng lực tính toán khó vượt qua.'), ('量子计算机利用微观粒子的量子叠加与纠缠特性，使量子比特能够同时处于多种状态的线性组合之中。', 'Liàngzǐ jìsuànjī lìyòng wēiguān lìzǐ de liàngzǐ diéjiā yǔ jiūchán tèxìng, shǐ liàngzǐ bǐtè nénggòu tóngshí chǔyú duō zhǒng zhuàngtài de xiànxìng zǔhé zhī zhōng.', 'Máy tính lượng tử tận dụng đặc tính chồng chập và vướng víu của các hạt vi mô, cho phép các qubit lượng tử tồn tại đồng thời trong tổ hợp tuyến tính của nhiều trạng thái.'), ('这种固有的并行处理能力，赋予了量子芯片在因子分解、复杂分子模拟与最优路径求解上的指数级加速优势。', 'Zhè zhǒng gùyǒu de bìngxíng chǔlǐ nénglì, fùyǔ le liàngzǐ xīnpiàn zài yīnzǐ fēnjiě, fùzá fēnzǐ mónǐ yǔ zuìyōu lùjìng qiújiě shàng de zhǐshùjí jiāsù yōushì.', 'Năng lực xử lý song song vốn có này đem lại cho chip lượng tử lợi thế gia tốc cấp số nhân trong phân tích thừa số nguyên, mô phỏng phân tử phức tạp và tìm lời giải đường đi tối ưu.'), ('攻克量子纠错编码并实现容错通用计算，是当下全球顶尖实验室展开白热化角逐的科技高地。', 'Gōngkè liàngzǐ jiūcuò biānmǎ bìng shíxiàn róngcuò tōngyòng jìsuàn, shì dāngxià quánqiú dǐngjiān shíyànshì zhǎnkāi bái-rè-huà jiǎozhú de kējì gāodì.', 'Chinh phục mã sửa sai lượng tử và đạt được điện toán chịu lỗi đa năng là cao điểm công nghệ mà các phòng thí nghiệm hàng đầu toàn cầu đang cạnh tranh quyết liệt.'), ('量子计算引发的算力跃迁，势必为新药研发、材料科学以及人工智能模型演进掀起颠覆性的产业革命。', 'Liàngzǐ jìsuàn yǐnfā de suànlì yuèqiān, shìbì wèi xīnyào yánfā, cáiliào kēxué yǐjí réngōng zhìnéng móxíng yǎnjìn xiānqǐ diānfùxìng de chǎnyè gémìng.', 'Bước nhảy vọt về năng lực tính toán do điện toán lượng tử kích hoạt chắc chắn sẽ tạo nên cuộc cách mạng công nghiệp mang tính đảo lộn trong nghiên cứu thuốc mới, khoa học vật liệu và phát triển mô hình AI.')], [('Nguyên lý cơ bản giúp máy tính lượng tử có tốc độ vượt trội là gì?', ['Dùng dây cáp quang siêu dẫn', 'Đặc tính chồng chập và vướng víu lượng tử cho phép xử lý song song khổng lồ', 'Chỉ chạy một tác vụ duy nhất'], 1, 'Trong bài có câu: 利用微观粒子的量子叠加与纠缠特性，使量子比特能够同时处于多种状态.'), ('Lĩnh vực nào sẽ hưởng lợi vượt bậc từ ưu thế tăng tốc cấp số nhân của chip lượng tử?', ['In văn bản', 'Phân tích thừa số nguyên, mô phỏng cấu trúc phân tử và giải toán tối ưu', 'Lưu trữ ảnh thông thường'], 1, 'Trong câu có viết: 在因子分解、复杂分子模拟与最优路径求解上的指数级加速优势.'), ('Ý nghĩa tương lai của bước nhảy vọt năng lực tính toán lượng tử là gì?', ['Gây tốn điện năng toàn cầu', 'Tạo nên cuộc cách mạng đảo lộn trong bào chế thuốc mới, khoa học vật liệu và AI', 'Làm hỏng hệ thống mạng cũ mà không có ích lợi'], 1, 'Trong câu cuối có viết: 势必为新药研发、材料科学以及人工智能模型演进掀起颠覆性的产业革命.')]),
    (15, '东方哲学的道法自然智慧', "Trí tuệ 'Đạo pháp tự nhiên' trong triết học phương Đông", 'philosophy', 'Triết học phương Đông', '☯️', 5, 'Tư tưởng Lão Trang đề cao sự thuận hòa, không khiên cưỡng, để con người tìm thấy tự do đích thực giữa quy luật vũ trụ.', [('道家哲学作为先秦诸子百家学说中的璀璨瑰宝，以其深邃玄妙的宇宙观奠定了东方思辨传统的基石。', 'Dàojiā zhéxué zuòwéi xiān-Qín zhūzǐ bǎijiā xuéshuō zhōng de cuǐcàn guībǎo, yǐ qí shēnsuì xuánmiào de yǔzhòu guān diàndì le dōngfāng sībiàn chuántǒng de jīshí.', 'Triết học Đạo gia với tư cách là viên ngọc sáng chói trong các học phái Bách gia chư tử thời Tiền Tần đã đặt nền móng cho truyền thống tư biện phương Đông bằng vũ trụ quan sâu xa huyền diệu.'), ('老子在《道德经》中提出人法地、地法天、天法道、道法自然，深刻阐释了宇宙运行的根本法则。', 'Lǎozǐ zài 《Dàodé Jīng》 zhōng tíchū rén fǎ dì, dì fǎ tiān, tiān fǎ dào, dào fǎ zìrán, shēnkè chǎnshì le yǔzhòu yùnxíng de gēnběn fǎzé.', "Lão Tử trong 'Đạo Đức Kinh' đã nêu ra 'Người thuận theo đất, đất thuận theo trời, trời thuận theo Đạo, Đạo thuận theo tự nhiên', giải thích sâu sắc quy luật vận hành căn bản của vũ trụ."), ('所谓无为而无不为，并非消极避世或无所事事，而是戒除主观妄动与盲目干预，顺应客观事物的内在规律。', 'Suǒwèi wúwéi ér wúbùwéi, bìng fēi xiāojí bìshì huò wúsuǒ-shìshì, ér shì jièchú zhǔguān wàngdòng yǔ mángmù gānyù, shùnyìng kèguān shìwù de nèizài guīlǜ.', "Cái gọi là 'Vô vi mà không gì không làm' không phải là trốn tránh thế sự tiêu cực hay ngồi không, mà là kiêng dè hành động mù quáng chủ quan, thuận theo quy luật nội tại của khách quan."), ('庄子所倡导的逍遥游境界，启示我们在面对世俗名缰利锁的束缚时，应当学会超越功利羁绊，回归精神自由。', 'Zhuāngzǐ suǒ chàngdǎo de xiāoyáoyóu jìngjiè, qǐshì wǒmen zài miànduì shìsú míngjiāng-lìsuǒ de shùfù shí, yīngdāng xuéhuì chāoyuè gōnglì jībàn, huíguī jīngshén zìyóu.', "Cảnh giới 'Tiêu Dao Du' mà Trang Tử cổ vũ gợi mở cho ta rằng trước sợi dây danh lợi trần tục trói buộc, cần học cách vượt lên trên rào cản công lợi để trở về với tự do tâm hồn."), ('在生态危机与精神内耗加剧的当代社会，汲取道法自然的东方智慧，能够为现代人抚平内心的焦虑浮躁。', 'Zài shēngtài wēijī yǔ jīngshén nèihào jiājù de dāngdài shèhuì, jíqǔ dào fǎ zìrán de dōngfāng zhìhuì, nénggòu wèi xiàndàirén fǔpíng nèixīn de jiāolǜ fúzào.', "Trong xã hội đương đại khi khủng hoảng sinh thái và hao tổn tinh thần gia tăng, tiếp thu trí tuệ 'Đạo pháp tự nhiên' có thể xoa dịu nỗi lo âu xốc nổi trong tâm người hiện đại.")], [('Mệnh đề cốt lõi của Lão Tử về quy luật vận hành vũ trụ là gì?', ['Con người chinh phục tự nhiên', 'Người thuận theo đất, đất thuận theo trời, trời thuận theo Đạo, Đạo thuận theo tự nhiên', 'Mọi sự vật tồn tại ngẫu nhiên'], 1, 'Trong bài có câu: 人法地、地法天、天法道、道法自然.'), ("Khái niệm 'Vô vi' (无为) trong triết học Đạo gia thực chất có ý nghĩa gì?", ['Lười biếng không làm gì cả', 'Tránh hành động mù quáng chủ quan, thuận theo quy luật phát triển nội tại của sự vật', 'Lẩn tránh trách nhiệm xã hội'], 1, 'Trong câu có viết: 戒除主观妄动与盲目干预，顺应客观事物的内在规律.'), ('Giá trị trị liệu tinh thần của tư tưởng Tiêu Dao Du đối với con người hiện đại là gì?', ['Vượt lên sự trói buộc của danh lợi công danh để tìm về sự tự do thanh thản của tâm hồn', 'Dạy cách kiếm tiền nhanh chóng', 'Khuyên con người cô lập bản thân'], 0, 'Trong câu có viết: 超越功利羁绊，回归精神自由，抚平内心的焦虑浮躁.')]),
    (16, '虚拟现实与人类感知重构', 'Thực tế ảo và sự tái định hình giác quan con người', 'virtual_reality', 'Khoa học nhận thức', '🕶️', 5, 'Môi trường mô phỏng siêu thực làm mờ ranh giới thực - ảo, đặt ra những suy ngẫm sâu sắc về bản chất của trải nghiệm và ý thức.', [('虚拟现实与空间计算技术的跨越式迭代，正在以不可逆转之势重塑人类感知客观世界的基本维度。', 'Xūnǐ xiànshí yǔ kōngjiān jìsuàn jìshù de kuàyuèshì diédài, zhèngzài yǐ bùkě-nìzhuǎn zhī shì chóngsù rénlèi gǎnzhī kèguān shìjiè de jīběn wéidù.', 'Sự nâng cấp nhảy vọt của công nghệ thực tế ảo và điện toán không gian đang tái định hình các chiều kích cơ bản của nhận thức con người về thế giới khách quan với đà không thể đảo ngược.'), ('高分辨率微显示屏配合毫米级头部追踪与触觉反馈手套，能够为沉浸者构筑出难辨真伪的拟真环境。', 'Gāo fēnbìanlǜ wēi xiǎnshìpíng pèihé háomǐ jí tóubù zhuīzōng yǔ chùjué fǎnkuì shǒutào, nénggòu wèi chénjìnzhě gòuzhù chū nán biàn zhēn-wěi de nǐzhēn huánjìng.', 'Màn hình vi mô độ phân giải cao kết hợp với tính năng theo dõi cử động đầu cấp milimet và găng tay phản hồi xúc giác có thể kiến tạo không gian mô phỏng chân thực đến khó phân biệt thật giả.'), ('从远程高难度外科手术仿真演练，到濒危古迹的跨时空沉浸式复原，技术正展现出惊人的实践价值。', 'Cóng yuǎnchéng gāonándù wàikē shǒushù fǎngzhēn yǎnliàn, dào bīnwēi gǔjì de kuà-shíkōng chénjìnshì fùyuán, jìshù zhèng zhǎnxiàn chū jīngrén de shíjiàn jiàzhí.', 'Từ diễn tập mô phỏng phẫu thuật ngoại khoa độ khó cao từ xa cho đến phục dựng di tích cổ nguy cấp xuyên không - thời gian, công nghệ đang thể hiện giá trị thực tiễn kinh ngạc.'), ('然而，当身心长期沉溺于近乎完美的数字虚境时，个体对现实物理世界的实体归属感可能会遭受潜移默化的侵蚀。', "Rán'ér, dāng shēnxīn chángqī chénnì yú jìnhū wánměi de shùzì xūjìng shí, gètǐ duì xiànshí wùlǐ shìjiè de shítǐ guīshǔgǎn kěnéng huì zāoshòu qiányí-mòhuà de qīnsí.", 'Thế nhưng, khi thân tâm chìm đắm lâu dài trong cảnh giới ảo kỹ thuật số gần như hoàn mỹ, cảm giác thuộc về thực thể đối với thế giới vật lý thực tế có thể bị ăn mòn âm thầm.'), ('在迎接数字化生存新浪潮的同时，保持对现实真实性的清醒审视，是捍卫人类主体性尊严的必答课题。', 'Zài yíngjiē shùzìhuà shēngcún xīn làngcháo de tóngshí, bǎochí duì xiànshí zhēnshíxìng de qīngxǐng shěnshì, shì hànwèi rénlèi zhǔtǐxìng zūnyán de bìdá kètí.', 'Trong lúc đón nhận làn sóng sinh tồn số hóa mới, giữ vững sự tỉnh táo nhận diện tính chân thực của hiện thực đời sống là câu hỏi bắt buộc để bảo vệ phẩm giá chủ thể của con người.')], [('Thiết bị nào giúp tạo nên trải nghiệm thực tế ảo khó phân biệt thật giả?', ['Màn hình tivi thông thường', 'Màn hình vi mô siêu nét, theo dõi chuyển động đầu milimet và găng tay phản hồi xúc giác', 'Kính cận thị'], 1, 'Trong bài có câu: 高分辨率微显示屏配合毫米级头部追踪与触觉反馈手套，构筑出难辨真伪的拟真环境.'), ('Ứng dụng thực tiễn giá trị của công nghệ VR được nhắc đến là gì?', ['Chơi game suốt ngày đêm', 'Mô phỏng phẫu thuật y khoa khó và phục dựng không gian di tích cổ nguy cấp', 'Thay thế việc ăn uống'], 1, 'Trong câu có viết: 从远程高难度外科手术仿真演练，到濒危古迹的跨时空沉浸式复原.'), ('Mối nguy tiềm ẩn khi con người đắm chìm quá mức trong không gian ảo là gì?', ['Mất hết tiền trong tài khoản', 'Cảm giác gắn bó và thuộc về thế giới vật lý thực tế bị ăn mòn', 'Thiết bị bị hỏng'], 1, 'Trong câu có viết: 对现实物理世界的实体归属感可能会遭受潜移默化的侵蚀.')]),
    (17, '古琴艺术与文人精神风骨', 'Nghệ thuật cổ cầm và cốt cách tinh thần văn nhân xưa', 'guqin_art', 'Âm nhạc & Cổ học', '🎼', 5, 'Thanh âm trầm ấm tĩnh tại của cây đàn bảy dây là phương tiện đối thoại nội tâm, biểu đạt tiết tháo thanh cao của kẻ sĩ.', [('古琴位列琴棋书画四艺之首，数千年来始终被视作中国古代文人士大夫砥砺操守、抒发幽思的雅乐圣器。', 'Gǔqín wèiliè qín-qí-shū-huà sìyì zhī shǒu, shù qiān nián lái shǐzhōng bèi shì zuò Zhōngguó gǔdài wénrén shìdàfū dǐlì cāoshǒu, shūfā yōusī de yǎyuè shèngqì.', 'Cổ cầm đứng đầu trong tứ nghệ Cầm - Kỳ - Thi - Họa, suốt hàng ngàn năm luôn được xem là nhạc khí thanh nhã thiêng liêng để giới văn nhân sĩ đại phu rèn giũa khí tiết và gửi gắm nỗi niềm u hoài.'), ('七弦古琴的音色深沉悠远、清微淡远，讲究大音希声的美学韵致与弦外之音的悠长意蕴。', 'Qī xián gǔqín de yīnsè shēnchén yōuyuǎn, qīng wēi dàn yuǎn, jiǎngjiu dàyīn-xīshēng de měixué yùnzhì yǔ xiánwài-zhīyīn de yōucháng yìyùn.', "Âm sắc của cây cổ cầm bảy dây trầm lắng vang xa, thanh tao đạm bạc, đề cao vận vị mỹ học 'đại âm hy thanh' cùng hàm ý sâu xa phía sau tiếng tơ đồng."), ('抚琴并非为了取悦听众，而是抚琴者借由指尖与丝弦的摩挲，与山川明月共鸣、与先贤圣哲进行深切的心灵独白。', 'Fǔqín bìng fēi wèile qǔyuè tīngzhòng, ér shì fǔqínzhě jièyóu zhǐjiān yǔ sīxián de mósā, yǔ shānchuān míngyuè gòngmíng, yǔ xiānxián shèngzhé jìnxíng shēnqiè de xīnlíng dúbái.', 'Gảy cầm không nhằm mua vui cho thính giả, mà là người chơi đàn mượn sự vuốt ve giữa đầu ngón tay và dây tơ để giao cảm cùng non sông trăng sáng, độc thoại sâu sắc với các bậc hiền triết.'), ('琴曲中所寄托的清正和雅与傲骨铮铮，生动诠释了士人阶层宁折不弯的精神品格与独立人格。', 'Qínqǔ zhōng suǒ jìtuō de qīngzhèng hé yǎ yǔ àogǔ-zhēngzhēng, shēngdòng quánshì le shìrén jiēcéng nìngzhé-bùwān de jīngshén pǐngé yǔ dúlì réngé.', 'Sự thanh chính hòa nhã cùng cốt cách ngạo nghễ kiên cường gửi gắm trong khúc nhạc giải thích sống động phẩm cách tinh thần thà gãy không cong của tầng lớp kẻ sĩ.'), ('静听一曲高山流水，不仅是一场听觉的纯化，更是浮华尘世中唤醒士人风骨的精神归宿。', 'Jìngtīng yì qǔ Gāoshān Liúshuǐ, bùjǐn shì yì chǎng tīngjué de chúnhuà, gèng shì fúhuá chénshì zhōng huànxǐng shìrén fēnggǔ de jīngshén guīsù.', "Tĩnh tâm lắng nghe khúc 'Cao Sơn Lưu Thủy' không chỉ là sự gạn lọc thính giác mà còn là chốn về tinh thần thức tỉnh cốt cách văn nhân giữa cõi trần phù hoa.")], [('Vị trí và ý nghĩa của cổ cầm trong đời sống văn nhân cổ đại là gì?', ['Dùng để hòa tấu ngoài chợ', 'Đứng đầu tứ nghệ, là nhạc cụ tao nhã giúp rèn luyện khí tiết và đối thoại nội tâm', 'Đồ chơi của trẻ con'], 1, 'Trong bài có câu: 位列琴棋书画四艺之首，被视作砥砺操守、抒发幽思的雅乐圣器.'), ('Mục đích cốt lõi của người gảy cổ cầm (抚琴) là gì?', ['Kiếm tiền bán vé', 'Không nhằm mua vui thính giả mà để giao cảm với non sông và độc thoại tâm hồn với thánh hiền', 'Làm ồn xung quanh'], 1, 'Trong câu có viết: 并非为了取悦听众，而是与山川明月共鸣、与先贤圣哲进行心灵独白.'), ("Khúc cầm 'Cao Sơn Lưu Thủy' gửi gắm phẩm chất gì của bậc trí thức xưa?", ['Tính tham lam danh vọng', 'Khí phách thà gãy không cong, trong sạch hòa nhã và nhân cách độc lập', 'Sự phục tùng quyền lực vô điều kiện'], 1, 'Trong câu có viết: 清正和雅与傲骨铮铮，宁折不弯的精神品格与独立人格.')]),
    (18, '循环经济与工业生态系统', 'Kinh tế tuần hoàn và hệ sinh thái cộng sinh công nghiệp', 'circular_economy', 'Kinh tế & Sinh thái', '🔄', 5, 'Chuyển từ mô hình khai thác - thải bỏ sang mạng lưới tái sinh khép kín, biến rác thải công nghiệp thành nguồn nguyên liệu quý.', [('传统工业文明长期奉行资源开采、产品制造、废弃丢弃的单向线性消费模式，造成了触目惊心的环境承载危机。', 'Chuántǒng gōngyè wénmíng chángqī fèngxíng zīyuán kāicǎi, chǎnpǐn zhìzào, fèiqì diūqì de dānxiàng xiànxìng xiāofèi móshì, zàochéng le chùmù-jīnxīn de huánjìng chéngzài wēijī.', 'Văn minh công nghiệp truyền thống lâu nay theo đuổi mô hình tiêu dùng tuyến tính một chiều: khai thác tài nguyên - chế tạo sản phẩm - vứt bỏ phế thải, gây ra khủng hoảng sức tải môi trường đến kinh hoàng.'), ('循环经济则彻底打破这一窠臼，主张在物质循环全生命周期内实现减量化、再利用与资源化再生。', 'Xúnhuán jīngjì zé chèdǐ dǎpò zhè yì kējiù, zhǔzhāng zài wùzhì xúnhuán quán shēngmìng zhōuqī nèi shíxiàn jiǎnliànghuà, zàilìyòng yǔ zīyuánhuà zàishēng.', 'Kinh tế tuần hoàn phá vỡ hoàn toàn khuôn mẫu cũ này, chủ trương đạt được giảm thiểu, tái sử dụng và tài nguyên hóa tái sinh trong toàn bộ vòng đời tuần hoàn vật chất.'), ('先进的工业共生网络能够促使某一企业的副产物与工业废热，精准转化为下游产业链的核心生产原料。', 'Xiānjìn de gōngyè gòngshēng wǎngluò nénggòu cùshǐ mǒu yì qǐyè de fùchǎnwù yǔ gōngyè fèirè, jīngzhǔn zhuǎnhuà wéi xiàyóu chǎnyèliàn de héxīn shēngchǎn yuánliào.', 'Mạng lưới cộng sinh công nghiệp tiên tiến có thể giúp phụ phẩm và nhiệt thừa công nghiệp của doanh nghiệp này được chuyển hóa chuẩn xác thành nguyên liệu cốt lõi cho chuỗi sản xuất hạ nguồn.'), ('这种变废为宝的闭环链条不仅显著降低了原材料开采消耗，还为企业带来了极为可观的降本增效收益。', 'Zhè zhǒng biàn-fèi-wéi-bǎo de bìhuán liàntiáo bùjǐn xiǎnzhù jiàngdī le yuáncáiliào kāicǎi xiāohào, hái wèi qǐyè dàilái le jíqí kěguān de jiàngběn zēngxiào shōuyì.', 'Vòng xích khép kín biến phế liệu thành bảo vật này không chỉ hạ thấp tiêu hao khai thác tài nguyên mà còn đem lại lợi ích giảm chi phí tăng hiệu quả kinh tế đáng kể.'), ('构建高效协同的绿色循环工业体系，是人类走向生态文明与实现经济可持续发展的必然抉择。', 'Gòujiàn gāoxiào xiétóng de lǜsè xúnhuán gōngyè tǐxì, shì rénlèi zǒuxiàng shēngtài wénmíng yǔ shíxiàn jīngjì kěchíxù fāzhǎn de bìrán juézé.', 'Xây dựng hệ thống công nghiệp tuần hoàn xanh hiệp đồng hiệu quả là lựa chọn tất yếu để nhân loại tiến tới văn minh sinh thái và phát triển kinh tế bền vững.')], [('Hạn chế lớn nhất của mô hình công nghiệp tuyến tính truyền thống là gì?', ['Sản phẩm quá bền', 'Khai thác - sản xuất - vứt bỏ một chiều gây khủng hoảng sức tải môi trường nghiêm trọng', 'Giá nguyên liệu quá rẻ'], 1, 'Trong bài có câu: 资源开采、产品制造、废弃丢弃的单向线性消费模式，造成了触目惊心的环境承载危机.'), ('Mạng lưới cộng sinh công nghiệp (工业共生网络) vận hành như thế nào?', ['Vứt hết phế thải ra sông', 'Biến phụ phẩm và nhiệt thải của doanh nghiệp này thành nguyên liệu cốt lõi cho chuỗi sản xuất hạ nguồn', 'Ngừng toàn bộ hoạt động nhà máy'], 1, 'Trong câu có viết: 副产物与工业废热，精准转化为下游产业链的核心生产原料.'), ('Lợi ích kép của kinh tế tuần hoàn đối với xã hội và doanh nghiệp là gì?', ['Tiêu tốn thêm ngân sách nhà nước', 'Giảm khai thác tài nguyên tự nhiên, bảo vệ môi trường và hạ giá thành nâng cao lợi nhuận', 'Chỉ mang tính lý thuyết suông'], 1, 'Trong câu có viết: 显著降低了原材料开采消耗，还为企业带来了可观的降本增效收益.')]),
    (19, '认知神经科学与意识之谜', 'Khoa học thần kinh nhận thức và bí ẩn của ý thức nhân loại', 'neuroscience', 'Khoa học não bộ', '🧠', 5, 'Từ các khớp thần kinh đến dòng suy nghĩ trừu tượng: Cuộc giải mã bí ẩn vĩ đại nhất của sự sống trong não bộ.', [('人类大脑拥有近千亿个神经元以及数以万亿计的突触连接，是宇宙中结构最为错综复杂的精密网络。', 'Rénlèi dànǎo yōngyǒu jìn qiān yì gè shénjīngyuán yǐjí shù yǐ wànyì jì de tūchù liánjiē, shì yǔzhòu zhōng jiégòu zuìwéi cuòzōng-fùzá de jīngmì wǎngluò.', 'Bộ não con người sở hữu gần trăm tỷ tế bào thần kinh cùng hàng ngàn tỷ khớp thần kinh (synapse) kết nối, là mạng lưới tinh vi có cấu trúc đan xen phức tạp nhất trong vũ trụ.'), ('脑电图、功能性磁共振成像等脑成像技术的长足进步，使科学家得以动态窥探人类思考与决策时的脑区激活图景。', 'Nǎodiàntú, gōngnéngxìng cígòngzhèn chéngxiàng děng nǎochéngxiàng jìshù de chángzú jìnbù, shǐ kēxuéjiā déyǐ dòngtài kuītàn rénlèi sīkǎo yǔ juécè shí de nǎoqū jīhuó tújǐng.', 'Tiến bộ vượt bậc của công nghệ chụp ảnh não như điện não đồ và cộng hưởng từ chức năng (fMRI) cho phép các nhà khoa học theo dõi sống động các vùng não kích hoạt khi con người tư duy và quyết định.'), ('然而，客观的电化学信号是如何不可思议地跨越鸿沟，跃变为丰富细腻的主观主观意识体验，至今依然是科学界难解的谜题。', "Rán'ér, kèguān de diànhuàxué xìnhào shì rúhé bùkě-sīyì de kuàyuè hónggōu, yuèbiàn wéi fēngfù xìnì de zhǔguān yìshí tǐyàn, zhìjīn yīrán shì kēxuéjiè nánjiě de mǐtí.", 'Thế nhưng, các tín hiệu điện hóa học khách quan đã vượt qua vực sâu ngăn cách như thế nào để nhảy vọt thành trải nghiệm ý thức chủ quan phong phú tinh tế, đến nay vẫn là câu đố hóc búa của giới khoa học.'), ('哲学家将这种从物理物质实体涌现出内在心智感受的难题，贴切地称为意识的硬问题。', 'Zhéxuéjiā jiāng zhè zhǒng cóng wùlǐ wùzhì shítǐ yǒngxiàn chū nèizài xīnji zhǐshòu de nántí, tiēqiè de chēngwéi yìshí de yìngwèntí.', "Các nhà triết học gọi bài toán hóc búa về sự trỗi dậy của cảm nhận tâm trí nội tại từ thực thể vật chất vật lý này một cách xác đáng là 'Vấn đề hóc búa của ý thức' (Hard problem of consciousness)."), ('解开人类大脑与自我意识之谜，不仅将深刻改写哲学认知，更将为治疗神经退行性疾病提供革命性的钥匙。', 'Jiěkāi rénlèi dànǎo yǔ zìwǒ yìshí zhī mǐ, bùjǐn jiāng shēnkè gǎixiě zhéxué rènzhī, gèng jiāng wèi zhìliáo shénjīng tuìxíngxìng jíbìng tígōng gémìngxìng de yàoshi.', 'Giải mã bí ẩn não bộ và ý thức tự ngã không chỉ viết lại nhận thức triết học mà còn trao chiếc chìa khóa cách mạng trong điều trị các căn bệnh thoái hóa thần kinh.')], [('Cấu trúc của não bộ con người có độ phức tạp như thế nào?', ['Chỉ có vài trăm tế bào', 'Gần trăm tỷ nơ-ron và hàng ngàn tỷ khớp nối synapse tinh vi bậc nhất vũ trụ', 'Đơn giản hơn máy vi tính để bàn'], 1, 'Trong bài có câu: 拥有近千亿个神经元以及数以万亿计的突触连接，是结构最为错综复杂的精密网络.'), ("'Vấn đề hóc búa của ý thức' (意识的硬问题) đề cập đến điều gì?", ['Làm thế nào tín hiệu điện hóa vật chất lại tạo ra được trải nghiệm tâm trí chủ quan', 'Cách thức học ngoại ngữ nhanh', 'Phương pháp phẫu thuật mở hộp sọ'], 0, 'Trong câu có viết: 客观的电化学信号是如何跃变为丰富细腻的主观意识体验，称为意识的硬问题.'), ('Ý nghĩa thực tiễn to lớn của việc giải mã bí ẩn não bộ là gì?', ['Chế tạo máy móc thay thế toàn bộ con người', 'Đổi mới nhận thức triết học và mở ra phương pháp điều trị bệnh thoái hóa thần kinh', 'Không mang lại ứng dụng nào'], 1, 'Trong câu cuối có viết: 不仅将深刻改写哲学认知，更将为治疗神经退行性疾病提供革命性的钥匙.')]),
    (20, '语言演变与社会思潮的互动', 'Sự tương tác giữa biến chuyển ngôn ngữ và các trào lưu xã hội', 'linguistics', 'Ngôn ngữ học', '🗣️', 5, 'Ngôn ngữ vừa là tấm gương phản chiếu biến động thời đại, vừa là công cụ định hình tư duy và quan niệm cộng đồng.', [('语言绝非一成不变的静止符号体系，而是一条随着社会变迁奔腾不息、不断吸纳新源泉的历史长河。', 'Yǔyán jué fēi yìchéng-bùbiàn de jìngzhǐ fúhào tǐxì, ér shì yì tiáo suízhe shèhuì biànqiān bēnténg-bùxī, búduàn xīnà xīn yuánquán de lìshǐ chánghé.', 'Ngôn ngữ tuyệt đối không phải là một hệ thống ký hiệu tĩnh tại bất biến, mà là một dòng sông lịch sử cuồn cuộn chảy trôi theo biến thiên xã hội, không ngừng tiếp thu những nguồn nước mới.'), ('每一个时代所涌现的新兴词汇、句式演化与语义泛化，都精准镌刻着当代公众的生活形态与价值观念。', 'Měi yí gè shídài suǒ yǒngxiàn de xīnxīng cíhuì, jùshì yǎnhuà yǔ yǔyì fànhuà, dōu jīngzhǔn juānkè zhe dāngdài gōngzhòng de shēnghuó xíngtài yǔ jiàzhí guānniàn.', 'Những từ vựng mới mẻ, sự biến đổi cấu trúc câu và sự mở rộng ngữ nghĩa xuất hiện ở mỗi thời đại đều khắc ghi chuẩn xác hình thái đời sống và hệ giá trị của công chúng đương thời.'), ('互联网文化的崛起催生了大量幽默鲜活的网络热梗与流行语，极大地丰富了青年群体的日常交际图式。', 'Hùliánwǎng wénhuà de juéqǐ cuīshēng le dàliàng yōumò xiānhuó de wǎngluò règěng yǔ liúxíngyǔ, jídà de fēngfù le niánqīng qúntǐ de rìcháng jiāojì túshì.', 'Sự trỗi dậy của văn hóa Internet đã sản sinh hàng loạt từ ngữ lóng và xu hướng thịnh hành hài hước sống động, làm phong phú phương thức giao tiếp thường nhật của giới trẻ.'), ('与此同时，外来语的频繁交融与古老词义的悄然嬗变，深刻见证了全球化浪潮中不同文明的对话轨迹。', 'Yǔcǐ-tóngshí, wàiláiyǔ de pínfán jiāoróng yǔ gǔlǎo cíyì de qiǎorán shànbiàn, shēnkè jiànzhèng le quánqiúhuà làngcháo zhōng bùtóng wénmíng de duìhuà guǐjì.', 'Đồng thời, sự giao thoa dồn dập của từ ngoại lai và sự đổi thay lặng lẽ của nghĩa từ cổ xưa minh chứng sâu sắc cho quỹ đạo đối thoại giữa các nền văn minh trong làn sóng toàn cầu hóa.'), ('考察语言生生不息的动态流变，正是我们深度解读社会变迁密码、把握时代脉搏的最敏锐触角。', 'Kǎochá yǔyán shēngshēng-bùxī de dòngtài liúbiàn, zhèng shì wǒmen shēndù jiědú shèhuì biànqiān mìmǎ, bǎwò shídài màibó de zuì mǐnruì chùjiǎo.', 'Khảo sát sự biến chuyển động không ngừng nghỉ của ngôn ngữ chính là chiếc ăng-ten nhạy bén nhất để ta giải mã mật mã biến thiên xã hội và nắm bắt mạch đập thời đại.')], [('Bản chất thực sự của ngôn ngữ được định nghĩa như thế nào trong bài viết?', ['Là hệ thống ký hiệu đóng kín bất biến', 'Là dòng sông lịch sử cuộn chảy, liên tục tiếp thu nguồn từ mới theo biến chuyển xã hội', 'Chỉ gồm các quy tắc ngữ pháp cứng nhắc'], 1, 'Trong câu đầu có viết: 绝非一成不变的静止符号体系，而是一条随着社会变迁奔腾不息的历史长河.'), ('Từ vựng mới và từ lóng mạng xuất hiện phản ánh điều gì?', ['Sự suy đồi của chữ viết', 'Khắc ghi chuẩn xác lối sống, tâm lý và hệ giá trị của công chúng đương thời', 'Chỉ để trêu đùa không có ý nghĩa'], 1, 'Trong câu có viết: 精准镌刻着当代公众的生活形态与价值观念.'), ('Nghiên cứu sự biến đổi của ngôn ngữ mang lại công cụ gì cho các nhà nghiên cứu?', ['Chỉ để viết từ điển', 'Là chiếc ăng-ten nhạy bén giải mã mật mã biến chuyển xã hội và nhịp đập thời đại', 'Làm phức tạp hóa việc dạy học'], 1, 'Trong câu cuối có viết: 解读社会变迁密码、把握时代脉搏的最敏锐触角.')]),
    (21, '宏观金融韧性与系统风险防范', 'Sức bền tài chính vĩ mô và phòng ngừa rủi ro hệ thống', 'financial_stability', 'Tài chính vĩ mô', '📈', 5, 'Xây dựng cơ chế giám sát thận trọng và công cụ đệm vốn giúp thị trường tài chính trụ vững trước biến động kinh tế toàn cầu.', [('现代金融体系如同一张精密交织的庞大神经网络，资金的高效流转支撑着实体经济的健康繁荣运转。', 'Xiàndài jīnróng tǐxì rútóng yì zhāng jīngmì jiāozhī de pángdà shénjīng wǎngluò, zījīn de gāoxiào liúzhuǎn zhīchēng zhe shítǐ jīngjì de jiànkāng fánróng yùnzhuǎn.', 'Hệ thống tài chính hiện đại tựa như mạng lưới thần kinh khổng lồ đan cài tinh vi, sự luân chuyển hiệu quả của dòng vốn nâng đỡ vận hành lành mạnh thịnh vượng của kinh tế thực thể.'), ('然而金融市场固有的顺周期性与资产泡沫膨胀倾向，往往容易在乐观预期蔓延时积聚巨大的杠杆风险。', "Rán'ér jīnróng shìchǎng gùyǒu de shùnqīqìngxìng yǔ zīchǎn pàomò péngzhàng qīngxiàng, wǎngwǎng róngyì zài lèguān yùqī mànyán shí jījù jùdà de gànggǎn fēngxiǎn.", 'Thế nhưng tính thuận chu kỳ vốn có và khuynh hướng thổi phồng bong bóng tài sản của thị trường tài chính thường dễ tích tụ rủi ro đòn bẩy khổng lồ khi kỳ vọng lạc quan lan rộng.'), ('一旦个别系统重要性金融机构遭遇流动性枯竭断裂，恐慌情绪可能在瞬间通过信用敞口引发灾难性的多米诺骨牌效应。', 'Yídàn gèbié xìtǒng zhòngyàoxìng jīnróng jīgòu zāoyù liúdòngxìng kūjié duànliè, kǒnghuāng qíngxù kěnéng zài shùnjiān tōngguò xìnyòng chǎngkǒu yǐnfā zāinànxìng de duōmǐnuò-gǔpái xiàoyìng.', 'Một khi định chế tài chính mang tầm quan trọng hệ thống cạn kiệt thanh khoản, tâm lý hoảng loạn có thể bùng phát ngay tức khắc qua các trạng thái rủi ro tín dụng tạo hiệu ứng domino thảm khốc.'), ('建立健全宏观审慎评估框架与动态逆周期资本缓冲机制，是守住不发生系统性金融风险底线的定海神针。', 'Jiànlì jiànquán hóngguān shěnshèn pínggū kuàngjià yǔ dòngtài nìzhōuqī zīběn huǎnchōng jīzhì, shì shǒu zhù bù fāshēng xìtǒngxìng jīnróng fēngxiǎn dǐxiàn de dìnghǎi-shénzhēn.', 'Xây dựng hoàn thiện khung đánh giá an toàn vĩ mô và cơ chế đệm vốn nghịch chu kỳ động là chiếc kim định hải giữ vững lằn ranh không để xảy ra rủi ro tài chính hệ thống.'), ('兼顾金融创新活力与监管兜底防线，方能确保国民经济在波谲云诡的国际风浪中行稳致远。', 'Jiāngù jīnróng chuàngxīn huólì yǔ jiānguǎn dōudǐ fángxiàn, fāng néng quèbǎo guómín jīngjì zài bōjué-yúnguǐ de guójì fēnglàng zhōng xíngwěn-zhìyuǎn.', 'Kết hợp hài hòa sức sống đổi mới tài chính cùng phòng tuyến giám sát vững vàng mới có thể bảo đảm nền kinh tế quốc dân lướt sóng ra khơi xa an định giữa bão táp quốc tế khôn lường.')], [('Đặc tính nguy hiểm tiềm ẩn của thị trường tài chính khi quá lạc quan là gì?', ['Lãi suất quá thấp', 'Tính thuận chu kỳ và tích tụ rủi ro đòn bẩy quá mức từ bong bóng tài sản', 'Không có người vay tiền'], 1, 'Trong bài có câu: 顺周期性与资产泡沫膨胀倾向，往往容易在乐观预期蔓延时积聚巨大的杠杆风险.'), ('Hiệu ứng domino tài chính xảy ra khi nào?', ['Khi lãi suất ngân hàng tăng nhẹ', 'Khi định chế tài chính quan trọng cạn kiệt thanh khoản gây lây lan hoảng loạn', 'Khi thị trường vàng ổn định'], 1, 'Trong câu có viết: 系统重要性金融机构遭遇流动性枯竭断裂，恐慌情绪瞬间引发多米诺骨牌效应.'), ("Công cụ then chốt được ví như 'kim định hải' để ngăn chặn rủi ro hệ thống là gì?", ['Ngừng mọi hoạt động vay vốn', 'Khung giám sát an toàn vĩ mô và cơ chế đệm vốn nghịch chu kỳ linh hoạt', 'Đóng cửa thị trường chứng khoán'], 1, 'Trong câu có viết: 建立健全宏观审慎评估框架与动态逆周期资本缓冲机制.')]),
    (22, '丝绸之路沿线的考古新启示', 'Những khám phá khảo cổ mới dọc Con đường Tơ lụa huyền thoại', 'archaeology', 'Khảo cổ học', '🏺', 5, 'Hiện vật gốm sứ, tiền xu và văn thư ngàn năm khai quật dưới cát vàng minh chứng cho giao lưu thương mại và văn hóa rực rỡ.', [('绵延万里的古丝绸之路横跨欧亚大陆腹地，黄沙掩埋之下深藏着无数曾经辉煌灿烂的历史密码。', 'Miányán wàn lǐ de gǔ sīchóuzhīlù héngkuà Ōu-Yà dàlù fùdì, huángshā yǎnmái zhī xià shēncáng zhe wúshù céngjīng huīhuáng cànlàn de lìshǐ mìmǎ.', 'Con đường Tơ lụa cổ xưa vạn dặm vắt ngang qua trung tâm lục địa Á - Âu, dưới lớp cát vàng chôn giấu vô vàn mật mã lịch sử từng huy hoàng rực rỡ.'), ('近年来在新疆与中亚腹地展开的田野考古发掘中，大量精美的纺织品、罗马金币与汉简文书重见天日。', 'Jìnnián lái zài Xīnjiāng yǔ Zhōngyà fùdì zhǎnkāi de tiányě kǎogǔ fājué zhōng, dàliàng jīngměi de fǎngzhīpǐn, Luómǎ jīnbì yǔ Hàn jiǎn wénshū chóngjiàn-tiānrì.', 'Những năm gần đây trong các cuộc khai quật khảo cổ điền dã tại Tân Cương và Trung Á, hàng loạt dệt phẩm tinh xảo, tiền vàng La Mã và thẻ tre văn thư thời Hán đã tái xuất ánh mặt trời.'), ('一件出土的锦织护膊上织有五星出东方利中国的吉祥铭文，色彩历经千余年依然鲜艳明丽如新。', 'Yí jiàn chūtǔ de jǐnzhī hùbó shàng zhī yǒu wǔxīng chū dōngfāng lì Zhōngguó de jíxiáng míngwén, sècǎi lìjīng qiān yú nián yīrán xiānyàn mínglì rú xīn.', "Một tấm bao tay dệt gấm khai quật dệt dòng chữ cát tường 'Ngũ tinh xuất đông phương lợi Trung Quốc', màu sắc trải qua hơn ngàn năm vẫn tươi tắn rạng ngời như mới."), ('出土文物上多语种对照的官方文书与商贸契约，铁证如山地证实了不同族群在此和睦共处与频繁互市。', 'Chūtǔ wénwù shàng duō yǔzhǒng duìzhào de guānfāng wénshū yǔ shāngmào qìyuē, tiězhèng-rúshān de zhèngshí le bùtóng zúqún zài cǐ hémù gòngchǔ yǔ pínfán hùshì.', 'Các văn thư hành chính đối chiếu đa ngôn ngữ và hợp đồng thương mại trên cổ vật là bằng chứng sắt đá chứng minh sự chung sống hòa bình và giao thương tấp nập giữa các dân tộc.'), ('考古发掘不仅是在重现被尘封的物质遗存，更是在重新勾勒一幅古代世界和平合作与文明互鉴的壮丽画卷。', 'Kǎogǔ fājué bùjǐn shì zài chóngxiàn bèi chénfēng de wùzhì yícún, gèng shì zài chóngxīn gōulè yì fú gǔdài shìjiè hépíng hézuò yǔ wénmíng hùjiàn de zhuànglì huàjuàn.', 'Khai quật khảo cổ không chỉ tái hiện những di tồn vật chất từng bị bụi thời gian chôn vùi, mà còn phác họa lại bức tranh tráng lệ về sự hợp tác hòa bình và văn minh tương chiếu của thế giới cổ đại.')], [('Hiện vật quý nào được phát hiện trong các đợt khảo cổ gần đây tại Tân Cương và Trung Á?', ['Chỉ có đá cuội', 'Hàng dệt may tinh xảo, tiền vàng La Mã và thẻ tre văn thư thời Hán', 'Đồ nhựa hiện đại'], 1, 'Trong bài có câu: 大量精美的纺织品、罗马金币与汉简文书重见天日.'), ('Dòng chữ dệt trên tấm bao tay gấm cổ ngàn năm còn tươi màu là gì?', ['Ngũ tinh xuất đông phương lợi Trung Quốc', 'Chúc mừng năm mới', 'Thuận buồm xuôi gió'], 0, 'Trong câu có viết: 织有五星出东方利中国的吉祥铭文，色彩历经千余年依然鲜艳明丽如新.'), ('Ý nghĩa cốt lõi của các phát hiện khảo cổ trên con đường tơ lụa là gì?', ['Khẳng định chiến tranh tàn khốc', 'Minh chứng sắt đá cho giao thương hòa bình, đa văn hóa cùng chung sống thịnh vượng', 'Chỉ để bán đấu giá cổ vật'], 1, 'Trong câu cuối có viết: 证实了不同族群在此和睦共处与频繁互市，勾勒和平合作与文明互鉴的壮丽画卷.')]),
    (23, '纳米科技对精准医疗的赋能', 'Công nghệ nano mở đường cho y học chính xác', 'nanomedicine', 'Công nghệ sinh học', '🔬', 5, 'Các hạt nano thông minh có khả năng vận chuyển thuốc tới tận tế bào ung thư mà không làm tổn thương mô lành xung quanh.', [('恶性肿瘤的传统放化疗手段往往缺乏足够的靶向特异性，在杀伤癌细胞的同时也会严重损伤人体的正常健康组织。', 'Èxìng zhǒngliú de chuántǒng fàng-huàliáo shǒuduàn wǎngwǎng quēfá zúgòu de bǎxiàng tèyìxìng, zài shāshāng áixìbāo de tóngshí yě huì yánzhòng sǔnshāng réntǐ de zhèngcháng jiànkāng zǔzhī.', 'Các phương pháp xạ trị và hóa trị truyền thống điều trị u ác tính thường thiếu tính đặc hiệu trúng đích, khi tiêu diệt tế bào ung thư đồng thời gây tổn thương nghiêm trọng các mô khỏe mạnh bình thường.'), ('纳米生物医药技术的崛起，为解决这一困扰现代医学数十年的棘手难题带来了划时代的突破契机。', 'Nàmǐ shēngwù yīyào jìshù de juéqǐ, wèi jiějué zhè yì kùnrǎo xiàndài yīxué shù shí nián de jíshǒu nántí dàilái le huàshídài de tūpò qìjī.', 'Sự trỗi dậy của công nghệ y dược sinh học nano mang đến cơ hội đột phá mang tính thời đại để giải quyết bài toán hóc búa làm đau đầu y học hiện đại nhiều thập kỷ qua.'), ('科学家通过表面修饰特定抗体或配体，制造出能够敏锐识别肿瘤特异抗原的智能纳米药物载体。', 'Kēxuéjiā tōngguò biǎomiàn xiūshì tèdìng kàngtǐ huò pèitǐ, zhìzào chū nénggòu mǐnruì shíbié zhǒngliú tèyì kàngyuán de zhìnéng nàmǐ yàowù zàitǐ.', 'Các nhà khoa học thông qua biến tính bề mặt bằng kháng thể hoặc phối tử đặc hiệu đã chế tạo ra các hạt chất mang nano thông minh có thể nhận diện nhạy bén kháng nguyên khối u.'), ('这些纳米微粒如同一枚枚精确制导的微型导弹，能将高浓度化疗药物直接释放于病灶深处，实现零误差杀灭。', 'Zhèxiē nàmǐ wēilì rútóng yì méiméi jīngquè zhìdǎo de wēixíng dǎodàn, néng jiāng gāo nóngdù huàliáo yàowù zhíjiē shìfàng yú bìngzào shēnchù, shíxiàn líng wùchā shāmiè.', 'Những hạt vi mô nano này tựa như những tên lửa mini dẫn đường chuẩn xác, có thể giải phóng trực tiếp thuốc hóa trị nồng độ cao vào sâu trong ổ bệnh để tiêu diệt với sai số bằng không.'), ('纳米科技赋能下的精准诊疗模式，正引领肿瘤医学迈向高效低毒、个性化定制的崭新纪元。', 'Nàmǐ kējì fùnéng xià de jīngzhǔn zhěnliáo móshì, zhèng yǐnlǐng zhǒngliú yīxué màixiàng gāoxiào dī dú, gèxìnghuà dìngzhì de zhǎnxīn jìyuán.', 'Mô hình chẩn đoán và điều trị chính xác được tiếp sức bởi công nghệ nano đang dẫn dắt chuyên ngành ung thư bước vào kỷ nguyên mới hiệu quả cao, độc tính thấp và cá thể hóa.')], [('Nhược điểm lớn nhất của các liệu pháp xạ trị hóa trị ung thư truyền thống là gì?', ['Không có hiệu quả', 'Thiếu tính trúng đích, tiêu diệt cả tế bào lành gây tác dụng phụ nặng nề', 'Chi phí quá thấp'], 1, 'Trong bài có câu: 缺乏足够的靶向特异性，在杀伤癌细胞的同时也会严重损伤健康组织.'), ('Hạt mang thuốc nano thông minh hoạt động như thế nào trong cơ thể?', ['Tỏa nhiệt ngẫu nhiên', 'Như tên lửa mini dẫn đường, nhận diện kháng nguyên khối u và đưa thuốc thẳng vào ổ bệnh', 'Làm tan biến mọi tế bào'], 1, 'Trong câu có viết: 如同一枚枚精确制导的微型导弹，能将高浓度化疗药物直接释放于病灶深处.'), ('Triển vọng mà công nghệ nano mang lại cho điều trị ung thư là gì?', ['Dẫn dắt y học ung thư bước vào kỷ nguyên hiệu quả cao, độc tính thấp và điều trị cá nhân hóa', 'Không cần bác sĩ nữa', 'Chữa khỏi ngay trong 1 giây'], 0, 'Trong câu cuối có viết: 正引领肿瘤医学迈向高效低毒、个性化定制的崭新纪元.')]),
    (24, '审美移情与艺术体验的共鸣', 'Đồng cảm thẩm mỹ và sự cộng hưởng sâu sắc trong trải nghiệm nghệ thuật', 'aesthetics', 'Mỹ học', '🎨', 5, 'Khi con người đặt trọn tâm hồn vào tác phẩm, khoảng cách giữa chủ thể và khách thể tan biến trong niềm thăng hoa xúc cảm.', [('艺术之所以能够跨越千年岁月与语言藩篱直抵人心，关键在于人类独具的审美移情心理机制。', 'Yìshù zhī suǒyǐ nénggòu kuàyuè qiān nián suìyuè yǔ yǔyán fānlí zhí dǐ rénxīn, guānjiàn zàiyú rénlèi dújù de shěnměi yíqíng xīnlǐ jīzhì.', 'Nghệ thuật sở dĩ có thể vượt qua ngàn năm thời gian và rào cản ngôn ngữ để chạm tới đáy tim là nhờ cơ chế tâm lý đồng cảm thẩm mỹ độc nhất của con người.'), ('美学理论认为，移情并非被动接收客体形象，而是鉴赏者将自身的生命情感与人生体验主动投射于审美对象之中。', 'Měixué lǐlùn rènwéi, yíqíng bìng fēi bèidòng jiēshōu kètǐ xíngxiàng, ér shì jiànshǎngzhě jiāng zìshēn de shēngmìng qínggǎn yǔ rénshēng tǐyàn zhǔdòng tóushè yú shěnměi duìxiàng zhī zhōng.', 'Lý luận mỹ học cho rằng, đồng cảm không phải là tiếp nhận hình ảnh khách thể một cách thụ động, mà là người thưởng lãm chủ động phóng chiếu tình cảm sinh mệnh và trải nghiệm đời mình vào đối tượng thẩm mỹ.'), ('当我们凝视凡·高笔下旋涡般翻滚的麦田与星空时，画布上的每一道狂热笔触都在剧烈激荡着我们内心的孤独与炽热。', 'Dāng wǒmen níngshì Fán Gāo bǐxià xuánwō bān fāngǔn de màitián yǔ xīngkōng shí, huàbù shàng de měi yí dào kuángrè bǐchù dōu zài jùliè jīdàng zhe wǒmen nèixīn de gūdú yǔ chìrè.', 'Khi ta ngắm nhìn bầu trời đêm và cánh đồng lúa mì cuộn xoáy dưới nét cọ Van Gogh, từng vệt vẽ cuồng nhiệt trên toan đều khuấy đảo dữ dội nỗi cô đơn và đam mê cháy bỏng trong lòng ta.'), ('在此种神与物游的浑然境界中，主观的心灵与客观的物象融为一体，激荡起强烈的精神震撼与情感涤荡。', 'Zài cǐ zhǒng shén yǔ wù yóu de húnrán jìngjiè zhōng, zhǔguān de xīnlíng yǔ kèguān de wùxiàng róng wéi yītǐ, jīdàng qǐ qiángliè de jīngshén zhènhàn yǔ qínggǎn dídàng.', "Trong cảnh giới 'thần hòa cùng vật' tự nhiên này, tâm hồn chủ quan và hình ảnh khách quan tan chảy làm một, dấy lên cú sốc tinh thần mãnh liệt và sự gột rửa cảm xúc sâu xa."), ('审美体验最终让我们超越了日常生活的琐碎平庸，在与人类共同命运的深层共鸣中寻获灵魂的升华。', 'Shěnměi tǐyàn zuìzhōng ràng wǒmen chāoyuè le rìcháng shēnghuó de suǒsuì píngyōng, zài yǔ rénlèi gòngtóng mìngyùn de shēncéng gòngmíng zhōng xúnhuò línghún de shēnghuá.', 'Trải nghiệm thẩm mỹ rốt cuộc giúp ta vượt thoát sự tầm thường vụn vặt của đời sống thường nhật, tìm thấy sự thăng hoa tâm hồn trong niềm cộng cảm sâu xa với vận mệnh chung của nhân loại.')], [("Cơ chế của hiện tượng 'đồng cảm thẩm mỹ' (审美移情) được hiểu như thế nào?", ['Chỉ nhìn ngắm màu sắc bên ngoài', 'Người thưởng ngoạn chủ động phóng chiếu tình cảm và trải nghiệm sống của mình vào đối tượng nghệ thuật', 'Học thuộc thông tin về tác giả'], 1, 'Trong bài có câu: 将自身的生命情感与人生体验主动投射于审美对象之中.'), ('Tranh của Van Gogh khơi gợi trạng thái cảm xúc gì nơi người xem?', ['Sự buồn ngủ', 'Khuấy động dữ dội nỗi cô đơn và ngọn lửa đam mê sâu kín trong lòng', 'Cảm giác sợ hãi không dám nhìn'], 1, 'Trong câu có viết: 画布上的每一道狂热笔触都在剧烈激荡着我们内心的孤独与炽热.'), ('Ý nghĩa tối thượng của trải nghiệm thẩm mỹ là gì?', ['Khoe khoang kiến thức nghệ thuật', 'Vượt thoát vụn vặt đời thường, tìm kiếm sự thăng hoa tâm hồn qua sự cộng cảm sâu sắc', 'Mua tranh để kiếm lời'], 1, 'Trong câu cuối có viết: 超越日常生活的琐碎平庸，在与人类共同命运的深层共鸣中寻获灵魂的升华.')]),
    (25, '城市群演进与区域协同发展', 'Tiến trình phát triển cụm đô thị và kết nối vùng chiến lược', 'regional_development', 'Đô thị học', '🏙️', 5, 'Liên kết giao thông tốc độ cao và phân công chuỗi công nghiệp giúp các siêu đô thị tương trợ và cùng cất cánh.', [('伴随着经济要素流动壁垒的逐步打破，以特大中心城市为核心的城市群正日益成为国家竞争力的核心载体。', 'Bànsuí zhe jīngjì yàosù liúdòng bìlěi de zhúbù dǎpò, yǐ tàdà zhōngxīn chéngshì wéi héxīn de chéngshìqún zhèng rìyì chéngwéi guójiā jìngzhēnglì de héxīn zàitǐ.', 'Cùng với việc dần xóa bỏ các rào cản luân chuyển yếu tố kinh tế, cụm đô thị lấy siêu đô thị trung tâm làm hạt nhân đang ngày càng trở thành chủ thể cốt lõi cho sức cạnh tranh quốc gia.'), ('过去城市间单打独斗、同质化低水平竞争的发展模式，已被深度分工协同的新型合作机制所彻底取代。', 'Guòqù chéngshì jiān dāndǎ-dúdòu, tóngzhìhuà dīshuǐpíng jìngzhēng de fāzhǎn móshì, yǐ bèi shēndù fēngōng xiétóng de xīnxíng hézuò jīzhì suǒ chèdǐ qǔdài.', 'Mô hình phát triển đơn đả độc đấu, cạnh tranh trùng lặp trình độ thấp giữa các đô thị trước kia đã bị thay thế hoàn toàn bằng cơ chế hợp tác mới phân công sâu sắc và hiệp đồng.'), ('发达的高速铁路网、城际轨道交通与物流骨干网络，将原本相距甚远的城市群聚合成高效紧密的一小时经济圈。', 'Fādá de gāosù tiělù wǎng, chéngjì guǐdào jiāotōng yǔ wùliú gǔgàn wǎngluò, jiāng yuánběn xiāngjù shènyuǎn de chéngshìqún jùhé chéng gāoxiào jǐnmì de yì xiǎoshí jīngjìquān.', "Mạng lưới đường sắt cao tốc phát triển, giao thông đường sắt liên đô thị cùng trục vận tải logistics nòng cốt đã hội tụ các đô thị xa xôi thành 'vòng tròn kinh tế một giờ' khép kín hiệu quả."), ('核心大都市专注于前沿研发、现代金融与高端设计，周边卫星城则依托成本优势承接高端制造与成果转化基地。', 'Héxīn dǎdūshì zhuānzhù yú qiányán yánfā, xiàndài jīnróng yǔ gāoduān shèjì, zhōuwéi wèixīngchéng zé yītuō chéngběn yōushì chéngjiē gāoduān zhìzào yǔ chéngguǒ zhuǎnhuà jīdì.', 'Đô thị hạt nhân tập trung vào nghiên cứu tiền phong, tài chính hiện đại và thiết kế cao cấp, trong khi các đô thị vệ tinh xung quanh phát huy ưu thế chi phí làm bệ phóng chế tạo cao cấp.'), ('这种优势互补、利益共享的区域一体化战略格局，将为国民经济的可持续高质量增长注入澎湃不竭的动力。', 'Zhè zhǒng yōushì hùbǔ, lìyì gòngxiǎng de qūyù yītǐhuà zhànlüè géjú, jiāng wèi guómín jīngjì de kěchíxù gāozhìliàng zēngzhǎng zhùrù péngpài-bùjié de dònglì.', 'Cục diện chiến lược nhất thể hóa khu vực bổ trợ thế mạnh và cùng chia sẻ lợi ích này sẽ bơm nguồn động lực cuộn trào bất tận cho tăng trưởng chất lượng cao bền vững.')], [('Mô hình phát triển nào đã thay thế sự cạnh tranh trùng lặp đơn độc giữa các thành phố?', ['Đóng cửa cô lập lẫn nhau', 'Cơ chế phân công sâu rộng và hợp tác hiệp đồng cùng phát triển', 'Bỏ hoang các thành phố nhỏ'], 1, 'Trong bài có câu: 已被深度分工协同的新型合作机制所彻底取代.'), ('Hạ tầng giao thông hiện đại tạo ra khái niệm liên kết kinh tế nào?', ['Vòng tròn kinh tế một giờ (一小时经济圈) hiệu quả và gắn kết', 'Khu cách ly ba ngày', 'Khoảng cách xa hơn'], 0, 'Trong câu có viết: 将原本相距甚远的城市群聚合成高效紧密的一小时经济圈.'), ('Sự phân công lao động giữa đô thị trung tâm và thành phố vệ tinh diễn ra như thế nào?', ['Đô thị trung tâm làm nông nghiệp, vệ tinh làm tài chính', 'Đô thị trung tâm tập trung nghiên cứu, tài chính; vệ tinh đón nhận sản xuất chế tạo', 'Hai bên làm việc hoàn toàn giống hệt nhau'], 1, 'Trong câu có viết: 核心大都市专注于研发与金融，周边卫星城承接制造与成果转化.')]),
    (26, '濒危物种基因库的抢救性保存', 'Bảo tồn khẩn cấp ngân hàng gen các loài sinh vật nguy cấp', 'genetic_preservation', 'Sinh thái & Di truyền', '🧬', 5, 'Đông lạnh tế bào mầm và mô sống ở nhiệt độ âm 196 độ C: Phao cứu sinh bảo vệ sự đa dạng sinh học trước nguy cơ tuyệt chủng.', [('人类活动导致的生境破碎化与全球气候剧变，正使得地球上的物种以惊人的速度滑向灭绝的深渊。', 'Rénlèi huódòng dǎozhì de shēngjìng pòsuìhuà yǔ quánqiú qìhòu jùbiàn, zhèng shǐde dìqiú shàng de wùzhǒng yǐ jīngrén de sùdù huá xiàng mièjué de shēnyuān.', 'Môi trường sống bị phân mảnh do hoạt động con người và biến đổi khí hậu dữ dội đang khiến các loài sinh vật trên trái đất trượt xuống bờ vực tuyệt chủng với tốc độ đáng kinh ngạc.'), ('建立国家级濒危野生动植物种质资源基因库，是抢救性挽救生物遗传多样性的终极科技防线。', 'Jiànlì guójiājí bīnwēi yèshēng dòngzhíwù zhǒngzhì zīyuán jīyīnkù, shì qiǎngjiùxìng wǎnjiù shēngwù yíchuán duōyàngxìng de zhōngjí kējì fángxiàn.', 'Xây dựng ngân hàng gen tài nguyên giống loài động thực vật hoang dã nguy cấp cấp quốc gia là phòng tuyến khoa học công nghệ tối hậu để cứu vãn sự đa dạng di truyền sinh học.'), ('科学家采用超低温深冷冻技术，在零下一百九十六度的液氮环境中长期保存珍稀生物的生殖细胞、组织与DNA样本。', 'Kēxuéjiā cǎiyòng chāodīwēn shēnlěngdòng jìshù, zài língxià yībǎi jiǔshíliù dù de yèdàn huánjìng zhōng chángqī bǎocún zhēnxī shēngwù de shēngzhí xìbāo, zǔzhī yǔ DNA yàngběn.', 'Các nhà khoa học áp dụng công nghệ đông lạnh siêu sâu ở môi trường nitơ lỏng âm 196 độ C để lưu giữ lâu dài tế bào sinh sản, mô và mẫu DNA của các sinh vật quý hiếm.'), ('这些休眠的遗传密码不仅承载着生命演化数十亿年的宝贵信息，更为未来利用生物克隆实现物种复活保留了火种。', 'Zhèxiē xiūmián de yíchuán mìmǎ bùjǐn chéngzài zhe shēngmìng yǎnhuà shù shí yì nián de bǎoguì xìnxī, gèng wèi wèilái lìyòng shēngwù kèlóng shíxiàn wùzhǒng fùhuó bǎoliú le huǒzhǒng.', 'Những mật mã di truyền đang say ngủ này không chỉ chứa đựng thông tin tiến hóa sinh mệnh quý giá hàng tỷ năm qua mà còn lưu giữ ngọn lửa hy vọng để hồi sinh giống loài bằng nhân bản vô tính tương lai.'), ('守护好大自然赋予地球的生命基因方舟，是我们对未来子孙后代不可推卸的庄严生态誓言。', 'Shǒuhù hǎo dàzìrán fùyǔ dìqiú de shēngmìng jīyīn fāngzhōu, shì wǒmen duì wèilái zǐsūn-hòudài bùkě-tuīxiè de zhuāngyán shēngtài shìyán.', 'Bảo vệ vững chắc con thuyền noah gen sự sống mà mẹ thiên nhiên trao gửi cho trái đất là lời thề sinh thái trang nghiêm không thể thoái thác của chúng ta với con cháu mai sau.')], [('Công nghệ cốt lõi nào được sử dụng để bảo tồn ngân hàng gen sinh vật hoang dã nguy cấp?', ['Sấy khô dưới ánh nắng', 'Bảo quản đông lạnh sâu trong nitơ lỏng âm 196 độ C', 'Ngâm trong cồn thông thường'], 1, 'Trong bài có câu: 在零下一百九十六度的液氮环境中长期保存生殖细胞、组织与DNA样本.'), ('Mục đích xa hơn của việc lưu giữ tế bào và mẫu DNA này cho tương lai là gì?', ['Làm tiêu bản trưng bày bảo tàng', 'Lưu giữ ngọn lửa mầm sống giúp hồi sinh các loài bằng kỹ thuật sinh học trong tương lai', 'Bán ra thị trường'], 1, 'Trong câu có viết: 为未来利用生物克隆实现物种复活保留了火种.'), ('Ngân hàng gen sinh vật được ví với hình ảnh gì?', ['Chiếc tủ lạnh thông thường', 'Con thuyền Noah chứa đựng gen sự sống của Trái Đất', 'Kho phế liệu sinh học'], 1, 'Trong câu cuối có viết: 守护好大自然赋予地球的生命基因方舟.')]),
    (27, '儒家伦理在现代管理中的生机', 'Sức sống của luân lý Nho gia trong quản trị tổ chức hiện đại', 'confucian_management', 'Quản trị học', '📜', 5, "Đạo lý 'Nhân nghĩa lễ trí tín' và tư tưởng dĩ vi bản giúp xây dựng văn hóa doanh nghiệp nhân văn và bền vững.", [('西方现代管理理论以契约理性、制度约束与绩效激励为支柱，推动了全球工商业的规模化飞跃。', 'Xīfāng xiàndài guǎnlǐ lǐlùn yǐ qìyuē lǐxìng, zhìdù yuēshù yǔ jìxiào jīlì wéi zhīzhù, tuīdòng le quánqiú gōngshāngyè de guīmóhuà fēiyuè.', 'Lý thuyết quản trị hiện đại phương Tây lấy duy lý hợp đồng, ràng buộc thể chế và đãi ngộ hiệu suất làm trụ cột, thúc đẩy bước nhảy vọt quy mô của công thương nghiệp toàn cầu.'), ('然而过度依赖量化考核与冰冷惩罚，也常常导致企业内部人际疏离、员工归属感缺失等异化困局。', "Rán'ér guòdù yīlài liànghuà kǎohé yǔ bǐnglěng chéngfá, yě chángcháng dǎozhì qǐyè nèibù rénjì shūlí, yuángōng guīshǔgǎn quēshī děng yìhuà kùnjú.", 'Thế nhưng việc quá lạm dụng đánh giá định lượng và kỷ luật lạnh lùng cũng hay dẫn tới thế khó tha hóa: sự xa cách giữa người với người và thiếu hụt cảm giác thuộc về tổ chức.'), ('汲取东方儒家仁爱互信、以人为本的核心思想，能够为冰冷的技术官僚管理注入温润的人文关怀。', "Jíqǔ dōngfāng Rújiā rén'ài hùxìn, yǐrén-wéiběn de héxīn sīxiǎng, nénggòu wèi bǐnglěng de jìshù-guānliáo guǎnlǐ zhùrù wēnrùn de rénwén guānhuái.", 'Tiếp thu tư tưởng cốt lõi nhân ái tin cậy, lấy con người làm gốc của Nho gia phương Đông có thể thổi hơi ấm quan tâm nhân văn vào nền quản trị quan liêu kỹ trị lạnh lẽo.'), ('管理者修身立德、以身作则，重诺守信并真诚关爱员工福祉，能够自上而下构筑坚如磐石的团队凝聚力。', "Guǎnlǐzhě xiūshēn-lìdé, yǐshēn-zuòzé, zhòngnuò-shǒuxìn bìng zhēnchéng guān'ài yuángōng fúzhǐ, nénggòu zìshàng'érxià gòuzhù jiānrúpánshí de tuánduì níngjùlì.", 'Người quản lý tu thân lập đức, nêu gương sáng đi đầu, coi trọng chữ tín và chân thành chăm lo phúc lợi nhân viên có thể xây đắp sức mạnh gắn kết bền như bàn thạch từ trên xuống dưới.'), ('制度刚性与道德温情的有机融合，正是现代企业迈向卓越、成就百年基业的深层文化密码。', 'Zhìdù gāngxìng yǔ dàodé wēnqíng de yǒujī rónghé, zhèng shì xiàndài qǐyè màixiàng zhuóyuè, chéngjiù bǎinián jīyè de shēncéng wénhuà mìmǎ.', 'Sự dung hợp hài hòa giữa tính nghiêm minh của thể chế cùng hơi ấm đạo đức chính là mật mã văn hóa sâu sắc giúp doanh nghiệp vươn tới kiệt xuất và gây dựng cơ nghiệp trăm năm.')], [('Mặt hạn chế khi doanh nghiệp chỉ áp dụng cứng nhắc quản lý định lượng phương Tây là gì?', ['Doanh thu tăng quá nhanh', 'Gây ra sự xa lánh giữa đồng nghiệp và nhân viên thiếu cảm giác thuộc về tập thể', 'Lương bổng quá cao'], 1, 'Trong bài có câu: 导致企业内部人际疏离、员工归属感缺失等异化困局.'), ('Triết lý Nho gia nào có thể bổ sung cho cách quản lý khô cứng này?', ['Lấy lợi ích làm đầu', 'Nhân ái, lấy con người làm gốc (以人为本) và coi trọng chữ tín', 'Chế độ thưởng phạt tùy tiện'], 1, 'Trong câu có viết: 汲取东方儒家仁爱互信、以人为本的核心思想.'), ('Bí quyết để doanh nghiệp xây dựng nền móng bền vững trăm năm là gì?', ['Dung hợp giữa thể chế nghiêm minh và sự ấm áp của đạo đức nhân văn', 'Bãi bỏ toàn bộ quy định công ty', 'Chỉ làm việc qua máy tính'], 0, 'Trong câu cuối có viết: 制度刚性与道德温情的有机融合，正是成就百年基业的深层文化密码.')]),
    (28, '深海热泉生态与生命起源之谜', 'Hệ sinh thái miệng phun thủy nhiệt và bí ẩn nguồn gốc sự sống', 'hydrothermal_vents', 'Địa sinh học', '🌋', 5, 'Nơi đáy biển tối tăm không ánh sáng mặt trời, vi khuẩn hóa dưỡng sinh sôi nảy nở mở ra giả thuyết nguồn cội sự sống nguyên sơ.', [('在数千米幽暗死寂的海底大洋中脊，炽热的岩浆加热地壳海水，喷涌出高达几百度、富含硫化物的海底黑烟囱。', "Zài shù qiān mǐ yōu'àn sǐjì de hǎidǐ dàyáng zhōngjǐ, chìrè de yánjiāng jiārè dìqiào hǎishuǐ, pēnyǒng chū gāodá jǐ bǎi dù, fùhán liúhuàwù de hǎidǐ hēiyāncōng.", "Nơi sống núi giữa đại dương tối tăm lạnh ngắt sâu hàng ngàn mét, magma nóng rực đun sôi nước biển trong vỏ trái đất, phun trào những cột 'ống khói đen' giàu sulfide với nhiệt độ hàng trăm độ C."), ('令人震撼的是，在完全缺乏光合作用、承受恐怖水压的极端严酷环境下，竟然繁衍着生机盎然的奇特生物群落。', 'Lìng rén zhènhàn de shì, zài wánquán quēfá guānghé zuòyòng, chéngshòu kǒngbù shuǐyā de jíduān yánkù huánjìng xià, jìngrán fányǎn zhe shēngjī-àngrán de qítè shēngwù qúnluò.', 'Điều làm chấn động là trong môi trường hoàn toàn không có quang hợp và chịu áp lực nước khủng khiếp, lại sinh sôi nảy nở những quần xã sinh vật kỳ lạ tràn trề nhựa sống.'), ('巨型管虫、盲虾与白瓷蟹完全不依赖太阳能，而是依靠化能合成自养细菌氧化硫化氢获取生存能量。', 'Jùxíng guǎnchóng, mángxiā yǔ báicíxiè wánquán bù yīlài tàiyángnéng, ér shì yīkào huànéng héchéng zìyǎng xìjūn yǎnghuà liúhuàqīng huòqǔ shēngcún néngliàng.', 'Những loài giun ống khổng lồ, tôm mù và cua trắng hoàn toàn không dựa vào năng lượng mặt trời, mà dựa vào vi khuẩn hóa dưỡng oxy hóa hydro sulfide để lấy năng lượng tồn tại.'), ('这种颠覆传统生物学常识的独立生态系统，为生命起源于深海热泉假说提供了极为有力的科学佐证。', 'Zhè zhǒng diānfù chuántǒng shēngwùxué chángshí de dúlì shēngtài xìtǒng, wèi shēngmìng qǐyuán yú shēnhǎi rèquán jiǎshuō tígōng le jíqí yǒulì de kēxué zuǒzhèng.', 'Hệ sinh thái độc lập lật đổ nhận thức thông thường của sinh học này đã cung cấp bằng chứng khoa học vô cùng đanh thép cho giả thuyết sự sống bắt nguồn từ miệng phun nhiệt đáy biển.'), ('探秘深海极端生境，不仅让我们重新审视地球生命的顽强本质，更指引着人类在冰封的外星海洋中寻找地外生命的踪迹。', 'Tànmì shēnhǎi jíduān shēngjìng, bùjǐn ràng wǒmen chóngxīn shěnshì dìqiú shēngmìng de wánqiáng běnzhì, gèng zhǐyǐn zhe rénlèi zài bīngfēng de wàixīng hǎiyáng zhōng xúnzhǎo dìwài shēngmìng de zōngjì.', 'Thám hiểm môi trường biển sâu khắc nghiệt không chỉ giúp ta nhìn nhận lại bản chất kiên cường của sự sống trái đất, mà còn chỉ dẫn nhân loại tìm kiếm dấu vết sự sống ngoài hành tinh dưới các đại dương đóng băng.')], [('Quần xã sinh vật ở đáy biển sâu sinh tồn dựa vào nguồn năng lượng nào khi không có ánh sáng mặt trời?', ['Đốt than bùn', 'Vi khuẩn hóa dưỡng oxy hóa hydro sulfide từ miệng phun thủy nhiệt', 'Thức ăn do con người thả xuống'], 1, 'Trong bài có câu: 依靠化能合成自养细菌氧化硫化氢获取生存能量.'), ("Hệ sinh thái 'ống khói đen' đáy biển mang lại đóng góp quan trọng nào cho khoa học?", ['Phát hiện ra mỏ vàng lộ thiên', 'Cung cấp bằng chứng thực nghiệm vững chắc cho giả thuyết sự sống nguyên sơ bắt nguồn từ miệng phun nhiệt biển sâu', 'Bác bỏ sự tồn tại của vi khuẩn'], 1, 'Trong câu có viết: 为生命起源于深海热泉假说提供了极为有力的科学佐证.'), ('Nghiên cứu sinh vật biển sâu giúp ích gì cho các chuyến thám hiểm không gian vũ trụ?', ['Định hướng tìm kiếm sự sống ngoài trái đất dưới các đại dương băng giá của thiên thể khác', 'Dạy sinh vật biển lái tàu vũ trụ', 'Không có liên hệ'], 0, 'Trong câu cuối có viết: 指引着人类在冰封的外星海洋中寻找地外生命的踪迹.')]),
    (29, '全球数字治理与数据主权博弈', 'Quản trị kỹ thuật số toàn cầu và bài toán chủ quyền dữ liệu', 'digital_governance', 'Quan hệ quốc tế', '🌐', 5, 'Dòng chảy dữ liệu xuyên biên giới đặt ra bài toán bảo vệ an ninh quốc gia đi đôi với hợp tác kinh tế số minh bạch.', [('数据作为数字经济时代的核心战略资源，正深刻改变着全球地缘政治与国际经贸博弈的底层逻辑。', 'Shùjù zuòwéi shùzì jīngjì shídài de héxīn zhànlüè zīyuán, zhèng shēnkè gǎibiàn zhe quánqiú dìyuán-zhèngzhì yǔ guójì jīng-mào bóyì de dǐcéng luójí.', 'Dữ liệu với tư cách là tài nguyên chiến lược cốt lõi trong kỷ nguyên kinh tế số đang làm thay đổi sâu sắc logic nền tảng của địa chính trị và giao thương quốc tế toàn cầu.'), ('海量跨境数据的高速流通在极大降低国际商务成本的同时，也对各主权国家的数据安全和隐私保护带来了前所未有的严峻挑战。', 'Hǎiliàng kuàjìng shùjù de gāosù liútōng zài jídà jiàngdī guójì shāngwù chéngběn de tóngshí, yě duì gè zhǔquán guójiā de shùjù ānquán hé yǐnsī bǎohù dàilái le qiánsuǒwèiyǒu de yánjùn tiǎozhàn.', 'Dòng chảy dữ liệu xuyên biên giới khổng lồ với tốc độ cao vừa làm giảm mạnh chi phí kinh doanh quốc tế, vừa mang lại thử thách gay gắt chưa từng có cho an ninh dữ liệu và quyền riêng tư của các quốc gia có chủ quyền.'), ('许多国家相继出台严格的数据安全法律，要求涉及国家命脉的关键基础设施数据与公民个人隐私必须在境内本地化存储。', 'Xǔduō guójiā xiāngjì chūtái yángé de shùjù ānquán fǎlǜ, yāoqiú shèjí guójiā mìngmài de guānjiàn jīchǔ shèshī shùjù yǔ gōngmín gèrén yǐnsī bìxū zài jìngnèi běndìhuà cúnchǔ.', 'Nhiều quốc gia lần lượt ban hành luật an toàn dữ liệu nghiêm ngặt, yêu cầu dữ liệu hạ tầng huyết mạch và quyền riêng tư công dân phải được lưu trữ bản địa hóa trong nước.'), ('然而过度严苛的数据壁垒与数字巴尔干化倾向，可能会阻碍人工智能等全球前沿科研成果的技术共享与协同演进。', "Rán'ér guòdù yánkē de shùjù bìlěi yǔ shùzì Bā'ěrgànhuà qīngxiàng, kěnéng huì zǔ'ài réngōng zhìnéng děng quánqiú qiányán kēyán chéngguǒ de jìshù gòngxiǎng yǔ xiétóng yǎnjìn.", "Tuy vậy, các rào cản dữ liệu quá ngặt nghèo và xu hướng 'Balkan hóa kỹ thuật số' có thể cản trở chia sẻ công nghệ và hiệp đồng phát triển các thành tựu khoa học tiền phong như AI."), ('构建开放包容、安全有序的全球数字治理多边规则框架，是全人类携手迈向普惠数字文明的必由之路。', 'Gòujiàn kāifàng bāoróng, ānquán yǒuxù de quánqiú shùzì zhìlǐ duōbiān guīzé kuàngjià, shì quán rénlèi xiéshǒu màixiàng pǔhuì shùzì wénmíng de bìyóuzhīlù.', 'Xây dựng khuôn khổ quy tắc đa phương về quản trị kỹ thuật số toàn cầu cởi mở, an toàn và có trật tự là con đường tất yếu để toàn nhân loại cùng tiến tới văn minh số bao trùm.')], [('Tài nguyên nào được xem là tài nguyên chiến lược cốt lõi trong kỷ nguyên mới?', ['Dầu mỏ thô', 'Dữ liệu (Data) trong nền kinh tế số', 'Quặng sắt'], 1, 'Trong câu đầu có viết: 数据作为数字经济时代的核心战略资源.'), ('Chính sách mà nhiều nước áp dụng để bảo vệ thông tin huyết mạch quốc gia là gì?', ['Công khai toàn bộ dữ liệu lên mạng', 'Yêu cầu dữ liệu hạ tầng then chốt và thông tin công dân phải lưu trữ bản địa hóa trong nước', 'Cấm dùng máy tính'], 1, 'Trong câu có viết: 要求关键基础设施数据与公民个人隐私必须在境内本地化存储.'), ('Mục tiêu lý tưởng của quản trị kỹ thuật số toàn cầu là gì?', ['Xây dựng khuôn khổ quy tắc đa phương cởi mở, an toàn và bao trùm', 'Ngắt kết nối mạng giữa các châu lục', 'Độc quyền dữ liệu cho một vài công ty'], 0, 'Trong câu cuối có viết: 构建开放包容、安全有序的全球数字治理多边规则框架.')]),
    (30, '敦煌莫高窟壁画的数字化保护', 'Ứng dụng số hóa bảo tồn bích họa hang Mạc Cao Đôn Hoàng', 'dunhuang_heritage', 'Bảo tồn di sản', '🖼️', 5, 'Công nghệ quét quang phổ và mô hình hóa 3D giúp lưu giữ vĩnh cửu những kiệt tác nghìn năm trước nguy cơ bào mòn của thời gian.', [('矗立在鸣沙山崖壁之上的敦煌莫高窟，以其绵延千余年的飞天壁画与彩塑经卷，被尊为人类艺术史上最璀璨的东方明珠。', 'Chùlì zài Míngshāshān yábì zhī shàng de Dūnhuáng Mògāokū, yǐ qí miányán qiān yú nián de fēitiān bìhuà yǔ cǎisù jīngjuàn, bèi zūn wéi rénlèi yìshù shǐ shàng zuì cuǐcàn de dōngfāng míngzhū.', 'Sừng sững trên vách núi Minh Sa, hang Mạc Cao Đôn Hoàng với các bức bích họa Phi Thiên và tượng điêu khắc tô màu trải dài hơn ngàn năm được tôn vinh là viên ngọc phương Đông rực rỡ nhất lịch sử nghệ thuật.'), ('然而受风沙侵蚀、盐分起甲以及游客呼出的湿气二氧化碳影响，脆弱的古代壁画正在不可逆转地面临褪色脱落的自然老化宿命。', "Rán'ér shòu fēngshā qīnshí, yánfèn qǐjiǎ yǐjí yóukè hūchū de shīqì èryǎnghuàtàn yǐngxiǎng, cuìruò de gǔdài bìhuà zhèng bùkě-nìzhuǎn de miànlín tuìsè tuōluò de zìrán lǎohuà sùmìng.", 'Thế nhưng chịu ảnh hưởng của bão cát mài mòn, muối kết tinh bong tróc cùng hơi ẩm khí thở CO2 của du khách, các bức bích họa cổ mong manh đang đối mặt số phận phai màu rơi rụng không thể đảo ngược.'), ('为了与无情的时间赛跑，文物保护专家创造性地实施了数字敦煌工程，运用高保真三维激光扫描与多光谱色彩复原技术。', 'Wèile yǔ wúqíng de shíjiān sàipǎo, wénwù bǎohù zhuānjiā chuàngzàoxìng de shíshī le Shùzì Dūnhuáng gōngchéng, yùnyòng gāobǎozhēn sānwéi jīguāng sǎomiáo yǔ duōguāngpǔ sècǎi fùyuán jìshù.', "Để chạy đua với thời gian tàn nhẫn, các chuyên gia bảo tồn di vật đã triển khai dự án 'Đôn Hoàng số', ứng dụng quét laser 3D độ trung thực cao và phục hồi màu sắc đa quang phổ."), ('毫米级精度的数字化档案不仅实现了莫高窟艺术珍宝的永久性数字保存，更让全球艺术爱好者足不出户便能身临其境漫游窟内。', "Háomǐ jí jīngdù de shùzìhuà dàng'àn bùjǐn shíxiàn le Mògāokū yìshù zhēnbǎo de yǒngjiǔxìng shùzì bǎocún, gèng ràng quánqiú yìshù àihàozhě zú-bù-chū-hù biàn néng shēnlín-qíjìng mànyóu kū nèi.", 'Hồ sơ số hóa với độ chính xác cấp milimet không chỉ thực hiện lưu trữ số vĩnh viễn kho báu nghệ thuật Mạc Cao, mà còn giúp người yêu nghệ thuật toàn cầu không cần rời chân khỏi nhà vẫn du ngoạn chân thực trong hang động.'), ('科技与人文的深情相拥，让沉淀千年的敦煌文明穿越时空风尘，在虚拟的数字长河中永驻青春容颜。', 'Kējì yǔ rénwén de shēnqíng xiāngyōng, ràng chéndiàn qiān nián de Dūnhuáng wénmíng chuānyuè shíkōng fēngchén, zài xūnǐ de shùzì chánghé zhōng yǒng zhù qīngchūn róngyán.', 'Cái ôm sâu đậm giữa công nghệ và nhân văn giúp nền văn minh Đôn Hoàng ngàn năm vượt qua gió bụi thời gian, giữ mãi dung nhan tuổi trẻ trong dòng sông số hóa vô tận.')], [('Yếu tố nào đe dọa sự tồn tại của bích họa hang Mạc Cao Đôn Hoàng?', ['Không có ai chăm sóc', 'Bão cát ăn mòn, muối kết tinh bong tróc và hơi ẩm khí thở của du khách gây phai màu rơi rụng', 'Nắng chiếu quá mạnh bên trong hang'], 1, 'Trong bài có câu: 受风沙侵蚀、盐分起甲以及游客呼出的湿气二氧化碳影响，面临褪色脱落的自然老化宿命.'), ('Giải pháp công nghệ đột phá nào được các chuyên gia áp dụng để chạy đua với thời gian?', ['Sơn đè màu mới lên', "Dự án 'Đôn Hoàng số' dùng quét laser 3D siêu nét và phục hồi màu sắc đa quang phổ", 'Chụp vài tấm ảnh bằng điện thoại'], 1, 'Trong câu có viết: 实施了数字敦煌工程，运用高保真三维激光扫描与多光谱色彩复原技术.'), ('Lợi ích kép của việc số hóa bích họa Đôn Hoàng là gì?', ['Lưu trữ số vĩnh cửu và cho phép công chúng toàn cầu tham quan trải nghiệm từ xa mà không làm hại di tích', 'Bán bản quyền lấy tiền', 'Thay thế hoàn toàn hang động thật'], 0, 'Trong câu có viết: 实现了永久性数字保存，更让全球艺术爱好者足不出户便能身临其境漫游窟内.')]),
    (31, '行为经济学与非理性繁荣反思', 'Kinh tế học hành vi và nhìn nhận về sự hưng phấn phi lý trí', 'behavioral_economics', 'Kinh tế học hành vi', '📊', 5, 'Con người không phải cỗ máy duy lý hoàn hảo; tâm lý bầy đàn và thiên kiến nhận thức thường định hình các chu kỳ thị trường.', [('传统古典经济学建立在理性经济人的假说之上，设定个体总是能够在纷繁复杂的决策情境中做出利益最大化的最优选择。', 'Chuántǒng gǔdiǎn jīngjìxué jiànlì zài lǐxìng jīngjìrén de jiǎshuō zhī shàng, shèdìng gètǐ zǒngshì nénggòu zài fēnfán fùzá de juécè qíngjìng zhōng zuòchū lìyì zuìdàhuà de zuìyōu xuǎnzé.', "Kinh tế học cổ điển truyền thống được xây dựng trên giả thuyết 'con người kinh tế duy lý', mặc định các cá nhân luôn có thể đưa ra lựa chọn tối ưu hóa lợi ích cao nhất giữa các tình huống quyết sách phức tạp."), ('然而行为经济学的大量实证研究揭示，人类在面对风险与不确定性时，普遍受到认知偏差与心理账户的严重左右。', "Rán'ér xíngwéi jīngjìxué de dàliàng shízèng yánjiū jiēshì, rénlèi zài miànduì fēngxiǎn yǔ bùquèdìngxìng shí, pǔbiàn shòudào rènzhī piānchà yǔ xīnlǐ zhànghù de yánzhòng zuǒyòu.", 'Thế nhưng hàng loạt nghiên cứu thực chứng của kinh tế học hành vi đã chỉ ra rằng khi đối diện rủi ro và bất định, con người thường bị chi phối nặng nề bởi sai lệch nhận thức và tài khoản tâm lý.'), ('沉没成本谬误、从众效应以及对损失的极端厌恶，常常诱使投资者在资产泡沫膨胀期盲目跟风，助推非理性繁荣。', 'Chénmò chéngběn miùwù, cóngzhòng xiàoyìng yǐjí duì sǔnshī de jíduān yànwù, chángcháng yòushǐ tóuzīzhě zài zīchǎn pàomò péngzhàngqī mángmù gēnfēng, zhùtuī fēilǐxìng fánróng.', 'Ngụy biện chi phí chìm, hiệu ứng bầy đàn và tâm lý ghét mất mát cực độ thường xúi giục nhà đầu tư mù quáng chạy theo phong trào trong thời kỳ bong bóng tài sản phình to, thúc đẩy sự hưng phấn phi lý trí.'), ('唯有深刻洞悉人性弱点在市场博弈中的放大效应，监管机构与投资者才能建立起更为稳健的风险预警机制。', 'Wéiyǒu shēnkè dòngxī rénxìng ruòdiǎn zài shìchǎng bóyì zhōng de fàngdà xiàoyìng, jiānguǎn jīgòu yǔ tóuzīzhě cái néng jiànlì qǐ gèngwéi wěnjiàn de fēngxiǎn yùjǐng jīzhì.', 'Chỉ khi thấu suốt sâu sắc hiệu ứng phóng đại của điểm yếu nhân tính trong các ván cờ thị trường, cơ quan giám sát và nhà đầu tư mới có thể thiết lập cơ chế cảnh báo rủi ro vững vàng hơn.'), ('引入对人类心理机制的现实关照，不仅是对传统经济理论的深刻重构，更是驾驭现代金融波动的智慧指南。', 'Yǐnrù duì rénlèi xīnlǐ jīzhì de xiànshí guānzhào, bùjǐn shì duì chuántǒng jīngjì lǐlùn de shēnkè chónggòu, gèng shì jiàyù xiàndài jīnróng bōdòng de zhìhuì zhǐnán.', 'Đưa sự thấu suốt thực tế về cơ chế tâm lý con người vào kinh tế học không chỉ là sự tái cấu trúc sâu sắc lý thuyết kinh tế truyền thống, mà còn là kim chỉ nam trí tuệ để làm chủ những biến động tài chính hiện đại.')], [('Giả thuyết nền tảng của kinh tế học cổ điển truyền thống là gì?', ['Con người luôn hành động theo cảm tính', 'Con người kinh tế hoàn toàn duy lý và tối đa hóa lợi ích', 'Con người không thích tiền'], 1, 'Trong câu đầu có viết: 建立在理性经济人的假说之上，设定个体总是做出利益最大化的最优选择.'), ('Hiện tượng tâm lý nào thúc đẩy sự phình to của bong bóng thị trường (非理性繁荣)?', ['Chi phí chìm, hiệu ứng đám đông và tâm lý sợ tổn thất', 'Sự tính toán cẩn trọng tuyệt đối', 'Không mua bán gì'], 0, 'Trong câu có viết: 沉没成本谬误、从众效应以及对损失的极端厌恶，助推非理性繁荣.'), ('Ý nghĩa lớn nhất của kinh tế học hành vi đối với nhà đầu tư và cơ quan quản lý là gì?', ['Thấu hiểu điểm yếu của tâm lý con người để xây dựng cơ chế phòng ngừa rủi ro vững vàng', 'Làm giá cổ phiếu biến động mạnh hơn', 'Bỏ qua các chỉ số tài chính'], 0, 'Trong câu có viết: 深刻洞悉人性弱点在市场博弈中的放大效应，建立更为稳健的风险预警机制.')]),
    (32, '极端气候应对与韧性城市营建', 'Ứng phó thời tiết cực đoan và xây dựng đô thị kiên cường', 'climate_resilience', 'Kiến trúc & Khí hậu', '🌦️', 5, 'Đô thị bọt biển, đê chắn sóng thông minh và mạng lưới thoát nước đa tầng giúp thành phố đứng vững trước bão lũ dị thường.', [('受全球变暖引发的气候系统紊乱影响，特大暴雨、持续高温与超强台风等极端气象事件正呈现频发且强化的态势。', 'Shòu quánqiú biànnuǎn yǐnfā de qìhòu xìtǒng wènluàn yǐngxiǎng, tèdà bàoyǔ, chíxù gāowēn yǔ chāoqiáng táifēng děng jíduān qìxiàng shìjiàn zhèng chéngxxiàn pínfā qiě qiánghuà de tàishì.', 'Chịu ảnh hưởng bởi sự rối loạn hệ thống khí hậu do nóng lên toàn cầu, các hiện tượng thời tiết cực đoan như mưa bão kỷ lục, nắng nóng kéo dài và siêu bão đang có xu thế diễn ra dày đặc và tăng cấp khốc liệt.'), ('传统城市高度硬化的水泥下垫面与单一排涝工程，在面对突发超标降水时往往显得不堪重负，极易酿成城市内涝。', 'Chuántǒng chéngshì gāodù yìnghuà de shuǐní xiàdiànmiàn yǔ dānyī páilào gōngchéng, zài miànduì tūfā chāobiāo jiàngshuǐ shí wǎngwǎng xiǎnde bùkān-zhòngfù, jí yì niàngchéng chéngshì nèilào.', 'Bề mặt bê tông hóa cao độ cùng công trình thoát nước đơn điệu của đô thị truyền thống thường trở nên quá tải trước lượng mưa lớn đột biến, rất dễ gây ra ngập úng nội thành nghiêm trọng.'), ('建设韧性城市成为现代城市规划的核心转向，其宗旨在于赋予城市在遭受外部剧烈冲击时自我修复与快速反弹的弹性机能。', 'Jiànshè rènxìng chéngshì chéngwéi xiàndài chéngshì guīhuà de héxīn zhuǎnxiàng, qí zōngzhǐ zàiyú fùyǔ chéngshì zài zāoshòu wàibù jùliè chōngjī shí zìwǒ xiūfù yǔ kuàisù fǎntán de tánxìng jīnéng.', 'Xây dựng đô thị kiên cường (Resilient City) trở thành bước chuyển hướng cốt lõi trong quy hoạch hiện đại, với tôn chỉ trao cho đô thị cơ chế đàn hồi tự phục hồi và phục hồi nhanh trước các cú sốc bên ngoài.'), ('大力推行海绵城市建设理念，通过下沉式绿地、透水铺装与蓄涝人工湿地，实现对雨水的自然积存、自然渗透与自然净化。', 'Dàlì tuīxíng hǎimián chéngshì jiànshè lǐniàn, tōngguò xiàchénshì lǜdì, tòushuǐ pūzhuāng yǔ xùlào réngōng shīdì, shíxiàn duì yǔshuǐ de zìrán jīcún, zìrán shèntòu yǔ zìrán jìnghuà.', "Đẩy mạnh mô hình 'thành phố bọt biển' (Sponge City) thông qua dải xanh trũng ngập, vỉa hè thấm nước và vùng ngập nước nhân tạo để trữ nước, thẩm thấu và làm sạch tự nhiên."), ('让城市学会与洪水风暴等自然伟力共处共生，才能在风雨变幻的未来守护好数以亿计市民的生命财产安全。', 'Ràng chéngshì xuéhuì yǔ hóngshuǐ fēngbào děng zìrán wěilì gòngchǔ-gòngshēng, cái néng zài fēngyǔ biànhuàn de wèilái shǒuhù hǎo shù yǐ yì jì shìmín de shēngmìng cáichǎn ānquán.', 'Để thành phố học cách cùng chung sống hòa hợp với sức mạnh tự nhiên như mưa lũ gió bão mới có thể che chở an toàn tính mạng và tài sản cho hàng trăm triệu cư dân trong tương lai biến đổi khôn lường.')], [('Điểm yếu của các đô thị truyền thống khi gặp mưa bão kỷ lục là gì?', ['Mặt đường quá nhiều cây xanh', 'Bề mặt bê tông hóa cao và hệ thống cống đơn điệu dễ gây ngập úng nghiêm trọng', 'Không có điện'], 1, 'Trong bài có câu: 高度硬化的水泥下垫面与单一排涝工程，在面对突发超标降水时极易酿成城市内涝.'), ("Mục tiêu của mô hình 'đô thị kiên cường' (韧性城市) là gì?", ['Xây tường thành bao quanh đô thị', 'Trao cho thành phố khả năng tự phục hồi và đàn hồi nhanh sau các cú sốc thời tiết cực đoan', 'Chuyển toàn bộ thành phố vào trong nhà'], 1, 'Trong câu có viết: 赋予城市在遭受外部剧烈冲击时自我修复与快速反弹的弹性机能.'), ("Giải pháp của 'thành phố bọt biển' (海绵城市) xử lý nước mưa như thế nào?", ['Hút cạn nước biển', 'Dùng dải xanh trũng, vật liệu thấm nước và vùng đất ngập để tích trữ, thẩm thấu và lọc sạch tự nhiên', 'Xả hết nước vào nhà dân'], 1, 'Trong câu có viết: 通过下沉式绿地、透水铺装与人工湿地，实现雨水的自然积存、自然渗透与自然净化.')]),
    (33, '脑机接口技术的突破与伦理反思', 'Đột phá công nghệ giao diện não - máy và suy ngẫm đạo đức học', 'bci_ethics', 'Y đức & Công nghệ', '⚡', 5, 'Đọc và dịch chuyển tín hiệu xung thần kinh kết nối não bộ với máy tính mang lại hy vọng y học nhưng cũng đặt ra ranh giới luân lý.', [('脑机接口技术通过在高精度微电极与皮层神经元之间架设通信桥梁，实现了大脑神经生物电信号向计算机指令的直接转译。', 'Nǎo-jī jiēkǒu jìshù tōngguò zài gāojīngdù wēidiànjí yǔ pícéng shénjīngyuán zhījiān jiàshè tōngxìn qiáoliáng, shíxiàn le dànǎo shénjīng shēngwùdiàn xìnhào xiàng jìsuànjī zhǐlìng de zhíjiē zhuǎnyì.', 'Công nghệ giao diện não - máy (BCI) thông qua việc bắc nhịp cầu thông tin giữa vi điện cực siêu chính xác và nơ-ron vỏ não đã hiện thực hóa việc chuyển dịch trực tiếp tín hiệu điện sinh học thần kinh thành khẩu lệnh máy tính.'), ('这项尖端科技为高位截瘫患者通过意念操控机械臂重新自理生活、为渐冻症患者重获与外界流畅对话能力点亮了希望之光。', 'Zhè xiàng jiānduān kējì wèi gāowèi jiétān huànzhě tōngguò yìniàn cāokòng jīxièbì chóngxīn zìlǐ shēnghuó, wèi jiàndòngzhèng huànzhě chónghuò yǔ wàijiè liúchàng duìhuà nénglì diǎnliàng le xīwàng zhī guāng.', 'Công nghệ đỉnh cao này đã thắp sáng tia hy vọng cho bệnh nhân liệt toàn thân có thể dùng ý nghĩ điều khiển cánh tay robot tự phục vụ và giúp bệnh nhân xơ cứng teo cơ (ALS) lấy lại khả năng đối thoại trôi chảy.'), ('然而随着神经解码精度的突飞猛进，该技术若被用于非医疗目的的情绪操纵、记忆干预乃至隐私入侵，将引发空前激烈的伦理诘问。', "Rán'ér suízhe shénjīng jiěmǎ jīngdù de tūfēi-měngjìn, gāi jìshù ruò bèi yòngyú fēi yīliáo mùdì de qíngxù cāozòng, jìyì gānyù nǎizhì yǐnsī rùqīn, jiāng yǐnfā kōngqián jīliè de lúnlǐ jiéwèn.", 'Tuy nhiên khi độ chính xác giải mã thần kinh tiến bộ thần tốc, nếu công nghệ này bị dùng cho mục đích phi y tế như thao túng cảm xúc, can thiệp ký ức hay xâm phạm quyền riêng tư tư tưởng, nó sẽ dấy lên chất vấn đạo đức gay gắt chưa từng có.'), ('当外在芯片算法能够反向重构人类的自主意志与思维活动时，人类主体的自主自由意志与传统人格定义将面临根本性的动摇。', 'Dāng wàizài xīnpiàn suànfǎ nénggòu fǎnxiàng chónggòu rénlèi de zìzhǔ yìzhì yǔ sīwéi huódòng shí, rénlèi zhǔtǐ de zìzhǔ zìyóu yìzhì yǔ chuántǒng réngé dìngyì jiāng miànlín gēnběnxìng de dòngyáo.', 'Khi thuật toán chip bên ngoài có thể tái cấu trúc ngược lại ý chí tự chủ và hoạt động tư duy con người, ý chí tự do và định nghĩa nhân cách truyền thống sẽ đứng trước sự lung lay tận gốc.'), ('在向神经科学前沿无人区挺进的征途上，给科技插上理性的道德缰绳，是保障科技造福人类而不是异化人类的根本底线。', 'Zài xiàng shénjīng kēxué qiányán wúrénqū tǐngjìn de zhēngtú shàng, gěi kējì chā shàng lǐxìng de dàodé jiāngshéng, shì bǎozhàng kējì zàofú rénlèi ér bú shì yìhuà rénlèi de gēnběn dǐxiàn.', 'Trên hành trình tiến vào vùng đất chưa khai phá của khoa học thần kinh, buộc dây cương đạo đức lý tính cho công nghệ là lằn ranh đỏ căn bản để bảo đảm công nghệ phục vụ nhân loại chứ không tha hóa con người.')], [('Ứng dụng y học đột phá nhất của giao diện não - máy là gì?', ['Chơi trò chơi điện tử', 'Giúp bệnh nhân bại liệt dùng ý nghĩ điều khiển chi giả và bệnh nhân ALS giao tiếp với thế giới', 'Xóa bỏ việc ngủ nghỉ'], 1, 'Trong bài có câu: 为高位截瘫患者通过意念操控机械臂，为渐冻症患者重获对话能力点亮希望之光.'), ('Mối lo ngại đạo đức lớn nhất đối với việc phát triển công nghệ thần kinh sâu là gì?', ['Tốn quá nhiều pin', 'Nguy cơ thao túng cảm xúc, can thiệp trí nhớ và xâm phạm quyền riêng tư tư tưởng', 'Làm mất sóng điện thoại'], 1, 'Trong câu có viết: 若被用于非医疗目的的情绪操纵、记忆干预乃至隐私入侵，将引发空前激烈的伦理诘问.'), ('Lằn ranh đỏ để công nghệ phát triển lành mạnh vì nhân loại là gì?', ['Không cần bất kỳ sự quản lý nào', 'Buộc dây cương đạo đức lý tính cho công nghệ để tránh tha hóa bản sắc con người', 'Ngừng toàn bộ nghiên cứu y khoa'], 1, 'Trong câu cuối có viết: 给科技插上理性的道德缰绳，是保障科技造福人类而不是异化人类的根本底线.')]),
    (34, '比较文学视野下的神话母题互融', 'Mô-típ thần thoại tương đồng dưới góc nhìn văn học so sánh', 'comparative_literature', 'Văn học so sánh', '📚', 5, 'Đại hồng thủy, sáng thế hay anh hùng diệt quái vật: Những câu chuyện cổ xưa phản ánh tâm thức chung của toàn nhân loại.', [('远古神话是人类童年时期的集体幻想结晶，蕴藏着各个文明在面对天地自然巨变时的原始惊惧与浪漫崇拜。', 'Yuǎngǔ shénhuà shì rénlèi tóngnián shíqī de jítǐ huànxiǎng jiéjīng, yùncáng zhe gègè wénmíng zài miànduì tiāndì zìrán jùbiàn shí de yuánshǐ jīngjù yǔ làngmàn chóngbài.', 'Thần thoại viễn cổ là sự kết tinh của trí tưởng tượng tập thể thời thơ ấu của nhân loại, chứa đựng nỗi kinh sợ nguyên sơ và sự sùng bái lãng mạn của các nền văn minh trước biến thiên trời đất.'), ('比较文学学者通过对东西方跨地域神话体系的系统比对，惊讶地发现了诸多高度吻合的核心母题叙事。', 'Bǐjiào wénxué xuézhě tōngguò duì dōng-xīfāng kuà-dìyù shénhuà tǐxì de xìtǒng bǐduì, jīngyà de fāxiàn le zhūduō gāodù wènhé de héxīn mǔtí xùshì.', 'Các học giả văn học so sánh thông qua đối chiếu hệ thống thần thoại xuyên khu vực Đông - Tây đã kinh ngạc phát hiện ra vô số mô-típ tự sự cốt lõi trùng khớp cao độ.'), ('无论是苏美尔泥板、希伯来圣经中记载的史前大洪水，还是华夏神话中大禹治水、女娲补天的壮烈史诗，都展现了人类抗击洪灾的集体记忆。', "Wúlùn shì Sūmèi'ěr níbǎn, Xībólái Shèngjīng zhōng jìzǎi de shǐqián dà hóngshuǐ, háishì Huáxià shénhuà zhōng Dà Yǔ zhìshuǐ, Nǚwā bǔtiān de zhuàngliè shǐshī, dōu zhǎnxiàn le rénlèi kàngjī hóngzāi de jítǐ jìyì.", 'Bất kể là phiến sét Sumer, Kinh thánh Do Thái ghi chép về đại hồng thủy tiền sử, hay huyền thoại Đại Vũ trị thủy, Nữ Oa vá trời trong thần thoại Trung Hoa, đều thể hiện ký ức tập thể về cuộc chiến chống lũ.'), ('这种跨越地理天堑的母题重合，深刻折射出人类在面对生存繁衍、生命脆弱与英雄牺牲时共同的精神心理结构。', 'Zhè zhǒng kuàyuè dìlǐ tiānqiàn de mǔtí chónghé, shēnkè zhéshè chū rénlèi zài miànduì shēngcún fányǎn, shēngmìng cuìruò yǔ yīngxióng xīshēng shí gòngtóng de jīngshén xīnlǐ jiégòu.', 'Sự trùng hợp mô-típ vượt qua vực thẳm địa lý phản ánh sâu sắc cấu trúc tâm lý tinh thần chung của nhân loại khi đối diện sinh tồn nảy nở, sự mong manh của sinh mệnh và sự hy sinh anh hùng.'), ('在多元神话的异质表象之下，深藏着全人类心灵深处永恒相通的生命悲悯与对光明正义的不懈追求。', 'Zài duōyuán shénhuà de yìzhì biǎoxiàng zhī xià, shēncáng zhe quán rénlèi xīnlíng shēnchù yǒnghéng xiāngtōng de shēngmìng bēimǐn yǔ duì guāngmíng zhèngyì de búxiè zhuīqiú.', 'Dưới vẻ bề ngoài dị biệt của các câu chuyện thần thoại đa dạng ẩn chứa lòng trắc ẩn sinh mệnh vĩnh hằng tương thông và khát vọng không ngơi nghỉ hướng về ánh sáng chính nghĩa của toàn nhân loại.')], [('Phát hiện bất ngờ của các học giả văn học so sánh khi nghiên cứu thần thoại các nền văn minh là gì?', ['Mỗi nơi kể một chuyện hoàn toàn không liên quan', 'Có sự trùng hợp cao độ về các mô-típ tự sự cốt lõi như đại hồng thủy, sáng thế', 'Thần thoại chỉ có ở châu Âu'], 1, 'Trong bài có câu: 惊讶地发现了诸多高度吻合的核心母题叙事.'), ('Ví dụ tiêu biểu về ký ức tập thể chống thiên tai của nhân loại là gì?', ['Chuyện săn bắn hái lượm', 'Huyền thoại về trận đại hồng thủy xuất hiện ở cả văn minh Lưỡng Hà, Do Thái và truyện Đại Vũ trị thủy phương Đông', 'Chuyện xây dựng kim tự tháp'], 1, 'Trong câu có viết: 苏美尔泥板、希伯来圣经与华夏大禹治水，都展现了抗击洪灾的集体记忆.'), ('Ý nghĩa sâu sắc của sự tương đồng trong các mô-típ thần thoại là gì?', ['Chứng minh loài người có cùng nguồn cội tâm lý tinh thần, lòng trắc ẩn và khát vọng chính nghĩa', 'Chỉ là sự sao chép ngẫu nhiên', 'Không mang giá trị nghiên cứu'], 0, 'Trong câu cuối có viết: 折射出人类共同的精神心理结构，深藏着永恒相通的生命悲悯与追求.')]),
    (35, '氢能开发与碳中和能源图景', 'Khai thác năng lượng hydro và viễn cảnh trung hòa carbon', 'hydrogen_energy', 'Năng lượng tương lai', '🔋', 5, "Được mệnh danh là 'năng lượng tối thượng của thế kỷ 21', hydro xanh hứa hẹn khử carbon triệt để trong giao thông và công nghiệp nặng.", [('为了实现全球深度脱碳与遏制气候灾变，寻找高能量密度且燃烧产物完全清洁的替代能源成为了时代的迫切呼唤。', 'Wèile shíxiàn quánqiú shēndù tuōtàn yǔ èzhì qìhòu zāibiàn, xúnzhǎo gāo néngliàng mìdù qiě ránshāo chǎnwù wánquán qīngjié de tìdài néngyuán chéngwéi le shídài de pòqiè hūhuàn.', 'Để đạt được mục tiêu phi carbon hóa sâu rộng và ngăn chặn thảm họa khí hậu toàn cầu, việc tìm kiếm nguồn năng lượng thay thế mật độ cao và sản phẩm cháy hoàn toàn sạch đã trở thành tiếng gọi cấp thiết của thời đại.'), ('氢能因其燃烧热值高、反应生成物仅为纯水而无任何碳排放，被公认为二十一世纪最具潜力的终极绿色能源载体。', 'Qīngnéng yīn qí ránshāo rèzhí gāo, fǎnyìng shēngchéngwù jǐn wéi chúnshuǐ ér wú rènhé tàn páifàng, bèi gōngrèn wéi èrshíyī shìjì zuì jù qiánlì de zhōngjí lǜsè néngyuán zàitǐ.', 'Năng lượng hydro nhờ nhiệt trị cháy cao, sản phẩm phản ứng chỉ là nước tinh khiết không phát thải bất kỳ lượng carbon nào, được công nhận là vật mang năng lượng xanh tối thượng tiềm năng nhất thế kỷ 21.'), ('利用风能、太阳能等可再生电力进行电解水制备绿氢，彻底斩断了传统制氢工艺对化石燃料原料的深重依赖路径。', 'Lìyòng fēngnéng, tàiyángnéng děng kězàishēng diànlì jìnxíng diànjiěshuǐ zhìbèi lǜqīng, chèdǐ zhǎnduàn le chuántǒng zhìqīng gōngyì duì huàshí ránliào yuánliào de shēnzhòng yīlài lùjìng.', "Ứng dụng điện tái tạo từ gió và mặt trời để điện phân nước sản xuất 'hydro xanh' đã cắt đứt hoàn toàn con đường phụ thuộc sâu vào nhiên liệu hóa thạch của công nghệ hydro truyền thống."), ('然而，氢气极易燃爆与超低密度的物理特性，对超高压气态储存、深冷液化储运以及安全输配管网提出了严苛的技术考验。', "Rán'ér, qīngqì jí yì ránbào yǔ chāodī mìdù de wùlǐ tèxìng, duì chāogāoyā qìtài chǔcún, shēnlěng yèhuà chǔyùn yǐjí ānquán shūpèi guǎnwǎng tíchū le yánkē de jìshù kǎoyàn.", 'Thế nhưng, đặc tính vật lý cực kỳ dễ cháy nổ và mật độ siêu thấp của khí hydro đặt ra thử thách kỹ thuật khắt khe cho lưu trữ thể khí siêu cao áp, hóa lỏng vận chuyển siêu lạnh và mạng lưới đường ống an toàn.'), ('随着全产业链核心技术的相继攻克，绿氢生态体系必将为钢铁冶金、重卡交通等难减排行业撑起碳中和的蔚蓝明天。', 'Suízhe quán chǎnyèliàn héxīn jìshù de xiāngjì gōngkè, lǜqīng shēngtài tǐxì bìjiāng wèi gāngtiě yějīn, zhòngkǎ jiāotōng děng nán jiǎnpái hángyè chēng qǐ tànzhōnghé de wèilán míngtiān.', 'Cùng với việc lần lượt chinh phục các công nghệ cốt lõi trong toàn chuỗi công nghiệp, hệ sinh thái hydro xanh chắc chắn sẽ dựng nên bầu trời mai sau trung hòa carbon cho các ngành khó giảm phát thải như luyện kim gang thép và vận tải xe tải nặng.')], [('Vì sao hydro được mệnh danh là nguồn năng lượng sạch tối thượng?', ['Vì giá rất rẻ', 'Vì nhiệt trị cao và sản phẩm cháy duy nhất là nước, hoàn toàn không phát thải carbon', 'Vì có màu xanh lá cây'], 1, 'Trong bài có câu: 燃烧热值高、反应生成物仅为纯水而无任何碳排放.'), ("'Hydro xanh' (绿氢) được sản xuất bằng phương pháp nào?", ['Đốt than đá', 'Dùng điện gió và điện mặt trời tái tạo để điện phân nước', 'Khai thác trực tiếp từ mỏ dầu'], 1, 'Trong câu có viết: 利用风能、太阳能等可再生电力进行电解水制备绿氢.'), ('Thách thức kỹ thuật lớn nhất đối với việc ứng dụng quy mô lớn của hydro là gì?', ['Lưu trữ siêu cao áp, vận chuyển hóa lỏng siêu lạnh và an toàn phòng chống cháy nổ', 'Không tìm thấy nước để điện phân', 'Khí hydro quá nặng'], 0, 'Trong câu có viết: 对超高压气态储存、深冷液化储运以及安全输配管网提出了严苛的技术考验.')]),
    (36, '博物馆文物的预防性微环境监测', 'Giám sát vi khí hậu phòng ngừa rủi ro cho hiện vật bảo tàng', 'museum_conservation', 'Khoa học bảo tàng', '🏛️', 5, 'Cảm biến vi mô không dây kiểm soát nhiệt độ, độ ẩm và khí độc hại 24/7 giúp bảo vệ cổ vật khỏi hư hại âm thầm.', [('陈列于博物馆恒温展柜中的珍贵古代书画、青铜器与丝织物，时刻经受着肉眼难以察觉的微观环境衰变威胁。', 'Chénliè yú bówùguǎn héngwēn zhǎnguì zhōng de zhēnguì gǔdài shūhuà, qīngtóngqì yǔ sīzhīwù, shíkè jīngshòu zhe ròuyǎn nányǐ chájào de wēiguān huánjìng shuāibiàn wēixié.', 'Những bức thư họa cổ, đồ đồng và lụa là quý giá trưng bày trong tủ kính bảo tàng luôn chịu sự đe dọa biến chất của môi trường vi khí hậu mà mắt thường khó nhận biết.'), ('展柜内环境温度与相对湿度的剧烈波动、微量有机挥发性酸性气体以及光照紫外线，都是加速文物纤维脆化和金属腐蚀的隐形元凶。', 'Zhǎnguì nèi huánjìng wēndù yǔ xiāngduì shīdù de jùliè bōdòng, wēiliàng yǒujī huīfāxìng suānxìng qìtǐ yǐjí guāngzhào zǐwàixiàn, dōu shì jiāsù wénwù xiānwéi cuìhuà hé jīnshǔ fǔshí de yǐnxíng yuánxiōng.', 'Biến động mạnh của nhiệt độ và độ ẩm tương đối trong tủ kính, các chất khí axit hữu cơ bay hơi li ti cùng tia cực tím của ánh sáng đều là thủ phạm vô hình thúc đẩy sợi xơ giòn gãy và kim loại ăn mòn.'), ('现代文物保护已经从病害发生后的事后抢救性修复，深刻转型为防患于未然的全流程预防性监测控制体系。', 'Xiàndài wénwù bǎohù yǐjīng cóng bìnghài fāshēng hòu de shìhòu qiǎngjiùxìng xiūfù, shēnkè zhuǎnxíng wéi fánghuàn-yú-wèirán de quán liúchéng yùfángxìng jiāncè kòngzhì tǐxì.', 'Bảo tồn hiện vật hiện đại đã chuyển mình sâu sắc từ sửa chữa cứu vãn bị động sau khi hư hại sang hệ thống giám sát kiểm soát phòng ngừa toàn quy trình ngay từ trong trứng nước.'), ('科研团队在展柜与库房中部署了微型物联网无线传感器阵列，能够实时精准采集并分析十余项微环境环境指标。', 'Kēyán tuánduì zài zhǎnguì yǔ kùfáng zhōng bùshǔ le wēixíng wùliánwǎng wúxiàn chuángǎnqì zhènliè, nénggòu shíshí jīngzhǔn cǎijí bìng fēnxī shí yú xiàng wēihuánjìng huánjìng zhǐbiāo.', 'Đội ngũ nghiên cứu khoa học bố trí mạng lưới cảm biến không dây IoT vi mô trong tủ trưng bày và kho lưu trữ, có thể thu thập và phân tích chuẩn xác theo thời gian thực hơn 10 chỉ số vi môi trường.'), ('这种科技织就的无形保护伞，为脆弱的千年文化遗产构筑了坚固屏障，让历史文明的温度得以长久安然传递。', 'Zhè zhǒng kējì zhī jiù de wúxíng bǎohùsǎn, wèi cuìruò de qiān nián wénhuà yíchǎn gòuzhù le jiāngù píngzhàng, ràng lìshǐ wénmíng de wēndù déyǐ chángjiǔ ānrán chuándì.', 'Chiếc ô bảo bọc vô hình dệt nên bằng công nghệ đã dựng nên bức bình phong vững chắc cho di sản ngàn năm mong manh, để hơi ấm của văn minh lịch sử truyền mãi an lành muôn đời.')], [('Thủ phạm vô hình gây hư hại cho tranh cổ và đồ lụa trong tủ kính là gì?', ['Khách tham quan chạm tay', 'Nhiệt độ ẩm dao động thất thường, khí axit bay hơi và tia cực tím', 'Mực in tự biến mất'], 1, 'Trong bài có câu: 相对湿度的剧烈波动、微量有机挥发性酸性气体以及光照紫外线，都是隐形元凶.'), ('Bước chuyển mình quan trọng nhất của ngành bảo tồn hiện vật hiện đại là gì?', ['Chỉ sửa chữa khi đồ đã vỡ nát', 'Chuyển từ sửa chữa cứu vãn bị động sang hệ thống giám sát phòng ngừa toàn diện từ sớm', 'Dừng triển lãm hoàn toàn'], 1, 'Trong câu có viết: 从事后抢救性修复，转型为防患于未然的全流程预防性监测控制体系.'), ('Công cụ công nghệ nào được dùng để theo dõi sức khỏe của cổ vật 24/7?', ['Máy đo nhiệt kế thủy ngân cổ', 'Mạng lưới cảm biến không dây IoT vi mô đo thời gian thực hơn mười chỉ số vi khí hậu', 'Chỉ dựa vào mắt nhìn người gác'], 1, 'Trong câu có viết: 部署了微型物联网无线传感器阵列，实时精准采集分析十余项指标.')]),
    (37, '群体心理学视角下的网络极化', 'Hiện tượng cực đoan hóa quan điểm mạng dưới góc nhìn tâm lý đám đông', 'group_psychology', 'Tâm lý xã hội', '👥', 5, "Thuật toán 'phòng vang thông tin' và hiệu ứng đám đông dễ biến các cuộc thảo luận trực tuyến thành cuộc chiến nhãn dán đối đầu gay gắt.", [('互联网原本被寄予促进全球开放对话、弥合社会认知分歧的崇高厚望，然而当下网络空间的言论生态却日益呈现极化撕裂态势。', "Hùliánwǎng yuánběn bèi jìyǔ cùjìn quánqiú kāifàng duìhuà, míhé shèhuì rènzhī fēnqí de chónggāo hòuwàng, rán'ér dāngxià wǎngluò kōngjiān de yánlùn shēngtài què rìyì chéngxiàn jíhuà sīliè tàishì.", 'Internet vốn dĩ được gửi gắm kỳ vọng cao cả về việc thúc đẩy đối thoại cởi mở toàn cầu và hàn gắn bất đồng nhận thức xã hội, thế nhưng sinh thái ngôn luận trên không gian mạng hiện nay lại ngày càng lộ rõ xu thế phân cực chia rẽ.'), ('个性化算法推荐机制通过不断投喂符合用户既有偏好的内容，悄然构筑起密不透风的信息茧房与网络回音室。', 'Gèxìnghuà suànfǎ tuījiàn jīzhì tōngguò búduàn tóuwèi fúhé yònghù jìyǒu piānhào de nèiróng, qiǎorán gòuzhù qǐ mì-bù-tòufēng de xìnxī jiǎnfáng yǔ wǎngluò huíyīnshì.', "Cơ chế thuật toán gợi ý cá nhân hóa thông qua việc liên tục cung cấp nội dung phù hợp sở thích sẵn có đã âm thầm dựng nên 'kén thông tin' (Information Cocoon) và 'phòng vang dội' (Echo Chamber) kín mít."), ('在同质化社群内部的高频共振之下，群体成员往往在情绪互相激化中丧失了反思能力，将温和的折中立场排斥为异端。', 'Zài tóngzhìhuà shèqún nèibù de gāopín gòngzhèn zhī xià, qúntǐ chéngyuán wǎngwǎng zài qíngxù hùxiāng jīhuà zhōng sàngshī le fǎnsī nénglì, jiāng wēnhé de zhézhōng lìchǎng páichì wéi yìduān.', 'Dưới sự cộng hưởng tần số cao trong các cộng đồng đồng nhất, các thành viên thường đánh mất khả năng tự phản tư khi cảm xúc bị kích động lẫn nhau, bài trừ lập trường dung hòa ôn hòa như một tà thuyết.'), ('匿名机制与群体盲从心理的叠加，更容易诱发缺乏理智的网络暴力与肆无忌惮的标签化人身攻击。', 'Nìmíng jīzhì yǔ qúntǐ mángcóng xīnlǐ de diéjiā, gèng róngyì yòufā quēfá lǐzhì de wǎngluò bàolì yǔ sìwúdàndàn de biāoqiānhuà rénshēn gōngjī.', 'Cơ chế ẩn danh cộng hưởng với tâm lý mù quáng theo đám đông càng dễ châm ngòi cho bạo lực mạng thiếu lý trí và sự công kích cá nhân dán nhãn vô căn cứ.'), ('重塑多元包容的公共理性讨论空间，培育公众批判性思维与跨群体沟通素养，是化解数字时代极化困境的根本解药。', 'Chóngsù duōyuán bāoróng de gōnggòng lǐxìng tǎolùn kōngjiān, péiyù gōngzhòng pīpànxìng sīwéi yǔ kuà-qúntǐ gōutōng sùyǎng, shì huàjiě shùzì shídài jíhuà kùnjìng de gēnběn jiěyào.', 'Tái thiết không gian thảo luận lý tính công cộng đa nguyên bao dung, bồi dưỡng tư duy phản biện và năng lực giao tiếp xuyên nhóm cho công chúng là liều thuốc giải căn bản cho bài toán phân cực thời đại số.')], [('Cơ chế thuật toán nào góp phần tạo nên hiện tượng quan điểm bị phân cực trên mạng?', ['Thuật toán tìm kiếm ngẫu nhiên', 'Thuật toán gợi ý cá nhân hóa liên tục đưa tin hợp sở thích tạo nên kén thông tin và phòng vang dội', 'Thuật toán dịch tự động'], 1, 'Trong bài có câu: 个性化算法推荐机制通过不断投喂符合偏好的内容，构筑起信息茧房与回音室.'), ('Hậu quả tâm lý của sự cộng hưởng trong các hội nhóm cùng quan điểm là gì?', ['Trở nên thấu hiểu người khác hơn', 'Cảm xúc bị kích động quá đà, mất khả năng tự phản tư và bài xích ý kiến ôn hòa', 'Tự động tắt mạng'], 1, 'Trong câu có viết: 在情绪互相激化中丧失了反思能力，将温和的折中立场排斥为异端.'), ('Giải pháp cốt lõi để tháo gỡ bế tắc phân cực trên không gian số là gì?', ['Cấm hoàn toàn việc bình luận', 'Tái thiết không gian thảo luận lý tính công cộng và bồi dưỡng tư duy phản biện cho cộng đồng', 'Đóng cửa tất cả mạng xã hội'], 1, 'Trong câu cuối có viết: 重塑多元包容的公共理性讨论空间，培育批判性思维与跨群体沟通素养.')]),
    (38, '跨流域生态补偿与水资源治理', 'Bồi hoàn sinh thái liên lưu vực và quản trị an ninh nguồn nước', 'water_governance', 'Tài nguyên nước', '💧', 5, 'Vùng hạ lưu kinh tế phát triển chi trả kinh phí hỗ trợ vùng thượng lưu bảo tồn rừng đầu nguồn là bài học thành công về phát triển xanh.', [('江河流水是连通不同行政区域与经济板块的生态命脉，其水质优劣直接关系着亿万居民的生存发展根基。', 'Jiānghé liúshuǐ shì liántōng bùtóng xíngzhèng qūyù yǔ jīngjì bǎikuài de shēngtài mìngmài, qí shuǐzhì yōuliè zhíjiē guānxì zhe yì wàn jūmín de shēngcún fāzhǎn gēnjī.', 'Dòng chảy sông ngòi là huyết mạch sinh thái kết nối các phân khu hành chính và mảng kinh tế khác nhau, chất lượng nguồn nước liên quan trực tiếp tới nền tảng sinh tồn và phát triển của hàng trăm triệu cư dân.'), ('长期以来，大江大河的上游水源保护区因限制工业发展而承担了巨大的生态保护成本与发展机会损失。', 'Chángqī yǐlái, dàjiāng-dàhé de shàngyóu shuǐyuán bǎohùqū yīn xiànzhì gōngyè fāzhǎn ér chéngdān le jùdà de shēngtài bǎohù chéngběn yǔ fāzhǎn jīhuì sǔnshī.', 'Suốt thời gian dài, các khu vực bảo tồn nguồn nước ở thượng lưu sông lớn do hạn chế phát triển công nghiệp đã phải gánh chịu chi phí bảo tồn sinh thái và mất mát cơ hội kinh tế khổng lồ.'), ('而坐享优质清洁水源的下游发达地区，如果在经济上缺乏对上游的反哺机制，往往容易激化区域之间的发展不公矛盾。', 'Ér zuòxiǎng yōuzhì qīngjié shuǐyuán de xiàyóu fādá dìqū, rúguǒ zài jīngjì shàng quēfá duì shàngyóu de fǎnbǔ jīzhì, wǎngwǎng róngyì jīhuà qūyù zhījiān de fāzhǎn bùgōng máodùn.', 'Trong khi đó các vùng hạ lưu phát triển hưởng lợi từ nguồn nước sạch, nếu thiếu cơ chế bồi hoàn kinh tế cho thượng lưu, rất dễ làm gay gắt thêm mâu thuẫn bất bình đẳng phát triển vùng.'), ('实施跨流域横向生态保护补偿机制，通过明确出境断面水质考核标准，由下游向下游支付专项生态补偿金。', 'Shíshī kuà-liùyù héngxiàng shēngtài bǎohù bǔcháng jīzhì, tōngguò míngquè chūjìng duànmiàn shuǐzhì kǎohé biāozhǔn, yóu xiàyóu xiàng shàngyóu zhīfù zhuānxiàng shēngtài bǔchángjīn.', 'Thực thi cơ chế bồi hoàn sinh thái ngang liên lưu vực thông qua xác định rõ tiêu chuẩn kiểm tra chất lượng nước tại mặt cắt ranh giới, hạ lưu sẽ chi trả kinh phí bồi hoàn chuyên dùng cho thượng lưu.'), ('谁受益谁补偿、谁保护谁得益的制度创新，实现了流域上下游绿水青山与金山银山的和谐双赢共富。', 'Shéi shòuyì shéi bǔcháng, shéi bǎohù shéi déyì de zhìdù chuàngxīn, shíxiàn le liùyù shàng-xiàyóu lǜshuǐ-qīngshān yǔ jīnshān-yínshān de héxié shuāngyíng gòngfù.', "Sự đổi mới thể chế 'Ai hưởng lợi người đó bồi hoàn, ai bảo vệ người đó hưởng lợi' đã hiện thực hóa kết quả đôi bên cùng thắng hài hòa giữa núi xanh nước biếc và thịnh vượng kinh tế của toàn lưu vực.")], [('Vấn đề bất bình đẳng giữa thượng lưu và hạ lưu các dòng sông là gì?', ['Thượng lưu không có nước uống', 'Thượng lưu phải hy sinh cơ hội phát triển công nghiệp để bảo vệ nguồn nước nhưng hạ lưu hưởng lợi lại không hỗ trợ', 'Hạ lưu nghèo hơn thượng lưu'], 1, 'Trong bài có câu: 上游水源保护区承担了巨大生态保护成本与机会损失，下游缺乏反哺机制容易激化矛盾.'), ('Cơ chế bồi hoàn sinh thái liên lưu vực (横向生态保护补偿) vận hành ra sao?', ['Chặn đập giữ nước không cho chảy', 'Dựa trên chất lượng nước đo tại ranh giới, vùng hạ lưu chuyển kinh phí bồi hoàn hỗ trợ kinh tế cho vùng thượng lưu', 'Di dời toàn bộ dân hạ lưu lên thượng lưu'], 1, 'Trong câu có viết: 明确出境断面水质考核标准，由下游向上游支付专项生态补偿金.'), ('Nguyên tắc cốt lõi mang lại thắng lợi kép cho thể chế bảo tồn này là gì?', ['Ai mạnh người đó thắng', 'Ai hưởng lợi người đó bồi hoàn, ai bảo vệ người đó được hưởng lợi (谁受益谁补偿、谁保护谁得益)', 'Mặc kệ thượng lưu tự xử lý'], 1, 'Trong câu cuối có viết: 谁受益谁补偿、谁保护谁得益的制度创新，实现上下游和谐双赢.')]),
    (39, '戏剧张力营造与受众心理共鸣', 'Kiến tạo kịch tính sân khấu và sự cộng hưởng tâm lý khán giả', 'dramatic_arts', 'Kịch nghệ học', '🎭', 5, 'Nghệ thuật thắt nút mở nút, xung đột tính cách và tình huống trớ trêu đẩy cảm xúc người xem đến đỉnh điểm thanh lọc tâm hồn.', [('戏剧作为集文学、表演与舞美于一体的综合综合艺术形式，其最扣人心弦的艺术魅力莫过于跌宕起伏的戏剧张力。', 'Xìjù zuòwéi jí wénxué, biǎoyǎn yǔ wǔměi yú yītǐ de zōnghé yìshù xíngshì, qí zuì kòurén-xīnxuán de yìshù mèilì mòguò yú diēdàng-qǐfú de xìjù zhānglì.', 'Kịch nghệ với tư cách là hình thức nghệ thuật tổng hợp hội tụ văn học, diễn xuất và mỹ thuật sân khấu, sức lôi cuốn rung động lòng người nhất không gì qua được kịch tính thăng trầm biến hóa khôn lường.'), ('剧作家擅长在逼仄的时空维度内精心构设尖锐的价值对立与性格冲突，让人物命运在两难抉择中经受严苛拷问。', 'Jùzuòjiā shàncháng zài bīzè de shíkōng wéidù nèi jīngxīn gòushè jiānruì de jiàzhí duìlì yǔ xìnggé chōngtū, ràng rénwù mìngyùn zài liǎngnán juézé zhōng jīngshòu yánkē kǎowèn.', 'Nhà viết kịch tài ba khéo léo kiến thiết thế đối lập gay gắt về giá trị và xung đột tính cách trong chiều kích không gian hạn hẹp, đẩy số phận nhân vật vào vòng thử thách khắc nghiệt giữa thế lưỡng nan.'), ('悬念的铺垫、误会的层层递进以及突转与高潮的爆发，牢牢牵引着观众的情感脉搏并在剧场中凝聚成巨大的期待视野。', 'Xuánniàn de pūdiàn, wùhuì de céngcéng dìjìn yǐjí tūzhuǎn yǔ gāocháo de bàofā, láoláo qiānyǐn zhe guānzhòng de qínggǎn màibó bìng zài jùchǎng zhōng níngjù chéng jùdà de qīdài shìyě.', 'Nghệ thuật cài cắm nỗi hồi hộp, sự dồn dập tầng tầng lớp lớp của hiểu lầm cùng những bước ngoặt bất ngờ và bùng nổ cao trào đã nắm giữ chặt chẽ mạch đập cảm xúc của khán giả trong rạp.'), ('亚里士多德在《诗学》中深刻阐明，悲剧通过引发观众内心的怜悯与恐惧，最终达成洗涤心灵污垢的卡塔西斯宣泄净化效应。', 'Yàlǐshìduōdé zài 《Shīxué》 zhōng shēnkè chǎnmíng, bēijù tōngguò yǐnfā guānzhòng nèixīn de liánmǐn yǔ kǒngjù, zuìzhōng dáchéng xǐdí xīnlíng wūgòu de kǎtǎxīsī xuānxiè jìnghuà xiàoyìng.', "Aristotle trong 'Thi học' đã làm sáng tỏ sâu sắc rằng, bi kịch thông qua việc khơi gợi lòng trắc ẩn và sự sợ hãi trong tâm khán giả, rốt cuộc đạt tới hiệu ứng thanh lọc tâm hồn (Catharsis) gột rửa bụi trần."), ('当舞台大幕缓缓落下，观众不仅收获了审美的极致震撼，更在对悲欢离合的深刻省思中重获生命的纯粹与力量。', 'Dāng wǔtái dàmù huǎnhuǎn luòxià, guānzhòng bùjǐn shōuhuò le shěnměi de jízhì zhènhàn, gèng zài duì bēihuān-líhé de shēnkè xǐngsī zhōng chónghuò shēngmìng de chúncuì yǔ lìliàng.', 'Khi tấm màn nhung sân khấu từ từ khép lại, khán giả không chỉ thu hoạch cú sốc thẩm mỹ tột độ, mà còn tìm lại sự thuần khiết và sức mạnh sinh mệnh trong nỗi suy tư sâu xa về những hợp tan ly biệt.')], [('Yếu tố cuốn hút nhất tạo nên sức mạnh của tác phẩm kịch nghệ là gì?', ['Sân khấu trang hoàng đắt tiền', 'Kịch tính thăng trầm biến hóa cùng sự đối lập gay gắt của tính cách và số phận nhân vật', 'Trang phục biểu diễn sặc sỡ'], 1, 'Trong bài có câu: 最扣人心弦的艺术魅力莫过于跌宕起伏的戏剧张力，构设尖锐的价值对立与性格冲突.'), ("Khái niệm 'Catharsis' (卡塔西斯) trong 'Thi học' của Aristotle có nghĩa là gì?", ['Tiếng cười sảng khoái thông thường', 'Sự thanh lọc giải tỏa tâm hồn thông qua việc khơi gợi lòng trắc ẩn và nỗi sợ hãi', 'Sự tức giận với nhân vật phản diện'], 1, 'Trong câu có viết: 通过引发观众内心的怜悯与恐惧，最终达成洗涤心灵污垢的卡塔西斯宣泄净化效应.'), ('Dư âm lớn nhất đọng lại trong tâm khán giả khi tấm màn kịch buông xuống là gì?', ['Sự mệt mỏi buồn ngủ', 'Cú sốc thẩm mỹ tột đỉnh và tìm lại sức mạnh thuần khiết qua chiêm nghiệm nhân sinh', 'Quên ngay nội dung vở kịch'], 1, 'Trong câu cuối có viết: 不仅收获了审美的极致震撼，更在深刻省思中重获生命的纯粹与力量.')]),
    (40, '自动驾驶算法中的道德两难困境', 'Thế lưỡng nan về luân lý của thuật toán xe tự hành', 'ai_ethics', 'Triết học & Trí tuệ nhân tạo', '🚗', 5, 'Khi chiếc xe tự lái đối mặt tình huống tai nạn không thể tránh khỏi: Ai là người quyết định sinh mạng của con người?', [('以深度神经网络与多传感器融合为驱动的自动驾驶技术，正在以惊人的速度驶入现实交通生活场景。', 'Yǐ shēndù shénjīng wǎngluò yǔ duōchuángǎnqì rónghé wéi qūdòng de zìdòng jiàshǐ jìshù, zhèngzài yǐ jīngrén de sùdù shǐrù xiànshí jiāotōng shēnghuó chǎngjǐng.', 'Công nghệ lái tự động được dẫn dắt bởi mạng nơ-ron học sâu và dung hợp đa cảm biến đang lăn bánh vào các kịch bản đời sống giao thông thực tế với tốc độ kinh ngạc.'), ('尽管统计数据表明机器视觉与极速算法反应能显著降低由疲劳分心带来的人为交通事故率，但技术无法彻底消除极端险情。', 'Jǐnguǎn tǒngjì shùjù biǎomíng jīqì shìjué yǔ jísù suànfǎ fǎnyìng néng xiǎnzhù jiàngdī yóu píláo fēnxīn dàilái de rénwéi jiāotōng shìgù lǜ, dàn jìshù wúfǎ chèdǐ xiāochú jíduān xiǎnqíng.', 'Dẫu dữ liệu thống kê chỉ ra rằng thị giác máy tính và tốc độ phản ứng thuật toán cực nhanh có thể giảm rõ rệt tỷ lệ tai nạn do con người mệt mỏi xao nhãng, nhưng công nghệ không thể xóa sạch hoàn toàn các tình huống nguy hiểm cực đoan.'), ('在经典的电车难题变体场景中，当车辆遭遇突发失控且碰撞不可避免时，算法应当优先保护车内乘员还是避让路面行人？', 'Zài jīngdiǎn de diànchē nántí biàntǐ chǎngjǐng zhōng, dāng chēliàng zāoyù tūfā shīkòng qiě pèngzhuàng bùkě bìmiǎn shí, suànfǎ yīngdāng yōuxiān bǎohù chēnèi chéngyuán háishì bìràng lùmiàn xíngrén?', 'Trong kịch bản biến thể của bài toán xe goòng kinh điển, khi xe gặp sự cố mất lái đột ngột và va chạm là không thể tránh khỏi, thuật toán nên ưu tiên bảo vệ hành khách trong xe hay tránh người đi bộ qua đường?'), ('如果将功利主义的伤亡最小化原则写入代码，是否意味着在某些特殊情况下算法会自动将守规避险者推向被牺牲的深渊？', 'Rúguǒ jiāng gōnglì zhǔyì de shāngwáng zuìxiǎohuà yuánzé xiěrù dàimǎ, shìfǒu yìwèizhe zài mǒuxiē tèshū qíngkuàng xià suànfǎ huì zìdòng jiāng shǒuguī bìxiǎnzhě tuī xiàng bèi xīshēng de shēnyuān?', 'Nếu đưa nguyên tắc tối thiểu hóa thương vong của chủ nghĩa công lợi vào dòng code, liệu có đồng nghĩa với việc trong một số trường hợp thuật toán sẽ tự động đẩy người tuân thủ luật lệ vào chỗ bị hy sinh?'), ('自动驾驶的伦理破局不仅是纯粹的工程数学优化问题，更考验着人类社会的法理智慧、公众信任与道德底线重构。', 'Zìdòng jiàshǐ de lúnlǐ pòjú bùjǐn shì chúncuì de gōngchéng shùxué yōuhuà wèntí, gèng kǎoyàn zhe rénlèi shèhuì de fǎlǐ zhìhuì, gōngzhòng xìnrèn yǔ dàodé dǐxiàn chónggòu.', 'Phá vỡ thế bế tắc đạo đức của xe tự lái không đơn thuần là bài toán tối ưu hóa toán học kỹ thuật, mà còn thử thách sâu sắc trí tuệ pháp lý, niềm tin của công chúng và sự tái định vị lằn ranh đạo đức của xã hội loài người.')], [("Tình huống nan giải kiểu 'bài toán xe goòng' mà xe tự lái đối mặt là gì?", ['Xe hết xăng giữa đường', 'Khi tai nạn không thể tránh khỏi, thuật toán nên ưu tiên bảo vệ hành khách trên xe hay người đi bộ bên ngoài', 'Không kết nối được wifi'], 1, 'Trong bài có câu: 碰撞不可避免时，算法应当优先保护车内乘员还是避让路面行人？'), ('Nghịch lý đạo đức nảy sinh khi lập trình giảm thiểu tối đa thương vong là gì?', ['Không ai mua xe nữa', 'Có thể dẫn đến việc thuật toán hy sinh người tuân thủ luật lệ một cách vô tình', 'Xe không thể khởi động'], 1, 'Trong câu có viết: 是否意味着在某些特殊情况下算法会自动将守规避险者推向被牺牲的深渊？'), ('Bản chất của việc giải quyết đạo đức cho thuật toán xe tự lái là gì?', ['Chỉ là việc sửa vài dòng code', 'Bài toán thử thách trí tuệ pháp lý xã hội, niềm tin công chúng và lằn ranh luân lý con người', 'Không cần quan tâm giải quyết'], 1, 'Trong câu cuối có viết: 不仅是纯粹的工程数学优化问题，更考验着法理智慧、公众信任与道德底线重构.')]),
    (41, '古代水利工程的生态智慧', 'Trí tuệ sinh thái trong các công trình thủy lợi cổ đại Trung Hoa', 'ancient_hydraulics', 'Kỹ thuật cổ đại', '🌊', 5, "Đô Giang Yển hơn hai nghìn năm trước: Triết lý 'thuận dòng thuận thế', không đắp đập ngăn sông mà biến thủy tai thành nguồn thủy lợi trù phú.", [('坐落于成都平原岷江之上的都江堰水利工程，历经两千两百余年风雨洗礼，至今依然润泽着天府之国的广袤良田。', 'Zuòluò yú Chéngdū píngyuán Mínjiāng zhī shàng de Dōujiāngyàn shuǐlì gōngchéng, lìjīng liǎng qiān liǎng bǎi yú nián fēngyǔ xǐlǐ, zhìjīn yīrán rùnzé zhe Tiānfǔ-zhī-guó de guǎngmào liángtián.', 'Công trình thủy lợi Đô Giang Yển tọa lạc trên sông Dân Giang vùng đồng bằng Thành Đô, trải qua hơn 2.200 năm mưa gió thử thách, đến nay vẫn tưới mát những cánh đồng màu mỡ của vùng đất Thiên Phủ.'), ('战国时期蜀郡太守李冰父子摒弃了筑高坝死堵洪水的蛮干做法，创造性地确立了乘势利导、因时制宜的无坝引水科学构想。', 'Zhànguó shíqī Shǔjùn tàishǒu Lǐ Bīng fùzǐ bǐngqì le zhù gāobà sǐ dǔ hóngshuǐ de mángàn zuòfǎ, chuàngzàoxìng de quèlì le chéngshì-lìdǎo, yīnshí-zhìyí de wúbà yǐnshuǐ kēxué gòuxiǎng.', 'Thời Chiến Quốc, hai cha con thái thú quận Thục Lý Băng đã gạt bỏ cách làm đắp đập cao chặn đứng dòng lũ bừa bãi, sáng tạo xác lập ý tưởng khoa học dẫn nước không đập thuận thế tự nhiên.'), ('鱼嘴分水堤巧妙实现四六分水，飞沙堰利用水流离心力高效排沙泄洪，宝瓶口则如咽喉般精准调控进水流量。', 'Yúzuǐ fēnshuǐdī qiǎomiào shíxiàn sì-liù fēnshuǐ, Fēishāyàn lìyòng shuǐliú líxīnlì gāoxiào páishā xièhóng, Bǎopíngkǒu zé rú yānhóu bān jīngzhǔn tiáokòng jìnshuǐ liúliàng.', 'Đê phân dòng Miệng Cá khéo léo chia dòng nước theo tỷ lệ 4:6, đập Phi Sa tận dụng lực ly tâm dòng chảy để xả cát thoát lũ, trong khi họng Bình Bảo Bối chuẩn xác điều tiết lưu lượng nước.'), ('这一顺应水性、自然调控的精妙工程体系，彻底消除了成都平原非旱即涝的千古灾害，化害为利、造福苍生。', 'Zhè yí shùnyìng shuǐxìng, zìrán tiáokòng de jīngmiào gōngchéng tǐxì, chèdǐ xiāochú le Chéngdū píngyuán fēi hàn jí lào de qiāngǔ zāihài, huà hài wéi lì, zàofú cāngshēng.', 'Hệ thống công trình tinh xảo thuận theo dòng nước và tự điều tiết này đã xóa bỏ hoàn toàn đại họa hạn hán ngập lụt ngàn năm của đồng bằng Thành Đô, biến nguy thành an, mang lại ấm no cho muôn dân.'), ('都江堰不仅是古代水利科技的巅峰杰作，更是道法自然、天人合一生态哲学在工程建设中的光辉典范。', 'Dōujiāngyàn bùjǐn shì gǔdài shuǐlì kējì de diānfēng jiézuò, gèng shì dào fǎ zìrán, tiānrén-héyī shēngtài zhéxué zài gōngchéng jiànshè zhōng de guānghuī diǎnfàn.', 'Đô Giang Yển không chỉ là kiệt tác đỉnh cao của kỹ thuật thủy lợi cổ đại, mà còn là tấm gương rực rỡ của triết học sinh thái Đạo pháp tự nhiên, Thiên nhân hợp nhất trong xây dựng công trình.')], [('Điểm sáng tạo vượt bậc của Lý Băng khi xây dựng Đô Giang Yển là gì?', ['Xây đập bê tông ngăn sông hoàn toàn', 'Thuận dòng thuận thế, dẫn nước tự nhiên không cần đắp đập chặn nước', 'Dời cả dòng sông đi nơi khác'], 1, 'Trong bài có câu: 摒弃了筑高坝死堵洪水的蛮干做法，确立了乘势利导、因时制宜的无坝引水构想.'), ('Bộ ba công trình nòng cốt của Đô Giang Yển gồm những bộ phận nào?', ['Ống dẫn nước ngầm', 'Đê Miệng Cá (鱼嘴), đập Phi Sa (飞沙堰) và họng Bình Bảo Bối (宝瓶口)', 'Hồ chứa nhân tạo lớn'], 1, 'Trong câu có viết: 鱼嘴分水堤巧妙实现四六分水，飞沙堰排沙泄洪，宝瓶口调控流量.'), ('Triết lý sâu sắc nhất được thể hiện qua công trình thủy lợi ngàn năm này là gì?', ['Chinh phục và khuất phục sức mạnh tự nhiên', 'Đạo pháp tự nhiên, Thiên nhân hợp nhất - con người hòa hợp cùng quy luật thiên nhiên', 'Tiết kiệm chi phí nhân công'], 1, 'Trong câu cuối có viết: 更是道法自然、天人合一生态哲学在工程建设中的光辉典范.')]),
    (42, '复杂系统科学与混沌秩序之美', 'Khoa học hệ thống phức tạp và vẻ đẹp của trật tự trong hỗn loạn', 'complex_systems', 'Khoa học lý thuyết', '🌀', 5, 'Cánh bướm vỗ ở Brazil có thể tạo nên lốc xoáy ở Texas: Khám phá trật tự sâu sắc đằng sau những hiện tượng phi tuyến tính.', [('牛顿经典力学曾构筑了一个钟表般确定、可严密预测的机械宇宙图景，然而真实自然界却远比线性方程繁复迷人。', "Niúdùn jīngdiǎn lìxué céng gòuzhù le yí gè zhōngbiǎo bān quèdìng, kě yánmì yùcè de jīxiè yǔzhòu tújǐng, rán'ér zhēnshí zìránjiè què yuǎn bǐ xiànxìng fāngchéng fánfù mírén.", 'Cơ học cổ điển Newton từng kiến tạo một bức tranh vũ trụ cơ học xác định và dự đoán chuẩn xác tựa như cỗ đồng hồ quả lắc, thế nhưng giới tự nhiên thực tế lại phức tạp và mê hoặc hơn các phương trình tuyến tính rất nhiều.'), ('气象学家洛伦茨在数值模拟天气演化时意外发现，极微小的初始参数舍入误差都会在级联放大后引发截然不同的结果。', 'Qìxiàngxuéjiā Luòlúncí zài shùzhí mónǐ tiānqì yǎnhuà shí yìwài fāxiàn, jí wēixiǎo de chūshǐ cānshù shě-rù wùchā dōu huì zài jílián fàngdà hòu yǐnfā jiérán-bùtóng de jiéguǒ.', 'Nhà khí tượng học Lorenz khi mô phỏng số sự biến đổi thời tiết đã tình cờ phát hiện ra rằng, ngay cả sai số làm tròn thông số ban đầu cực nhỏ cũng có thể dẫn đến kết quả hoàn toàn trái ngược sau khi phóng đại liên tiếp.'), ('这种著名的蝴蝶效应生动揭示了非线性复杂系统的内在特征：对初始条件的极度敏感性与长期行为的内在不可预测性。', 'Zhè zhǒng zhùmíng de húdié xiàoyìng shēngdòng jiēshì le fēi-xiànxìng fùzá xìtǒng de nèizài tèzhēng: duì chūshǐ tiáojiàn de jídù mǐngǎnxìng yǔ chángqī xíngwéi de nèizài bùkě-yùcèxìng.', 'Hiệu ứng cánh bướm trứ danh này đã làm sáng tỏ sinh động đặc tính nội tại của các hệ thống phức tạp phi tuyến: sự nhạy cảm tột độ với điều kiện ban đầu và tính bất khả dự đoán nội tại về hành vi lâu dài.'), ('然而在看似杂乱无章的混沌表象之下，奇异吸引子却以分形几何的绝美对称性，勾勒出深层次的动态秩序与规律。', "Rán'ér zài kànsì záluàn-wúzhāng de hùndùn biǎoxiàng zhī xià, qíyì xīyǐnzǐ què yǐ fēnxíng jǐhé de juéměi duìchènxìng, gōulè chū shēncéngcì de dòngtài zhìxù yǔ guīlǜ.", "Thế nhưng ẩn dưới vẻ ngoài hỗn độn tưởng chừng bừa bãi ấy, các 'hấp dẫn tử kỳ dị' (Strange Attractor) lại phác họa nên trật tự và quy luật vận động sâu xa với vẻ đẹp đối xứng tuyệt mỹ của hình học phân dạng (Fractal)."), ('从细胞代谢、神经网络到生态平衡与金融市场，复杂性科学为人类洞察生生不息的宇宙万象提供了崭新的认知棱镜。', 'Cóng xìbāo dàixiè, shénjīng wǎngluò dào shēngtài pínghéng yǔ jīnróng shìchǎng, fùzáxìng kēxué wèi rénlèi dòngchá shēngshēng-bùxī de yǔzhòu wànxiàng tígōng le zhǎnxīn de rènzhī léngjìng.', 'Từ chuyển hóa tế bào, mạng lưới thần kinh cho tới cân bằng sinh thái và thị trường tài chính, khoa học tính phức tạp đã cung cấp lăng kính nhận thức hoàn toàn mới cho nhân loại thấu suốt vạn vật vũ trụ sinh sôi bất tận.')], [("Hiện tượng 'Hiệu ứng cánh bướm' (蝴蝶效应) trong hệ thống phi tuyến biểu thị điều gì?", ['Mọi việc luôn diễn ra hoàn toàn tĩnh lặng', 'Sự nhạy cảm tột độ với điều kiện ban đầu: sai số nhỏ ban đầu có thể gây ra kết quả biến đổi khổng lồ', 'Bướm có thể tạo ra gió bão thật sự'], 1, 'Trong bài có câu: 对初始条件的极度敏感性与长期行为的内在不可预测性.'), ('Điều bất ngờ ẩn giấu đằng sau sự hỗn loạn bề ngoài của tự nhiên là gì?', ['Không có quy luật nào', 'Trật tự sâu xa và tính đối xứng tuyệt mỹ thể hiện qua hình học phân dạng (phân hình)', 'Mọi thứ sẽ sụp đổ'], 1, 'Trong câu có viết: 奇异吸引子以分形几何的绝美对称性，勾勒出深层次的动态秩序与规律.'), ('Tầm vóc của khoa học hệ thống phức tạp đối với nhận thức con người là gì?', ['Cung cấp lăng kính nhận thức hoàn toàn mới để hiểu về tế bào, thần kinh, sinh thái và kinh tế', 'Phủ nhận toàn bộ toán học', 'Chỉ áp dụng cho dự báo thời tiết'], 0, 'Trong câu cuối có viết: 为人类洞察生生不息的宇宙万象提供了崭新的认知棱镜.')]),
    (43, '知识产权保护与全球创新激励', 'Bảo hộ sở hữu trí tuệ và cơ chế thúc đẩy đổi mới toàn cầu', 'intellectual_property', 'Luật pháp & Kinh tế', '⚖️', 5, 'Cân bằng giữa độc quyền bằng sáng chế và phổ biến tri thức vì lợi ích công cộng là bài toán pháp lý then chốt của kỷ nguyên sáng tạo.', [('知识产权制度作为市场经济与现代法治的智慧结晶，其本质是通过赋予创新者阶段性的法定垄断权利来激励智力创造。', 'Zhīshi chǎnquán zhìdù zuòwéi shìchǎng jīngjì yǔ xiàndài fǎzhì de zhìhuì jiéjīng, qí běnzhì shì tōngguò fùyǔ chuàngxīnzhě jiēduànxìng de fǎdìng lǒngduàn quánlì lái jīlì zhìlì chuàngzào.', 'Chế định sở hữu trí tuệ với tư cách là kết tinh trí tuệ của kinh tế thị trường và pháp trị hiện đại, bản chất là thông qua việc trao cho người sáng tạo quyền độc quyền theo luật định có thời hạn để khích lệ sáng tạo trí tuệ.'), ('高额研发投入的创新药、芯片微架构与前沿算法，唯有在获得严密专利保护的预期下，企业才敢于承担巨大的试错沉没成本。', "Gāo'é yánfā tóurù de chuàngxīnyào, xīnpiàn wēi-jiàgòu yǔ qiányán suànfǎ, wéiyǒu zài huòdé yánmì zhuānlì bǎohù de yùqī xià, qǐyè cái gǎnyú chéngdān jùdà de shìcuò chénmò chéngběn.", 'Thuốc phát minh mới, vi kiến trúc chip và thuật toán tiền phong với vốn đầu tư nghiên cứu khổng lồ chỉ khi có kỳ vọng được bảo vệ bằng sáng chế nghiêm ngặt thì doanh nghiệp mới dám gánh chịu chi phí chìm rủi ro lớn.'), ('然而，过度宽泛的专利封锁与专利流氓的恶意诉讼投机，也容易构筑起高耸的技术壁垒，扼杀后续中小企业的再创新活力。', "Rán'ér, guòdù kuānfàn de zhuānlì fēngsuǒ yǔ zhuānlì liúmáng de èyì sùsòng tóujī, yě róngyì gòuzhù qǐ gāosǒng de jìshù bìlěi, èshā hòuxù zhōng-xiǎo qǐyè de zàichuàngxīn huólì.", "Thế nhưng, việc phong tỏa bằng sáng chế quá rộng rãi cùng những vụ kiện đầu cơ ác ý của các tổ chức 'thực thi bằng sáng chế trá hình' (patent troll) cũng dễ dựng nên bức tường kỹ thuật cao ngút, bóp nghẹt sức sống đổi mới của doanh nghiệp vừa và nhỏ."), ('尤其在面对突发全球公共卫生危机时，如何在原研药企研发激励与欠发达国家仿制药可及性之间取得人道平衡，是一大伦理考验。', 'Yóuqí zài miànduì tūfā quánqiú gōnggòng wèishēng wēijī shí, rúhé zài yuányányàoqǐ yánfā jīlì yǔ qiàn-fādá guójiā fǎngzhìyào kějíxìng zhījiān qǔdé réndào pínghéng, shì yí dà lúnlǐ kǎoyàn.', 'Đặc biệt khi đối mặt với khủng hoảng y tế công cộng toàn cầu đột phát, làm thế nào để đạt được sự cân bằng nhân đạo giữa động lực nghiên cứu của hãng dược gốc và khả năng tiếp cận thuốc generic của các nước kém phát triển là bài toán đạo đức lớn.'), ('构建公正包容、动态平衡的全球知识产权治理体系，才能让保护创新的法治阳光真正普惠全人类福祉。', 'Gòujiàn gōngzhèng bāoróng, dòngtài pínghéng de quánqiú zhīshi chǎnquán zhìlǐ tǐxì, cái néng ràng bǎohù chuàngxīn de fǎzhì yángguāng zhēnzhèng pǔhuì quán rénlèi fúzhǐ.', 'Xây dựng hệ thống quản trị sở hữu trí tuệ toàn cầu công bằng bao dung và cân bằng động mới có thể để ánh sáng pháp quyền bảo vệ đổi mới sáng tạo thực sự mang lại phúc lợi bao trùm cho toàn nhân loại.')], [('Bản chất cốt lõi của chế định sở hữu trí tuệ (知识产权) là gì?', ['Ngăn chặn người khác sử dụng công nghệ mãi mãi', 'Trao quyền độc quyền hợp pháp có thời hạn để bù đắp chi phí và khích lệ sáng tạo trí tuệ', 'Thu thuế bản quyền cho chính phủ'], 1, 'Trong bài có câu: 通过赋予创新者阶段性的法定垄断权利来激励智力创造.'), ('Nguy cơ tiêu cực khi bằng sáng chế bị lạm dụng quá đà là gì?', ['Không ai thèm nghiên cứu nữa', 'Tạo rào cản kỹ thuật quá mức, đầu cơ kiện tụng và bóp nghẹt sức sống đổi mới của doanh nghiệp nhỏ', 'Làm giá sản phẩm rẻ đi'], 1, 'Trong câu có viết: 构筑起高耸的技术壁垒，扼杀后续中小企业的再创新活力.'), ('Bài toán nhân đạo lớn nảy sinh trong khủng hoảng dịch bệnh toàn cầu là gì?', ['Cân bằng giữa quyền lợi sáng chế của hãng dược và khả năng tiếp cận thuốc giá rẻ của các nước nghèo', 'Cấm nhập khẩu thuốc', 'Ép người dân trả giá thuốc cao hơn'], 0, 'Trong câu có viết: 在原研药企研发激励与欠发达国家仿制药可及性之间取得人道平衡.')]),
    (44, '暗物质与宇宙演化模型探秘', 'Giải mã vật chất tối và mô hình tiến hóa vũ trụ', 'dark_matter', 'Vật lý lý thuyết', '🔭', 5, 'Hiện tượng thấu kính hấp dẫn và sự xoay chuyển của các thiên hà hé lộ 85% vật chất trong vũ trụ là những bóng ma vô hình.', [('仰望璀璨夜空，繁星与星系汇聚的绚丽景象令人惊叹，但现代天体物理学却揭示出一个令人不安的事实：人类可见的一切仅占宇宙物质总量的冰山一角。', "Yǎngwàng cuǐcàn yèkōng, fánxīng yǔ xīngxì huìjù de xuànlì jǐngxiàng lìng rén jīngtàn, dàn xiàndài tiāntǐ wùlǐxué què jiēshì chū yí gè lìng rén bù'ān de shìshí: rénlèi kějiàn de yíqiè jǐn zhàn yǔzhòu wùzhì zǒngliàng de bīngshān-yìjiǎo.", 'Ngước nhìn bầu trời đêm rực rỡ, cảnh tượng hoa lệ của muôn vàn vì sao và thiên hà khiến ta kinh ngạc, nhưng vật lý thiên văn hiện đại lại hé lộ một sự thật gây chấn động: tất cả những gì con người nhìn thấy chỉ chiếm một góc tảng băng chìm trong tổng lượng vật chất vũ trụ.'), ('天文学家在观测螺旋星系旋转曲线时发现，星系边缘恒星的旋转速度远高于可见发光物质质量所能提供的引力束缚极限。', 'Tiānwénxuéjiā zài guānxiè luóxuán xīngxì xuánzhuǎn qūxiàn shí fāxiàn, xīngxì biānyuán héngxīng de xuánzhuǎn sùdù yuǎn gāo yú kějiàn fāguāng wùzhì zhìliàng suǒ néng tígōng de yǐnlì shùfù jíxiàn.', 'Các nhà thiên văn khi quan sát đường cong quay của thiên hà xoắn ốc nhận thấy tốc độ quay của các ngôi sao ở rìa thiên hà cao hơn nhiều so với giới hạn lực hấp dẫn mà khối lượng vật chất phát quang nhìn thấy có thể cung cấp.'), ('这一重力反常现象有力证实，宇宙中弥漫着大量不参与电磁相互作用、既不发光也不反光的幽灵物质——暗物质。', 'Zhè yí zhònglì fǎncháng xiànxiàng yǒulì zhèngshí, yǔzhòu zhōng mímàn zhe dàliàng bù cānyù diàncí xiānghù-zuòyòng, jì bù fāguāng yě bù fǎnguāng de yōulíng wùzhì——ànwùzhì.', 'Hiện tượng dị thường trọng lực này chứng minh mạnh mẽ rằng vũ trụ tràn ngập chất ma quái không tham gia tương tác điện từ, không phát sáng cũng không phản xạ ánh sáng: vật chất tối.'), ('在地下数千米极深实验室中利用超高纯度液氙探测器捕捉微弱的反冲信号，是全球科学家直接探测暗物质粒子的最前沿阵地。', 'Zài dìxià shù qiān mǐ jíshēn shíyànshì zhōng lìyòng chāogāochún dù yèxiān tàncèqì bǔzhuō wēiruò de fǎnchōng xìnhào, shì quánqiú kēxuéjiā zhíjiē tàncè ànwùzhì lìzǐ de zuì qiányán zhèndì.', 'Việc sử dụng máy dò xenon lỏng siêu tinh khiết trong các phòng thí nghiệm sâu hàng ngàn mét dưới lòng đất để bắt tín hiệu giật lùi cực yếu là mặt trận tiền phong nhất của các nhà khoa học toàn cầu nhằm dò tìm hạt vật chất tối.'), ('彻底揭开暗物质的真实身份，将彻底改写现行粒子物理学标准模型，引领人类走向对终极物理实在的崭新认知。', 'Chèdǐ jiēkāi ànwùzhì de zhēnshí shēnfèn, jiāng chèdǐ gǎixiě xiànxíng lìzǐ wùlǐxué biāozhǔn móxíng, yǐnlǐng rénlèi zǒuxiàng duì zhōngjí wùlǐ shízài de zhǎnxīn rènzhī.', 'Vén mở hoàn toàn thân phận thực sự của vật chất tối sẽ viết lại căn bản mô hình chuẩn của vật lý hạt hiện hành, dẫn dắt nhân loại tiến tới nhận thức mới về thực tại vật lý tối hậu.')], [('Bằng chứng thiên văn nào khẳng định sự tồn tại của vật chất tối?', ['Mặt trời mọc ở hướng đông', 'Tốc độ quay của các ngôi sao ở rìa thiên hà cao hơn nhiều so với lực hấp dẫn của vật chất nhìn thấy', 'Mặt trăng tròn vào rằm'], 1, 'Trong bài có câu: 星系边缘恒星的旋转速度远高于可见发光物质质量所能提供的引力束缚极限.'), ('Đặc tính vật lý cơ bản của vật chất tối là gì?', ['Có màu đen kịt', 'Không tham gia tương tác điện từ, hoàn toàn không phát sáng và không phản xạ ánh sáng', 'Tự bốc cháy'], 1, 'Trong câu có viết: 不参与电磁相互作用、既不发光也不反光的幽灵物质.'), ('Ý nghĩa khoa học của việc giải mã được vật chất tối là gì?', ['Viết lại hoàn toàn mô hình chuẩn của vật lý hạt và mở ra hiểu biết mới về thực tại vũ trụ', 'Giúp tăng tốc độ bay của máy bay', 'Không làm thay đổi các lý thuyết cũ'], 0, 'Trong câu cuối có viết: 彻底改写现行粒子物理学标准模型，引领人类走向对终极物理实在的崭新认知.')]),
    (45, '现象学哲学对日常生活的观照', 'Chiêm nghiệm đời sống thường nhật qua lăng kính hiện tượng học', 'phenomenology', 'Triết học hiện đại', '📖', 5, "'Trở về với chính bản thân sự vật': Tạm gác định kiến lý thuyết để cảm nhận nguyên vẹn sự sống động của từng khoảnh khắc hiện tiền.", [('现代实证科学倾向于将世界客体化、数据化与抽象化，使人不知不觉中与生动鲜活的原初生活世界渐行渐远。', 'Xiàndài shízèng kēxué qīngxiàng yú jiāng shìjiè kètǐhuà, shùjùhuà yǔ chōuxiànghuà, shǐ rén bùzhī-bùjué zhōng yǔ shēngdòng xiānhuó de yuánchū shēnghuó shìjiè jiànxíng-jiànyuǎn.', 'Khoa học thực chứng hiện đại có xu hướng khách thể hóa, số liệu hóa và trừu tượng hóa thế giới, khiến con người vô tình ngày càng xa rời thế giới đời sống nguyên sơ sinh động và tươi mới.'), ('二十世纪初胡塞尔创立的现象学运动，提出了重回事物本身的光辉口号，呼唤人们悬置既有的理论预设与科学教条。', "Èrshí shìjì chū Húsài'ěr chuànglì de xiànxiàngxué yùndòng, tíchū le chóng huí shìwù běnshēn de guānghuī kǒuhào, hūhuàn rénmen xuánzhì jìyǒu de lǐlùn yùshè yǔ kēxué jiàotiáo.", "Phong trào hiện tượng học do Husserl sáng lập vào đầu thế kỷ 20 đã giương cao khẩu hiệu sáng ngời 'Trở về với chính bản thân sự vật', kêu gọi con người gác lại (epoché) những tiền giả định lý thuyết và giáo điều khoa học sẵn có."), ('通过现象学还原的认知洗礼，我们学会对周围的一切司空见惯之事保持一种初见般的惊异与纯粹直观。', 'Tōngguò xiànxiàngxué huányuán de rènzhī xǐlǐ, wǒmen xuéhuì duì zhōuwéi de yíqiè sīkōng-jiànguàn zhī shì bǎochí yì zhǒng chūjiàn bān de jīngyì yǔ chúncuì zhíguān.', "Thông qua cuộc thanh lọc nhận thức 'quy giản hiện tượng học', ta học cách giữ vững sự kinh ngạc như thuở ban đầu và cái nhìn trực quan thuần khiết trước mọi việc vốn đã quen mắt thường ngày."), ('清晨洒在桌面上的第一缕阳光、指尖触碰咖啡杯时的温热质感，都在这种纯粹体验中焕发出充盈的生命意义。', 'Qīngchén sǎ zài zhuōmiàn shàng de dì-yī lǚ yángguāng, zhǐjiān chùpèng kāfēibēi shí de wēnrè zhìgǎn, dōu zài zhè zhǒng chúncuì tǐyàn zhōng huànfā chū chōngyíng de shēngmìng yìyì.', 'Một vạt nắng sớm đầu tiên trải trên mặt bàn, cảm giác ấm áp khi đầu ngón tay chạm vào tách cà phê, đều bừng sáng ý nghĩa sinh mệnh tròn đầy trong trải nghiệm thuần khiết ấy.'), ('走出机械理性与功利计算的藩篱，重新深情凝视身处于其中的世界，我们才能在喧嚣当下找回栖居诗意的精神家园。', 'Zǒu chū jīxiè lǐxìng yǔ gōnglì jìsuàn de fānlí, chóngxīn shēnqíng níngshì shēnchǔ qízhōng de shìjiè, wǒmen cái néng zài xuānxiāo dāngxià zhǎohuí qījū shīyì de jīngshén jiāyuán.', 'Bước ra khỏi hàng rào duy lý máy móc và toan tính vụ lợi, một lần nữa tha thiết ngắm nhìn thế giới ta đang sống, ta mới có thể tìm lại mái nhà tinh thần cư ngụ đầy thi vị giữa thực tại huyên náo.')], [('Khẩu hiệu nổi tiếng nhất của phong trào hiện tượng học do Husserl khởi xướng là gì?', ['Chinh phục thế giới tự nhiên', 'Trở về với chính bản thân sự vật (重回事物本身)', 'Mọi thứ đều là hư ảo'], 1, 'Trong bài có câu: 提出了重回事物本身的光辉口号，呼唤人们悬置既有的理论预设.'), ("Phương pháp 'quy giản hiện tượng học' (现象学还原) giúp con người đạt được điều gì?", ['Quên hết mọi ký ức', 'Gác lại định kiến lý thuyết cũ để ngắm nhìn vạn vật quen thuộc với sự kinh ngạc ban sơ và trực quan thuần khiết', 'Tính toán chi phí cuộc sống'], 1, 'Trong câu có viết: 学会对周围司空见惯之事保持一种初见般的惊异与纯粹直观.'), ('Giá trị nhân văn của hiện tượng học đối với đời sống con người hiện đại là gì?', ['Thoát khỏi toan tính máy móc vụ lợi, tìm lại cảm nhận thi vị và ý nghĩa sống trong từng khoảnh khắc hiện tiền', 'Kiếm thêm thu nhập thụ động', 'Trốn tránh xã hội thực tế'], 0, 'Trong câu cuối có viết: 走出机械理性与功利计算的藩篱，在喧嚣当下找回栖居诗意的精神家园.')]),
    (46, '作物种质资源库与粮食安全屏障', 'Ngân hàng giống cây trồng và lá chắn an ninh lương thực', 'food_security', 'Nông học & Di truyền', '🌾', 5, 'Lưu giữ hàng trăm nghìn mẫu hạt giống cây trồng quý hiếm là bảo chứng sống còn cho an ninh lương thực trước dịch bệnh và biến đổi khí hậu.', [('粮食安全是国家经济平稳发展与社会长治久安的压舱石，而优良的作物种质资源则是现代农业创新的芯片。', "Liángshi ānquán shì guójiā jīngjì píngwěn fāzhǎn yǔ shèhuì chángzhì-jiǔ'ān de yāchāngshí, ér yōuliáng de zuòwù zhǒngzhì zīyuán zé shì xiàndài nóngyè chuàngxīn de xīnpiàn.", "An ninh lương thực là tảng đá dằn tàu cho sự phát triển ổn định kinh tế và thái bình thịnh trị lâu dài của quốc gia, trong khi nguồn giống cây trồng ưu tú chính là con 'chip' đổi mới của nông nghiệp hiện đại."), ('由于现代集约化农业对少数高产品种的大规模单一推广，大量适应极端气候与抗病虫害的古老农家农作物品种正加速消亡。', 'Yóuyú xiàndài jíyuēhuà nóngyè duì shǎoshù gāochǎn pǐnzhǒng de dàguīmó dānyī tuīguǎng, dàliàng shìyìng jíduān qìhòu yǔ kàng bìngchónghài de gǔlǎo nóngjiā nóngzuòwù pǐnzhǒng zhèng jiāsù xiāowáng.', 'Do nền nông nghiệp thâm canh hiện đại mở rộng độc canh quy mô lớn một số ít giống cao sản, rất nhiều giống cây trồng bản địa cổ truyền có khả năng chịu đựng khí hậu khắc nghiệt và kháng sâu bệnh đang chết dần chết mòn.'), ('一旦新型超级病菌突发肆虐或极端干旱降临，单一遗传背景的作物群落极易遭受毁灭性的系统崩溃。', 'Yídàn xīnxíng chāojí bìngjūn tūfā sìnüè huò jíduān gānhàn jiànglín, dānyī yíchuán bèijǐng de zuòwù qúnluò jí yì zāoshòu huǐmièxìng de xìtǒng bēngkuì.', 'Một khi siêu vi khuẩn mới bất ngờ hoành hành hoặc hạn hán cực đoan ập đến, các quần xã cây trồng có nền tảng di truyền đơn điệu rất dễ hứng chịu sự sụp đổ mang tính hủy diệt cả hệ thống.'), ('建立国家级长期作物种质资源库，在恒温恒湿的地下深层妥善保存数十万份野生近缘种与特色地方品种的珍贵种子。', 'Jiànlì guójiājí chángqī zuòwù zhǒngzhì zīyuánkù, zài héngwēn héngshī de dìxià shēncéng tuǒshàn bǎocún shù shí wàn fèn yèshēng jìnyuánzhǒng yǔ tèsè dìfāng pǐnzhǒng de zhēnguì zhǒngzǐ.', 'Xây dựng ngân hàng tài nguyên giống cây trồng dài hạn cấp quốc gia, bảo quản thỏa đáng hàng trăm nghìn mẫu hạt giống quý của các loài họ hàng hoang dã và giống đặc sản địa phương dưới tầng hầm sâu hằng nhiệt hằng ẩm.'), ('深挖这些沉睡种质中的抗逆与优质优异基因，是培育下一代突破性耐旱、抗病、高产新品种的不竭源头活水。', 'Shēnwā zhèxiē chénshuì zhǒngzhì zhōng de kàngnì yǔ yōuzhì yōuyì jīyīn, shì péiyù xià yídài tūpòxìng nàihàn, kàngbìng, gāochǎn xīn pǐnzhǒng de bùjié yuántóu huóshuǐ.', 'Khai thác sâu các gen kháng nghịch và phẩm chất vượt trội trong nguồn giống đang ngủ yên này là dòng nước đầu nguồn bất tận để lai tạo thế hệ giống mới chịu hạn, kháng bệnh và năng suất cao mang tính đột phá.')], [('Mối nguy hiểm của việc canh tác độc canh một vài giống cây trồng cao sản là gì?', ['Không bán được nông sản', 'Đồng nhất di truyền cao khiến cây trồng dễ bị xóa sổ hàng loạt khi dịch bệnh lạ hoặc hạn hán ập đến', 'Tốn quá ít phân bón'], 1, 'Trong bài có câu: 单一遗传背景的作物群落极易遭受毁灭性的系统崩溃.'), ('Ngân hàng giống cây trồng cấp quốc gia có nhiệm vụ gì?', ['Lưu trữ hàng trăm nghìn mẫu hạt giống hoang dã và bản địa quý dưới môi trường bảo quản tối ưu', 'Bán hạt giống ra chợ', 'Xuất khẩu toàn bộ lương thực'], 0, 'Trong câu có viết: 妥善保存数十万份野生近缘种与特色地方品种的珍贵种子.'), ('Ý nghĩa chiến lược của việc bảo tồn giống cây đối với tương lai nông nghiệp là gì?', ['Là nguồn gen bất tận để lai tạo các giống cây trồng mới chống chịu hạn hán, sâu bệnh và bảo đảm an ninh lương thực', 'Để nông dân không cần làm ruộng nữa', 'Chỉ mang tính lưu niệm'], 0, 'Trong câu cuối có viết: 是培育下一代突破性耐旱、抗病、高产新品种的不竭源头活水.')]),
    (47, '空间站微重力环境下的生命科学实验', 'Thí nghiệm khoa học sự sống trong môi trường vi trọng lực vũ trụ', 'space_biology', 'Sinh học vũ trụ', '🛰️', 5, 'Nuôi cấy tinh thể protein, tế bào mô 3D và nghiên cứu lão hóa phi trọng lực trên quỹ đạo mang lại đột phá cho y học mặt đất.', [('围绕地球高速旋转的载人空间站，为人类提供了地面上无论如何也无法模拟的持续微重力极端实验环境。', 'Wéirào dìqiú gāosù xuánzhuǎn de zàirén kōngjiānzhàn, wèi rénlèi tígōng le dìmbiàn shàng wúlùn-rúhé yě wúfǎ mónǐ de chíxù wēizhònglì jíduān shíyàn huánjìng.', 'Trạm vũ trụ có người lái quay quanh Trái đất với tốc độ cao cung cấp môi trường thí nghiệm cực đoan vi trọng lực liên tục mà dưới mặt đất không tài nào mô phỏng được.'), ('在近乎完全失重的特殊物理条件下，流体由于重力驱动的自然对流与沉降现象几乎完全消失，分子扩散成为主导机制。', 'Zài jìnhū wánquán shīzhòng de tèshū wùlǐ tiáojiàn xià, liútǐ yóuyú zhònglì qūdòng de zìrán duìliú yǔ chénjiàng xiànxiàng jīhū wánquán xiāoshī, fēnzǐ kuòsàn chéngwéi zhǔdǎo jīzhì.', 'Trong điều kiện vật lý đặc thù gần như hoàn toàn không trọng lượng, hiện tượng đối lưu tự nhiên và lắng đọng do trọng lực điều khiển của chất lưu gần như biến mất hoàn toàn, khuếch tán phân tử trở thành cơ chế chủ đạo.'), ('科学家在微重力轨道舱内能够培养出生长极为缓慢均匀、晶格缺陷极少的高质量蛋白质晶体，极大助力了新药靶点解析。', 'Kēxuéjiā zài wēizhònglì guǐdàocāng nèi nénggòu péiyǎng chū shēngzhǎng jíqí huǎnmàn jūnyún, jīnggé quēxiàn jí shǎo de gāozhìliàng dànbáizhì jīngtǐ, jídà zhùlì le xīnyào bǎdiǎn jiěxī.', 'Các nhà khoa học trong khoang quỹ đạo vi trọng lực có thể nuôi cấy những tinh thể protein chất lượng cao lớn lên cực kỳ chậm và đều, rất ít khuyết tật mạng tinh thể, trợ lực lớn cho việc phân tích đích thuốc mới.'), ('与此同时，干细胞在空间站中展现出与地面完全不同的三维立体分化行为，为人体器官体外再生开辟了全新路径。', 'Yǔcǐ-tóngshí, gànxìbāo zài kōngjiānzhàn zhōng zhǎnxiàn chū yǔ dìmbiàn wánquán bùtóng de sānwéi lìtǐ fēnhuà xíngwéi, wèi réntǐ qìguān tǐwài zàishēng kāipì le quánxīn lùjìng.', 'Đồng thời, tế bào gốc trong trạm vũ trụ thể hiện hành vi biệt hóa không gian 3 chiều hoàn toàn khác biệt so với mặt đất, mở ra con đường mới cho tái tạo cơ quan người ngoài cơ thể.'), ('太空生命科学研究不仅为未来人类跨星际长途航行筑牢生理安全基石，更以反哺之力造福地球上的广大病患福祉。', 'Tàikōng shēngmìng kēxué yánjiū bùjǐn wèi wèilái rénlèi kuà-xīngjì chángtú hángxíng zhù láo shēnglǐ ānquán jīshí, gèng yǐ fǎnbǔ zhī lì zàofú dìqiú shàng de guǎngdà bìnghuàn fúzhǐ.', 'Nghiên cứu khoa học sự sống trong không gian không chỉ xây chắc nền móng an toàn sinh lý cho các chuyến du hành liên sao dài ngày trong tương lai của loài người, mà còn mang lại lợi ích hỗ trợ điều trị quý giá cho bệnh nhân trên mặt đất.')], [('Điều kiện vật lý độc nhất vô nhị mà trạm vũ trụ mang lại là gì?', ['Nhiệt độ cực cao', 'Môi trường vi trọng lực (không trọng lượng) liên tục, loại bỏ hiện tượng đối lưu và lắng đọng trọng lực', 'Có nhiều oxy hơn mặt đất'], 1, 'Trong bài có câu: 持续微重力极端实验环境，重力驱动的自然对流与沉降现象几乎完全消失.'), ('Ưu thế của việc nuôi cấy tinh thể protein trong môi trường vi trọng lực là gì?', ['Tinh thể mọc rất nhanh', 'Tinh thể lớn chậm, đều đặn, độ hoàn hảo mạng tinh thể cực cao giúp giải mã cấu trúc đích điều trị bệnh', 'Tinh thể biến thành vàng'], 1, 'Trong câu có viết: 晶格缺陷极少的高质量蛋白质晶体，极大助力了新药靶点解析.'), ('Triển vọng ứng dụng của tế bào gốc nuôi trong vũ trụ đối với y học mặt đất là gì?', ['Biệt hóa không gian 3 chiều mở ra cơ hội tái tạo cơ quan nội tạng người ngoài cơ thể', 'Làm chậm nhịp tim con người mãi mãi', 'Không có ứng dụng nào'], 0, 'Trong câu có viết: 展现出完全不同的三维立体分化行为，为人体器官体外再生开辟了全新路径.')]),
    (48, '东方美学中的虚实相生与意境构筑', 'Hư thực tương sinh và sự kiến tạo ý cảnh trong mỹ học phương Đông', 'oriental_poetics', 'Mỹ học truyền thống', '🎋', 5, "Nghệ thuật 'lưu bạch' trong hội họa thủy mặc và thi ca cổ: Nơi khoảng trống không lời đánh thức trí tưởng tượng vô hạn.", [('不同于西方传统绘画对焦点透视与光影体量感的执着再现，东方古典美学更加推崇虚实相生的空灵意境。', 'Bùtóng yú Xīfāng chuántǒng huìhuà duì jiāodiǎn tòushì yǔ guāngyǐng tǐliànggǎn de zhízhuó zàixiàn, dōngfāng gǔdiǎn měixué gèngjiā tuīchóng xū-shí xiāngshēng de kōnglíng yìjìng.', "Khác biệt với hội họa truyền thống phương Tây luôn chú trọng tái hiện phối cảnh hội tụ và cảm giác khối lượng của ánh sáng bóng tối, mỹ học cổ điển phương Đông lại sùng bái ý cảnh thanh thoát của 'Hư thực tương sinh'."), ('在宋代水墨山水画巨幅图卷中，画家往往惜墨如金，于宣纸上大面积保留未着一笔墨痕的纯净空白。', 'Zài Sòng dài shuǐmò shānshuǐhuà jùfú tújuàn zhōng, huàjiā wǎngwǎng xī mò rú jīn, yú xuānzhǐ shàng dà miànjī bǎoliú wèi zháo yì bǐ mòhén de chúnjìng kòngbái.', 'Trong các đại kiệt tác thủy mặc sơn thủy thời Tống, họa gia thường tiếc mực như vàng, lưu lại những khoảng trắng thuần khiết mênh mông không vương một vết mực trên giấy xuyến.'), ('这种独具匠心的留白绝非单纯的视觉空无，而是借无画处皆成妙境的手法，赋予了云海苍茫、江流浩渺的无限想象空间。', 'Zhè zhǒng dújù-jiàngxīn de liúbái jué fēi dānchún de shìjué kōngwú, ér shì jiè wú huà chù jiē chéng miàojìng de shǒufǎ, fùyǔ le yúnhǎi cāngmáng, jiāngliú hàomiǎo de wúxiàn xiǎngxiàng kōngjiān.', "Thủ pháp 'lưu bạch' (chừa khoảng trống) độc đáo này tuyệt đối không phải là sự trống rỗng thị giác đơn thuần, mà là thủ pháp 'nơi không có nét vẽ đều hóa thành cõi diệu', mở ra không gian tưởng tượng vô hạn về biển mây bao la hay dòng sông cuồn cuộn."), ('虚与实、有与无在画卷中相互交织转化，以最简约凝练的笔触，引导观赏者跨越物象表壳、体悟宇宙生生不息的太虚本体。', 'Xū yǔ shí, yǒu yǔ wú zài huàjuàn zhōng xiānghù jiāozhī zhuǎnhuà, yǐ zuì jiǎnyuē níngliàn de bǐchù, yǐndǎo guānshǎngzhě kuàyuè wùxiàng biǎoké, tǐwù yǔzhòu shēngshēng-bùxī de tàixū běntǐ.', 'Hư và thực, có và không đan cài chuyển hóa trong bức họa, dùng nét bút cô đọng giản ước nhất dẫn dắt người thưởng lãm vượt qua lớp vỏ bề ngoài để chiêm nghiệm bản thể thái hư sinh sôi bất tận của vũ trụ.'), ('东方美学中计白当黑的深邃智慧，至今依然为当代设计与现代心灵提供着超然物外的审美滋养与精神呼吸空间。', 'Dōngfāng měixué zhōng jì bái dāng hēi de shēnsuì zhìhuì, zhìjīn yīrán wèi dāngdài shèjì yǔ xiàndài xīnlíng tígōng zhe chāorán-wùwài de shěnměi zīyǎng yǔ jīngshén hūxī kōngjiān.', "Trí tuệ thâm sâu 'tính chỗ trắng cũng quan trọng như nét đen' trong mỹ học phương Đông đến nay vẫn cung cấp dưỡng chất thẩm mỹ và không gian thở tinh thần thanh tao thoát tục cho thiết kế đương đại và tâm hồn con người hôm nay.")], [('Điểm khác biệt cốt lõi giữa tranh thủy mặc phương Đông và hội họa cổ điển phương Tây là gì?', ['Tranh phương Đông dùng nhiều màu sặc sỡ hơn', "Tranh phương Đông đề cao ý cảnh 'hư thực tương sinh' và nghệ thuật để trống (lưu bạch), không phụ thuộc vào tả thực ánh sáng", 'Tranh phương Tây không vẽ con người'], 1, 'Trong bài có câu: 东方古典美学更加推崇虚实相生的空灵意境，大面积保留未着一笔墨痕的纯净空白.'), ("Nghệ thuật 'lưu bạch' (chừa khoảng trống trắng) mang lại hiệu quả thẩm mỹ gì?", ['Khiến bức tranh dở dang', "'Nơi không vẽ đều thành cõi diệu', mở ra không gian tưởng tượng vô hạn về mây trời sông nước", 'Tiết kiệm tiền mực vẽ'], 1, 'Trong câu có viết: 借无画处皆成妙境的手法，赋予了云海苍茫、江流浩渺的无限想象空间.'), ("Nguyên lý 'Kế bạch đương hắc' (计白当黑 - coi khoảng trắng quan trọng như nét đen) dạy cho con người bài học gì?", ['Vẽ thật nhiều chi tiết kín giấy', 'Trí tuệ tinh giản, biết chừa không gian tinh thần thanh thoát và cân bằng giữa hữu hình và vô hình', 'Chỉ dùng giấy trắng'], 1, 'Trong câu cuối có viết: 计白当黑的深邃智慧，提供着超然物外的审美滋养与精神呼吸空间.')]),
    (49, '人口结构转型与健康老龄化战略', 'Chuyển dịch cơ cấu dân số và chiến lược già hóa khỏe mạnh', 'aging_society', 'Xã hội học', '👵', 5, "Xây dựng hệ thống an sinh đa tầng và phát huy kinh nghiệm của người cao tuổi biến 'gánh nặng dân số' thành tài sản xã hội quý giá.", [('全球主要经济体普遍面临生育率持续走低与人均预期寿命延长的双重人口学人口学转变趋势。', 'Quánqiú zhǔyào jīngjìtǐ pǔbiàn miànlín shēngyùlǜ chíxù zǒudī yǔ rénjūn yùqī shòumìng yáncháng de shuāngzhòng rénkǒuxué zhuǎnbiàn qūshì.', 'Các nền kinh tế chủ đạo trên thế giới đều đang đối mặt với xu thế chuyển dịch kép của nhân khẩu học: tỷ lệ sinh giảm liên tục và tuổi thọ bình quân kỳ vọng kéo dài.'), ('劳动力适龄人口规模的逐步缩减与老龄人口抚养比的攀升，对现行的养老保险金收支平衡与公共医疗卫生系统形成了巨大承压。', 'Láodònglì shìlíng rénkǒu guīmó de zhúbù suōjiǎn yǔ lǎolíng rénkǒu fǔyǎngbǐ de pānshēng, duì xiànxíng de yǎnglǎo bǎoxiǎnjīn shōuzhī pínghéng yǔ gōnggòng yīliáo wèishēng xìtǒng xíngchéng le jùdà chéngyā.', 'Quy mô lực lượng lao động trong độ tuổi suy giảm từng bước cùng tỷ lệ phụ dưỡng người già tăng cao đang gây áp lực to lớn lên cân đối thu chi quỹ hưu trí và hệ thống y tế công cộng hiện hành.'), ('然而将人口老龄化机械地视作沉重的社会经济包袱，是一种充满偏见的消极被动视角。', "Rán'ér jiāng rénkǒu lǎolínghuà jīxiè de shì zuò chénzhòng de shèhuì jīngjì bāofu, shì yì zhǒng chōngmǎn piānjiàn de xiāojí bèidòng shìjiǎo.", 'Thế nhưng việc nhìn nhận già hóa dân số một cách máy móc như một gánh nặng kinh tế xã hội trĩu nặng là một góc nhìn thụ động tiêu cực đầy định kiến.'), ('推行健康老龄化与积极老龄化战略，强调通过全生命周期的健康干预，让老年群体保持良好的身心机能与社会参与度。', 'Tuīxíng jiànkāng lǎolínghuà yǔ jījí lǎolínghuà zhànlüè, qiángdiào tōngguò quán shēngmìng zhōuqī de jiànkāng gānyù, ràng lǎonián qúntǐ bǎochí liánghǎo de shēnxīn jīnéng yǔ shèhuì cānyùdù.', "Thực hiện chiến lược 'già hóa khỏe mạnh' và 'già hóa tích cực' nhấn mạnh can thiệp sức khỏe trong suốt vòng đời, giúp người cao tuổi giữ vững thể trạng tốt và mức độ tham gia xã hội năng động."), ('蓬勃兴起的银发经济、社区互助养老以及老年人力资源的弹性开发，完全能够将银发浪潮转化为促进社会繁荣的新引擎。', 'Péngbó xīngqǐ de yínfà jīngjì, shèqū hùzhù yǎnglǎo yǐjí lǎonián rénlì zīyuán de tánxìng kāifā, wánquán nénggòu jiāng yínfà làngcháo zhuǎnhuà wéi cùjìn shèhuì fánróng de xīn yǐnqíng.', 'Nền kinh tế tóc bạc đang phát triển nở rộ, mô hình dưỡng lão tương trợ cộng đồng cùng khai thác linh hoạt nguồn nhân lực cao tuổi hoàn toàn có thể biến làn sóng bạc thành động cơ mới thúc đẩy xã hội phồn vinh.')], [('Xu thế chuyển dịch dân số chung mà các nền kinh tế lớn đang đối mặt là gì?', ['Tỷ lệ sinh tăng vọt', 'Tỷ lệ sinh giảm sút liên tục kết hợp tuổi thọ bình quân kéo dài dẫn tới già hóa dân số', 'Tuổi thọ giảm sút'], 1, 'Trong bài có câu: 生育率持续走低与人均预期寿命延长的双重人口学转变趋势.'), ("Quan điểm tiến bộ về dân số già hóa thay vì coi đó là 'gánh nặng' là gì?", ['Già hóa tích cực và già hóa khỏe mạnh, giúp người già duy trì thể trạng tốt và tiếp tục cống hiến cho xã hội', 'Cách ly người già', 'Cắt giảm hoàn toàn tiền lương hưu'], 0, 'Trong câu có viết: 推行健康老龄化与积极老龄化战略，保持良好的身心机能与社会参与度.'), ('Động lực kinh tế mới nào trỗi dậy từ làn sóng già hóa dân số?', ['Kinh tế người cao tuổi (Kinh tế tóc bạc - 银发经济) và khai thác linh hoạt kinh nghiệm người già', 'Ngành trò chơi điện tử trẻ em', 'Đóng cửa bệnh viện'], 0, 'Trong câu cuối có viết: 蓬勃兴起的银发经济与老年人力资源开发，能转化为促进社会繁荣的新引擎.')]),
    (50, '极地科学考察与全球气候反馈机制', 'Khảo sát khoa học vùng cực và cơ chế phản hồi khí hậu toàn cầu', 'polar_research', 'Khoa học địa cầu', '❄️', 5, 'Các nhà khoa học khoan lõi băng hàng nghìn mét tại Nam Cực để giải mã lịch sử khí hậu hành tinh và dự báo tương lai trái đất.', [('终年被万顷冰雪覆盖的南极内陆高原与北极冰洋，是地球系统中最严酷偏远的极寒生命禁区。', 'Zhōngnián bèi wànqǐng bīngxuě fùgài de Nánjí nèilù gāoyuán yǔ Běijí bīngyáng, shì dìqiú xìtǒng zhōng zuì yánkù piānyuǎn de jíhán shēngmìng jìnjū.', 'Cao nguyên nội lục Nam Cực quanh năm băng tuyết ngút ngàn và Bắc Băng Dương là vùng cấm địa sự sống cực lạnh, khắc nghiệt và xa xôi nhất trên hệ thống Trái Đất.'), ('然而正是这片冰封大陆，如同一个巨大的天然档案库，忠实封存着地球数十万年以来大气成分与气温波动的全部冰芯记录。', "Rán'ér zhèng shì zhè piàn bīngfēng dàlù, rútóng yí gè jùdà de tiānrán dàng'ànkù, zhōngshí fēngcún zhe dìqiú shù shí wàn nián yǐlái dàqì chéngfèn yǔ qìwēn bōdòng de quánbù bīngxīn jìlù.", 'Thế nhưng chính lục địa băng giá này tựa như một kho lưu trữ tự nhiên khổng lồ, trung thực niêm phong toàn bộ hồ sơ lõi băng về thành phần khí quyển và dao động nhiệt độ hàng trăm ngàn năm qua của Trái Đất.'), ('极地科考队员顶着零下数十度的刺骨严寒，成功钻取深达数千米的古老冰芯样本，通过分析深锁其中的微小气泡破译古气候变迁轨迹。', 'Jídì kěkǎoduìyuán dǐng zhe língxià shù shí dù de cìgǔ yánhán, chénggōng zuānqǔ shēn dá shù qiān mǐ de gǔlǎo bīngxīn yàngběn, tōngguò fēnxī shēn suǒ qízhōng de wēixiǎo qìpào pòyì gǔqìhòu biànqiān guǐjì.', 'Các đoàn thám hiểm khoa học vùng cực bất chấp cái lạnh cắt da cắt thịt âm hàng chục độ, đã khoan lấy thành công các mẫu lõi băng cổ sâu hàng ngàn mét, phân tích bọt khí li ti khóa chặt bên trong để giải mã quỹ đạo biến thiên cổ khí hậu.'), ('极地冰盖的反照率衰减与永冻土层融化释放巨量甲烷，正在引发可能加速全球急剧变暖的恶性正反馈循环链条。', 'Jídì bīnggài de fǎnzhàolǜ shuāijiǎn yǔ yǒngdòngtǔcéng rónghuà shìfàng jùliàng jiǎwán, zhèng yǐnfā kěnéng jiāsù quánqiú jíjù biànnuǎn de èxìng zhèng fǎnkuì xúnhuán liàntiáo.', 'Sự suy giảm suất phản chiếu của dải băng cực và sự tan rã của tầng đất đóng băng vĩnh cửu giải phóng lượng khí methane khổng lồ đang kích hoạt chuỗi vòng lặp phản hồi dương nguy hiểm có thể làm ấm lên toàn cầu tăng tốc dữ dội.'), ('立足极地科考的最前沿窗口，人类才能以前瞻性的科学眼光准确预判地球气候临界点，守护这颗蓝色星球的永恒生机。', 'Lìzú jídì kěkǎo de zuì qiányán chuāngkǒu, rénlèi cái néng yǐ qiánzhānxìng de kēxué yǎnguāng zhǔnquè yùpàn dìqiú qìhòu línjièdiǎn, shǒuhù zhè kē lánsè xīngqiú de yǒnghéng shēngjī.', 'Đứng vững tại cửa sổ tiền tiêu của khảo sát vùng cực, nhân loại mới có thể dùng tầm nhìn khoa học tiên phong dự báo chính xác các điểm giới hạn bùng nổ khí hậu Trái Đất, che chở sinh khí vĩnh hằng cho hành tinh xanh này.')], [('Lõi băng cổ (冰芯) được khoan từ đáy băng Nam Cực đóng vai trò như thế nào?', ['Là nước đá giải khát', 'Như kho lưu trữ tự nhiên niêm phong thành phần khí quyển và biến đổi khí hậu hàng trăm ngàn năm qua', 'Không có giá trị khoa học'], 1, 'Trong bài có câu: 如同一个巨大的天然档案库，忠实封存着数十万年以来大气成分与气温波动的冰芯记录.'), ("Cơ chế 'phản hồi dương nguy hiểm' (恶性正反馈) nào ở vùng cực có thể đẩy nhanh ấm lên toàn cầu?", ['Cây cối mọc quá nhiều', 'Băng tan làm giảm độ phản chiếu ánh sáng và đất đóng băng vĩnh cửu tan làm thoát khí methane ồ ạt', 'Gió thổi mạnh hơn'], 1, 'Trong câu có viết: 反照率衰减与永冻土层融化释放巨量甲烷，引发加速全球急剧变暖的恶性正反馈循环.'), ('Mục tiêu chiến lược tối cao của công tác khảo sát khoa học vùng cực là gì?', ['Dự báo chuẩn xác các điểm giới hạn bùng nổ khí hậu Trái Đất để bảo vệ hành tinh xanh', 'Khai thác mỏ than dưới lòng đất', 'Xây dựng các khu du lịch sang trọng'], 0, 'Trong câu cuối có viết: 准确预判地球气候临界点，守护这颗蓝色星球的永恒生机.')]),
]
